// SM-2 Algorithm
function sm2(quality: number, prev: { ease_factor: number; interval_days: number; repetitions: number }) {
  let { ease_factor, interval_days, repetitions } = prev;
  if (quality < 3) {
    repetitions = 0;
    interval_days = 1;
  } else {
    if (repetitions === 0) interval_days = 1;
    else if (repetitions === 1) interval_days = 6;
    else interval_days = Math.round(interval_days * ease_factor);
    repetitions += 1;
  }
  ease_factor = Math.max(1.3, ease_factor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)));
  const next_review_at = new Date(Date.now() + interval_days * 86400000).toISOString();
  return { ease_factor, interval_days, repetitions, next_review_at, last_reviewed_at: new Date().toISOString() };
}

const qualityMap = [
  { label: "Again", quality: 1, color: "bg-destructive text-destructive-foreground" },
  { label: "Hard", quality: 2, color: "bg-warning text-warning-foreground" },
  { label: "Good", quality: 4, color: "bg-primary text-primary-foreground" },
  { label: "Easy", quality: 5, color: "bg-success text-success-foreground" },
];

export default function Flashcards() {
  const { user } = useAuth();
  const { toast } = useToast();
  const { failure, report } = useLoadFailure("your flashcard sets");
  const [sets, setSets] = useState<any[]>([]);
  const [topics, setTopics] = useState<any[]>([]);
  const [levelById, setLevelById] = useState<Record<string, string>>({});
  const [filter, setFilter] = useState("all");
  const [studySetId, setStudySetId] = useState<string | null>(null);
  const [studyCards, setStudyCards] = useState<any[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [progressMap, setProgressMap] = useState<Record<string, any>>({});
  const [dueCount, setDueCount] = useState<Record<string, number>>({});
  const [studyComplete, setStudyComplete] = useState(false);

  const loadSets = useCallback(async () => {
    const [setsRes, topicsRes, levelsRes] = await Promise.all([
      supabase.from("flashcard_sets").select("*, topics(name), flashcards(id)").order("created_at", { ascending: false }),
      supabase.from("topics").select("*").order("sort_order"),
      supabase.from("subject_levels").select("id, level"),
    ]);
    if (setsRes.error || topicsRes.error || levelsRes.error) {
      report(setsRes.error ?? topicsRes.error ?? levelsRes.error);
      return;
    }
    setSets(setsRes.data ?? []);
    setTopics(topicsRes.data ?? []);
    const lv: Record<string, string> = {};
    (levelsRes.data ?? []).forEach((l) => { lv[l.id] = l.level; });
    setLevelById(lv);
  }, [report]);

  // Load due counts per set
  const loadDueCounts = useCallback(async () => {
    if (!user) return;
    const { data: progress, error: progressError } = await supabase.from("flashcard_progress").select("flashcard_id, next_review_at").eq("user_id", user.id);
    if (progressError) { report(progressError); return; }
    const now = new Date();
    const dueMap: Record<string, boolean> = {};
    (progress ?? []).forEach((p) => {
      if (new Date(p.next_review_at) <= now) dueMap[p.flashcard_id] = true;
    });

    const { data: allCards, error: allCardsError } = await supabase.from("flashcards").select("id, set_id");
    if (allCardsError) { report(allCardsError); return; }
    const reviewed = new Set((progress ?? []).map((p) => p.flashcard_id));
    const counts: Record<string, number> = {};
    (allCards ?? []).forEach((c) => {
      // Due if never reviewed OR next_review_at is past
      if (!reviewed.has(c.id) || dueMap[c.id]) {
        counts[c.set_id] = (counts[c.set_id] || 0) + 1;
      }
    });
    setDueCount(counts);
  }, [user, report]);

  useEffect(() => { loadSets(); loadDueCounts(); }, [loadSets, loadDueCounts]);

  const startStudy = async (setId: string) => {
    if (!user) return;
    const { data: cards, error: cardsError } = await supabase.from("flashcards").select("*").eq("set_id", setId).order("sort_order");
    const { data: prog, error: progError } = await supabase.from("flashcard_progress").select("*").eq("user_id", user.id);
    // Without this the deck came back empty and tapping a set did nothing.
    if (cardsError || progError) {
      toast({
        title: "Couldn't open that set",
        description: loadFailureMessage("these flashcards", cardsError ?? progError),
        variant: "destructive",
      });
      return;
    }
    const pMap: Record<string, any> = {};
    (prog ?? []).forEach((p) => { pMap[p.flashcard_id] = p; });
    setProgressMap(pMap);

    // Filter to due cards (unreviewed or next_review_at <= now)
    const now = new Date();
    const dueCards = (cards ?? []).filter((c) => {
      const p = pMap[c.id];
      return !p || new Date(p.next_review_at) <= now;
    });

    setStudyCards(dueCards.length > 0 ? dueCards : cards ?? []);
    setStudySetId(setId);
    setCurrentIdx(0);
    setFlipped(false);
    setStudyComplete(false);
  };

  const handleRate = async (quality: number) => {
    if (!user) return;
    const card = studyCards[currentIdx];
    const prev = progressMap[card.id] || { ease_factor: 2.5, interval_days: 1, repetitions: 0 };
    const updated = sm2(quality, prev);

    if (progressMap[card.id]) {
      await supabase.from("flashcard_progress").update(updated).eq("user_id", user.id).eq("flashcard_id", card.id);
    } else {
      await supabase.from("flashcard_progress").insert({ user_id: user.id, flashcard_id: card.id, ...updated });
    }
    setProgressMap((m) => ({ ...m, [card.id]: { ...prev, ...updated } }));

    if (currentIdx + 1 < studyCards.length) {
      setCurrentIdx(currentIdx + 1);
      setFlipped(false);
    } else {
      setStudyComplete(true);
      loadDueCounts();
    }
  };

  const { isPreview, hasPaid, loading: planLoading } = usePlanAccess();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  // Topic ids belonging to the subject-levels the student picked. Admins and
  // unauthenticated previews see everything; students only see their picked
  // subjects' topics (and therefore their flashcard sets).
  const pickedTopicIds = useMemo(() => {
    if (isAdminRole || !prefsLoaded) return new Set<string>();
    return new Set(topics.filter((t) => pickedIds.has(t.subject_level_id)).map((t) => t.id));
  }, [topics, pickedIds, isAdminRole, prefsLoaded]);

  // Topics sharing a name across levels ("Thermal Physics" exists at OL and
  // AS) get the level appended so duplicate tabs and badges stay distinct.
  const topicLevelOf = (topicId: string) => {
    const lv = levelById[topics.find((x) => x.id === topicId)?.subject_level_id];
    return lv ? levelLabel(lv) : "";
  };
  const dupTopicNames = useMemo(() => {
    const counts: Record<string, number> = {};
    topics.forEach((t) => { counts[t.name] = (counts[t.name] ?? 0) + 1; });
    return new Set(Object.keys(counts).filter((n) => counts[n] > 1));
  }, [topics]);
  const topicTabLabel = (t) => {
    const lv = topicLevelOf(t.id);
    return dupTopicNames.has(t.name) && lv ? `${t.name} · ${lv}` : t.name;
  };
  const setTopicBadge = (s) => {
    const t = topics.find((x) => x.id === s.topic_id);
    const name = s.topics?.name ?? t?.name;
    if (!name) return null;
    const lv = t ? topicLevelOf(t.id) : "";
    const label = t && dupTopicNames.has(name) && lv ? `${name} · ${lv}` : name;
    return <Badge variant="secondary" className="text-[10px] shrink-0 max-w-full">{label}</Badge>;
  };

  //_visibleTopicIds picks the topic ids used for the per-topic tab triggers.
  const visibleTopicIds = useMemo(() => {
    if (isAdminRole || !prefsLoaded) return topics.map((t) => t.id);
    return topics.filter((t) => pickedIds.has(t.subject_level_id)).map((t) => t.id);
  }, [topics, pickedIds, isAdminRole, prefsLoaded]);

  // Everything the student is entitled to see, scoped to their picked subjects
  // and the active tab. Kept separate from the free-plan slice so the header
  // can say "4 of 8 sets" instead of comparing against all 100 in the catalogue.
  const scopedSets = useMemo(() => sets.filter((s) => {
    // Subject/level gate: only show sets whose topic belongs to a picked
    // subject-level. Admins and the loading/preview states bypass this.
    if (!isAdminRole && prefsLoaded && pickedTopicIds.size > 0) {
      if (!pickedTopicIds.has(s.topic_id)) return false;
    }
    if (filter === "all") return true;
    if (filter === "due") return (dueCount[s.id] ?? 0) > 0;
    return s.topic_id === filter;
  }), [sets, filter, dueCount, isAdminRole, prefsLoaded, pickedTopicIds]);

  const filteredSets = useMemo(() => {
    // Free-plan preview: mirror Lessons — show at most FREE_PREVIEW_LIMIT
    // flashcard sets per subject-level, so a free student picking "Ol Math"
    // never sees Physics/CS sets and only gets a small slice of Ol Math.
    if (!(isPreview && !hasPaid) || scopedSets.length === 0) return scopedSets;
    const byLevel = new Map<string, any[]>();
    for (const s of scopedSets) {
      const tid = s.topic_id;
      const sl = topics.find((t) => t.id === tid)?.subject_level_id;
      if (sl) byLevel.set(sl, (byLevel.get(sl) || []).concat(s));
    }
    const limited = new Set<string>();
    for (const [, items] of byLevel) {
      items.slice(0, FREE_PREVIEW_LIMIT).forEach((s) => limited.add(s.id));
    }
    return scopedSets.filter((s) => limited.has(s.id));
  }, [scopedSets, isPreview, hasPaid, topics, FREE_PREVIEW_LIMIT]);

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any flashcard content is shown. While preferences are still
  // loading we render nothing — never the content itself. Placed after every
  // hook so the early returns never change hook order.
  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/flashcards" />
        <SubjectGate />
      </div>
    );
  }

  // Study mode
  if (studySetId && studyCards.length > 0) {
    const card = studyCards[currentIdx];
    const setInfo = sets.find((s) => s.id === studySetId);

    if (studyComplete) {
      return (
        <div className="cm-study flex flex-col items-center justify-center min-h-[60vh] gap-6">
          <SEOHead path="/flashcards" />
          <CheckCircle2 className="h-16 w-16 text-success" />
          <h2 className="text-2xl font-bold text-foreground">Session Complete!</h2>
          <p className="text-muted-foreground">You reviewed all {studyCards.length} cards in this session.</p>
          <Button onClick={() => { setStudySetId(null); setStudyCards([]); }}>
            <ArrowLeft className="h-4 w-4 mr-2" /> Back to Sets
          </Button>
        </div>
      );
    }

    return (
      <div className="cm-study max-w-xl mx-auto space-y-6">
        <SEOHead path="/flashcards" />
        <div className="flex items-center justify-between">
          <Button variant="ghost" onClick={() => { setStudySetId(null); setStudyCards([]); }}>
            <ArrowLeft className="h-4 w-4 mr-2" /> Back
          </Button>
          <p className="text-sm text-muted-foreground">{currentIdx + 1} / {studyCards.length}</p>
        </div>

        <h2 className="text-lg font-semibold text-foreground">{setInfo?.title}</h2>

        <ManuscriptFlashcard
          eyebrow={flipped ? `Answer · card ${currentIdx + 1} of ${studyCards.length}` : `Question · card ${currentIdx + 1} of ${studyCards.length}`}
          face={flipped ? card.back : card.front}
          hint="Tap to reveal answer"
          flipped={flipped}
          onFlip={() => setFlipped(!flipped)}
        />

        {flipped && (
          <div className="grid grid-cols-4 gap-2">
            {qualityMap.map((q) => (
              <Button key={q.label} className={cn("text-sm font-medium", q.color)} onClick={() => handleRate(q.quality)}>
                {q.label}
              </Button>
            ))}
          </div>
        )}

        {/* Progress bar */}
        <div className="cm-m-progress">
          <div style={{ width: `${((currentIdx + 1) / studyCards.length) * 100}%` }} />
        </div>
      </div>
    );
  }

  // Browse mode
  return (
    <div className="cm-study space-y-6">
      <SEOHead path="/flashcards" />
      <ManuscriptHead
        eyebrow="Spaced repetition"
        title="Flashcards"
        lede={
          isPreview && !hasPaid
            ? `Preview: ${filteredSets.length} of ${scopedSets.length} sets — full access unlocks everything.`
            : "Study with spaced repetition to remember key concepts."
        }
      />

      {failure && <QueryError message={failure} onRetry={() => { window.location.reload(); }} />}

      <Tabs value={filter} onValueChange={setFilter}>
        <TabsList className="flex-wrap h-auto justify-start gap-1 max-w-full overflow-x-auto">
          <TabsTrigger value="all">All Sets</TabsTrigger>
          <TabsTrigger value="due" className="gap-1">
            <Clock className="h-3 w-3" /> Due for Review
          </TabsTrigger>
          {visibleTopicIds.map((tid) => {
            const t = topics.find((x) => x.id === tid);
            return t ? <TabsTrigger key={t.id} value={t.id}>{topicTabLabel(t)}</TabsTrigger> : null;
          })}
        </TabsList>
      </Tabs>
      {filteredSets.length === 0 ? (
        <Card className="border-dashed"><CardContent className="py-12 text-center text-muted-foreground"><Layers className="mx-auto h-10 w-10 mb-3 opacity-40" />{filter === "due" ? "No cards due for review. Great job!" : "No flashcard sets available."}</CardContent></Card>
      ) : (
        <>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filteredSets.map((s) => (
              <Card key={s.id} className="hover:shadow-md transition-shadow group">
                <CardHeader className="pb-2 cursor-pointer" onClick={() => startStudy(s.id)}>
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <CardTitle className="text-base group-hover:text-primary transition-colors">{s.title}</CardTitle>
                    {setTopicBadge(s)}
                  </div>
                  {s.description && <p className="text-xs text-muted-foreground">{s.description}</p>}
                </CardHeader>
                <CardContent className="space-y-2">
                  <div className="flex items-center justify-between text-sm">
                    <span className="text-muted-foreground">{s.flashcards?.length ?? 0} cards</span>
                    {(dueCount[s.id] ?? 0) > 0 && (
                      <Badge className="bg-warning text-warning-foreground text-[10px] gap-1">
                        <RotateCcw className="h-3 w-3" /> {dueCount[s.id]} due
                      </Badge>
                    )}
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="w-full gap-2 text-xs h-7"
                    onClick={async (e) => {
                      e.stopPropagation();
                      const { data: cards, error: exportError } = await supabase.from("flashcards").select("front, back").eq("set_id", s.id).order("sort_order");
                      if (exportError) {
                        toast({
                          title: "Couldn't export this set",
                          description: loadFailureMessage("these flashcards", exportError),
                          variant: "destructive",
                        });
                        return;
                      }
                      if (!cards || cards.length === 0) {
                        toast({ title: "Nothing to export", description: "This set has no cards yet." });
                        return;
                      }
                      try {
                        // Branded, watermarked export: the set title, every card,
                        // and the signed-in account burned into the frame.
                        await exportFlashcardsToPdf(s.title, cards, {
                          owner: user?.email ?? user?.id ?? null,
                        });
                        toast({ title: "Saved", description: "Your flashcard PDF is downloading." });
                      } catch (e) {
                        toast({
                          title: "Couldn't build the PDF",
                          description: e?.message ?? "Please try again.",
                          variant: "destructive",
                        });
                      }
                    }}
                  >
                    <Download className="h-3 w-3" /> Export PDF
                  </Button>
                </CardContent>
              </Card>
            ))}
          </div>
          {isPreview && !hasPaid && filteredSets.length < scopedSets.length && (
            <PreviewLimit
              hiddenCount={scopedSets.length - filteredSets.length}
              what="flashcard sets"
            />
          )}
        </>
      )}
    </div>
  );
}

// Per-lesson notes view.
import { useEffect, useState } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { SEOHead } from "@/components/SEOHead";
import { openProtectedFile } from "@/lib/contentFiles";
import { toast } from "sonner";
import { PreviewBanner } from "@/components/PreviewBanner";
import { SITE_URL } from "@/lib/seoRoutes";
import { WatermarkOverlay } from "@/components/WatermarkOverlay";
import { useNoteProgress, downloadNote, type NoteRow } from "./Notes";
import { FeedbackNudge } from "@/components/FeedbackNudge";
import { LEVEL_LABELS } from "@/lib/subjects";
import { Download, ExternalLink, CheckCircle2, Circle, ArrowLeft, Pencil } from "lucide-react";
import { ContentEditor } from "@/components/admin/ContentEditor";
import { ManuscriptHead, ManuscriptSection } from "@/components/StudyManuscript";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { QueryError } from "@/components/QueryError";
import { useLoadFailure } from "@/hooks/useLoadFailure";

export default function LessonNotes() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const { user, role } = useAuth();
  const { failure, report } = useLoadFailure("this lesson");
  const [reloadKey, setReloadKey] = useState(0);
  const bump = () => setReloadKey((k) => k + 1);
  const [lesson, setLesson] = useState<any>(null);
  const [notes, setNotes] = useState<NoteRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [lessonDone, setLessonDone] = useState(false);
  const { done, toggle } = useNoteProgress();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  useEffect(() => {
    if (!lessonId) return;
    const load = async () => {
      setLoading(true);
      const { data: l, error: lessonError } = await supabase
        .from("lessons")
        .select("id, title, content, topic_id, topics(name, subject_levels(id, level, subjects(name, slug)))")
        .eq("id", lessonId)
        .maybeSingle();
      // Report before bailing, and always settle `loading` — returning here
      // with the spinner still on left the page stuck.
      if (lessonError) { report(lessonError); setLoading(false); return; }
      setLesson(l);
      if (l?.topic_id) {
        const { data, error: notesError } = await supabase
          .from("study_materials")
          .select("id, title, file_url, content, topic_id, material_type")
          .eq("material_type", "notes")
          .eq("topic_id", l.topic_id)
          .order("title");
        if (notesError) { report(notesError); setLoading(false); return; }
        const t = l;
        setNotes((data ?? []).map((m) => ({
          id: m.id,
          title: m.title,
          file_url: m.file_url,
          content: m.content,
          material_type: m.material_type ?? "notes",
          topic_id: m.topic_id,
          topic_name: t.topics?.name ?? "",
          subject_name: t.topics?.subject_levels?.subjects?.name ?? "",
          subject_id: "",
          subject_level_id: t.topics?.subject_levels?.id ?? "",
          level: t.topics?.subject_levels?.level ?? "",
        })));
      }
      if (user) {
        const { data: p, error: progressError } = await supabase
          .from("lesson_progress")
          .select("completed")
          .eq("user_id", user.id)
          .eq("lesson_id", lessonId)
          .maybeSingle();
        if (progressError) { report(progressError); setLoading(false); return; }
        setLessonDone(!!p?.completed);
      }
      setLoading(false);
    };
    load();
  }, [lessonId, user, reloadKey, report]);

  const toggleLesson = async () => {
    if (!user || !lessonId) return;
    const next = !lessonDone;
    setLessonDone(next);
    if (next) {
      await supabase.from("lesson_progress").upsert({
        user_id: user.id, lesson_id: lessonId, completed: true, completed_at: new Date().toISOString(),
      });
    } else {
      await supabase.from("lesson_progress").delete().eq("user_id", user.id).eq("lesson_id", lessonId);
    }
  };

  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  // "Does this reader still have to pick subjects?" is asked in one place.
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead title="Lesson Notes — Clutch Marks" description="View and download the uploaded notes for this lesson." path={`/lessons/${lessonId}/notes`} />
        <SubjectGate />
      </div>
    );
  }

  if (loading) {
    return <div className="space-y-3"><Skeleton className="h-10 w-48" /><Skeleton className="h-40 rounded-xl" /></div>;
  }

  if (failure) {
    return (
      <div className="space-y-4">
        <SEOHead title="Lesson Notes — Clutch Marks" description="View and download the uploaded notes for this lesson." path={`/lessons/${lessonId}/notes`} />
        <QueryError message={failure} onRetry={() => window.location.reload()} />
      </div>
    );
  }

  if (!lesson) {
    return (
      <Card><CardContent className="py-12 text-center space-y-3">
        <p className="text-muted-foreground">Lesson not found.</p>
        <Button variant="outline" onClick={() => navigate("/lessons")}>Back to Lessons</Button>
      </CardContent></Card>
    );
  }

  // Students only see lessons belonging to a subject-level they picked.
  const lessonSlId = lesson?.topics?.subject_levels?.id;
  if (!isAdminRole && prefsLoaded && lessonSlId && !pickedIds.has(lessonSlId)) {
    return (
      <Card><CardContent className="py-12 text-center space-y-3">
        <p className="text-muted-foreground">You haven't selected this subject yet.</p>
        <Button variant="outline" onClick={() => navigate("/lessons")}>Back to Lessons</Button>
      </CardContent></Card>
    );
  }

  const level = lesson.topics?.subject_levels?.level;

  return (
    <div className="cm-study space-y-5">
      <PreviewBanner />
      <WatermarkOverlay />
      <SEOHead
        title={`${lesson.title} — Notes | Clutch Marks`}
        description="View and download the uploaded notes for this lesson and track your completion."
        path={`/lessons/${lessonId}/notes`}
        jsonLd={{
          "@context": "https://schema.org",
          "@type": "LearningResource",
          name: `${lesson.title} — Notes`,
          url: `${SITE_URL}/lessons/${lessonId}/notes`,
          learningResourceType: "Lesson notes",
          educationalLevel:
            (level && (LEVEL_LABELS[level as "OL"] ?? level)) || undefined,
          about: lesson.topics?.name
            ? { "@type": "Thing", name: lesson.topics.name }
            : undefined,
          inLanguage: "en",
          provider: {
            "@type": "EducationalOrganization",
            name: "Clutch Marks",
            url: `${SITE_URL}/`,
          },
        }}
      />

      <Button variant="ghost" asChild className="gap-2"><Link to="/lessons"><ArrowLeft className="h-4 w-4" /> Back to Lessons</Link></Button>

      <ManuscriptHead
        eyebrow={
          lesson.topics?.subject_levels?.subjects?.name
            ? `${lesson.topics.subject_levels.subjects.name}${level ? ` · ${LEVEL_LABELS[level as "OL"] ?? level}` : ""}`
            : "Lesson notes"
        }
        title={lesson.title}
        lede={lesson.topics?.name ? `Lesson · ${lesson.topics.name}` : null}
        actions={
          <>
            {role === "admin" && (
              <ContentEditor
                entityType="lesson"
                entityId={lesson.id}
                initialTitle={lesson.title}
                initialContent={lesson.content ?? null}
                onSaved={bump}
                trigger={
                  <Button variant="outline" className="gap-2">
                    <Pencil className="h-4 w-4" /> Edit lesson
                  </Button>
                }
              />
            )}
            <Button onClick={toggleLesson} variant={lessonDone ? "outline" : "default"} className="gap-2">
              {lessonDone ? <><CheckCircle2 className="h-4 w-4" /> Completed</> : "Mark lesson complete"}
            </Button>
          </>
        }
      />

      {role === "admin" && lesson.content && (
        <ManuscriptSection
          eyebrow="Lesson notes"
          actions={
            <ContentEditor
              entityType="lesson"
              entityId={lesson.id}
              initialTitle={lesson.title}
              initialContent={lesson.content}
              onSaved={bump}
            />
          }
        >
          <div
            className="cm-notes"
            dangerouslySetInnerHTML={{ __html: lesson.content }}
          />
        </ManuscriptSection>
      )}

      {lessonDone && <FeedbackNudge tool="notes" toolLabel={lesson.title} />}

      <ManuscriptSection eyebrow="Study materials" title="Uploaded notes">
        <div className="space-y-3">
          {notes.length === 0 ? (
            <p className="text-sm text-muted-foreground">No notes have been uploaded for this topic yet.</p>
          ) : notes.map((n) => (
            <div key={n.id} className="flex flex-wrap items-center gap-3 rounded-lg border p-3">
              <button onClick={() => toggle(n.id)} aria-label={done[n.id] ? "Mark as not studied" : "Mark as studied"} className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md hover:bg-muted">
                {done[n.id] ? <CheckCircle2 className="h-5 w-5 text-emerald-500" /> : <Circle className="h-5 w-5 text-muted-foreground" />}
              </button>
              <p className="min-w-0 flex-1 truncate text-sm font-medium">{n.title}</p>
              <div className="flex gap-2">
                {role === "admin" && (
                  <ContentEditor
                    entityType="material"
                    entityId={n.id}
                    initialTitle={n.title}
                    initialContent={n.content ?? null}
                    onSaved={bump}
                  />
                )}
                <Button size="sm" variant="outline" className="gap-1" disabled={!n.file_url}
                  onClick={async () => {
                    if (!n.file_url) return;
                    try {
                      await openProtectedFile("study-materials", n.file_url);
                    } catch (e) {
                      toast.error(e?.message ?? "Could not open this file");
                    }
                  }}>
                  <ExternalLink className="h-3.5 w-3.5" /> Open
                </Button>
                <Button size="sm" variant="ghost" className="gap-1" disabled={!n.file_url}
                  onClick={() => downloadNote(n).catch((e) => toast.error(e?.message ?? "Could not download this file"))}>
                  <Download className="h-3.5 w-3.5" /> Download
                </Button>
              </div>
            </div>
          ))}
        </div>
      </ManuscriptSection>

    </div>
  );
}

// All topics with their lessons and notes, filtered by subject picker.
import { useEffect, useState, useMemo } from "react";
import { useNavigate, useParams } from "react-router-dom";
import DOMPurify from "dompurify";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { useToast } from "@/hooks/useToast";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { CheckCircle2, Circle, BookOpen, ChevronRight, Download, FileText, Loader2, ClipboardList, Layers } from "lucide-react";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { exportLessonToPdf } from "@/lib/pdfExport";
import { SEOHead } from "@/components/SEOHead";
import { openSignedFile } from "@/lib/contentFiles";
import { topicNotesPath, topicQuizPath, topicSlugOf } from "@/lib/topicUrls";
import { LEVELS, LEVEL_LABELS } from "@/lib/subjects";
import { useMySubjects } from "@/hooks/useMySubjects";
import { usePreviewSlice, PreviewLimit, usePlanAccess, FREE_PREVIEW_LIMIT } from "@/components/PreviewLimit";
import { PreviewBanner } from "@/components/PreviewBanner";
import { SubjectGate } from "@/components/SubjectGate";
import { FeedbackNudge } from "@/components/FeedbackNudge";
import { SubjectPicker } from "@/components/SubjectPicker";

export default function Lessons() {
  const { user } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const { subject, level, topic } = useParams<{ subject?: string; level?: string; topic?: string }>();
  const [topics, setTopics] = useState<any[]>([]);
  const [lessons, setLessons] = useState<any[]>([]);
  const [progress, setProgress] = useState<Record<string, boolean>>({});
  const [selectedLesson, setSelectedLesson] = useState<any>(null);
  const [notes, setNotes] = useState<any[]>([]);
  // Per-topic hub links (notes / questions) plus the badge label
  // (subject + level), so same-named topics on different levels — Nuclear
  // Physics (OL vs A2), Thermal Physics — are distinguishable in the list.
  const [topicLinks, setTopicLinks] = useState<Record<string, { notes: string; quiz: string } | undefined>>({});
  const [topicMeta, setTopicMeta] = useState<Record<string, { subject: string; level: string }>>({});
  const topicSlugMap = useMemo(() => new Map(topics.map((t) => [t.id, topicSlugOf(t)])), [topics]);
  const { pickedIds, loaded: prefsLoaded, isAdmin, needsSubjectPick } = useMySubjects();

  // Save the open lesson as branded revision paper. The export loads the brand
  // tile and stamps the account watermark, so it is async and can fail (offline,
  // a blocked canvas) — awaited in a try/catch rather than fired into the void.
  const saveLessonPdf = async (lesson) => {
    try {
      await exportLessonToPdf(lesson, { owner: user?.email ?? user?.id ?? null });
      toast({ title: "Saved", description: "Your PDF is downloading." });
    } catch (e) {
      toast({
        title: "Couldn't build the PDF",
        description: e?.message ?? "Please try again.",
        variant: "destructive",
      });
    }
  };

  useEffect(() => {
    const load = async () => {
      const [topicsRes, lessonsRes, notesRes, progressRes, slRes, subRes] = await Promise.all([
        supabase.from("topics").select("*").order("sort_order"),
        supabase.from("lessons").select("*").order("sort_order"),
        supabase.from("study_materials").select("id, title, file_url, topic_id").eq("material_type", "notes"),
        user ? supabase.from("lesson_progress").select("lesson_id, completed").eq("user_id", user.id) : Promise.resolve({ data: [] }),
        supabase.from("subject_levels").select("id, level, subject_id"),
        supabase.from("subjects").select("id, name, slug"),
      ]);
      const topicsList = topicsRes.data ?? [];
      setTopics(topicsList);
      setLessons(lessonsRes.data ?? []);
      setNotes(notesRes.data ?? []);
      const prog: Record<string, boolean> = {};
      (progressRes.data ?? []).forEach((p) => { prog[p.lesson_id] = p.completed; });
      setProgress(prog);
      // Resolve each topic's hub links (notes / questions) and badge
      // label via its subject level + subject slug.
      const slMap = new Map(((slRes.data ?? []) as any[]).map((s) => [s.id, s]));
      const subMap = new Map(((subRes.data ?? []) as any[]).map((s) => [s.id, s]));
      const links: Record<string, { notes: string; quiz: string } | undefined> = {};
      const meta: Record<string, { subject: string; level: string }> = {};
      for (const t of topicsList) {
        const sl = slMap.get((t as any).subject_level_id);
        const sub = sl ? subMap.get(sl.subject_id) : undefined;
        const slug = sub?.slug;
        if (slug && sl) {
          const lvl = sl.level.toLowerCase();
          const tslug = topicSlugOf(t);
          links[t.id] = {
            notes: topicNotesPath(slug, lvl, tslug),
            quiz: topicQuizPath(slug, lvl, tslug),
          };
          meta[t.id] = { subject: sub.name, level: sl.level };
        } else {
          links[t.id] = undefined;
        }
      }
      setTopicLinks(links);
      setTopicMeta(meta);
    };
    load();
  }, [user]);

  const toggleComplete = async (lessonId: string) => {
    if (!user) return;
    const isCompleted = progress[lessonId];
    if (isCompleted) {
      await supabase.from("lesson_progress").delete().eq("user_id", user.id).eq("lesson_id", lessonId);
    } else {
      await supabase.from("lesson_progress").upsert({ user_id: user.id, lesson_id: lessonId, completed: true, completed_at: new Date().toISOString() });
    }
    setProgress((p) => ({ ...p, [lessonId]: !isCompleted }));
  };

  const { loading: planLoading, isPreview, previewLimit, hasPaid } = usePlanAccess();
  const visibleTopics = useMemo(() => {
    if (isAdmin || !prefsLoaded) return topics;
    // Signed-in students are scoped to the subjects they picked. An anonymous
    // visitor has no picks, and an empty pick set would filter the whole index
    // away — they see every subject, still cut down by the free-plan slice
    // below, exactly like a student on the free plan.
    const picked = user
      ? topics.filter((t) => pickedIds.has((t as any).subject_level_id))
      : topics;
    if (planLoading) return picked;
    // Free plan: first 2 lessons per subject-level (preview limit)
    if (!isPreview) {
      const byLevel = new Map<string, any[]>();
      for (const t of picked) {
        const qs = lessons.filter((l) => l.topic_id === t.id);
        byLevel.set(t.id, qs);
      }
      const limited = new Map<string, any[]>();
      for (const [levelId, qs] of byLevel) {
        limited.set(levelId, qs.slice(0, FREE_PREVIEW_LIMIT));
      }
      return picked.filter((t) => limited.get(t.id)?.length > 0);
    }
    return picked;
  }, [topics, pickedIds, prefsLoaded, isAdmin, lessons, planLoading, isPreview, FREE_PREVIEW_LIMIT, user]);

  // Hidden lesson count for the free-plan upgrade prompt.
  const hiddenCount = useMemo(() => {
    if (isAdmin || !prefsLoaded) return 0;
    if (!isPreview) {
      let total = 0;
      for (const t of pickedIds ? topics.filter((t) => pickedIds.has(t.subject_level_id)) : topics) {
        total += (lessons.filter((l) => l.topic_id === t.id)).length;
      }
      return total;
    }
    return 0;
  }, [topics, pickedIds, lessons, isAdmin, isPreview]);

  // Only signed-in students are gated: an anonymous visitor has picked no
  // subjects by definition and must still see the lesson index. That rule lives
  // in useMySubjects now, so this page cannot drift from the others.

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any lesson content renders — nothing is shown while prefs
  // are loading or when nothing is picked. Early returns sit after every hook.
  if (!isAdmin && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/lessons" />
        <SubjectGate />
      </div>
    );
  }

  if (selectedLesson) {
    return (
      <div className="space-y-4">
        <SEOHead path="/lessons" />
        <Button variant="ghost" onClick={() => setSelectedLesson(null)} className="gap-2">
          ← Back to Lessons
        </Button>
        <Card>
          <CardHeader>
            <CardTitle>{selectedLesson.title}</CardTitle>
          </CardHeader>
          <CardContent className="prose prose-sm max-w-none dark:prose-invert">
            {selectedLesson.content ? (
              <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(selectedLesson.content.replace(/\n/g, "<br/>")) }} />
            ) : (
              <p className="text-muted-foreground">No content available yet.</p>
            )}
            {selectedLesson.video_url && (
              <div className="mt-4">
                <a href={selectedLesson.video_url} target="_blank" rel="noopener noreferrer" className="text-primary underline">
                  Watch Video →
                </a>
              </div>
            )}
            {selectedLesson.zoom_url && (
              <div className="mt-4">
                <a href={selectedLesson.zoom_url} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition-colors">
                  Join Zoom Meeting →
                </a>
              </div>
            )}
            <div className="mt-6 flex flex-wrap gap-2">
              <Button onClick={() => toggleComplete(selectedLesson.id)} variant={progress[selectedLesson.id] ? "outline" : "default"}>
                {progress[selectedLesson.id] ? "Mark Incomplete" : "Mark Complete ✓"}
              </Button>
              <Button variant="outline" className="gap-2" onClick={() => saveLessonPdf(selectedLesson)}>
                <Download className="h-4 w-4" /> Save as PDF
              </Button>
            </div>
            {progress[selectedLesson.id] && (
              <div className="mt-4">
                <FeedbackNudge tool="lesson" toolLabel={selectedLesson.title} />
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PreviewBanner />
      <SEOHead path="/lessons" />
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Lessons</h1>
          <p className="text-muted-foreground">Structured lessons and notes by topic</p>
        </div>
        <SubjectPicker />
      </div>

      {needsSubjectPick ? (
        <SubjectGate />
      ) : visibleTopics.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center py-12">
            <BookOpen className="h-12 w-12 text-muted-foreground/50 mb-4" />
            <p className="text-muted-foreground">No topics available yet.</p>
          </CardContent>
        </Card>
      ) : (
        <Accordion type="multiple" className="space-y-3">
          {visibleTopics.map((topic) => {
            const topicLessons = lessons.filter((l) => l.topic_id === topic.id);
            const topicNotes = notes.filter((n) => n.topic_id === topic.id);
            const completedCount = topicLessons.filter((l) => progress[l.id]).length;
            const links = topicLinks[topic.id];
            const meta = topicMeta[topic.id];
            return (
              <AccordionItem key={topic.id} value={topic.id} className="border rounded-lg px-4">
                <AccordionTrigger className="hover:no-underline">
                  <div className="flex items-center gap-3 text-left">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/10 text-primary text-sm font-bold">
                      {topic.sort_order + 1}
                    </div>
                    <div>
                      <p className="font-semibold">{topic.name}</p>
                      <p className="text-xs text-muted-foreground">{completedCount}/{topicLessons.length} lessons</p>
                    </div>
                    {meta && (
                      <div className="ml-1 flex flex-wrap gap-1">
                        <Badge variant="secondary" className="text-[10px]">{meta.subject}</Badge>
                        <Badge variant="outline" className="text-[10px]">{LEVEL_LABELS[meta.level as "OL"] ?? meta.level}</Badge>
                      </div>
                    )}
                  </div>
                </AccordionTrigger>
                <AccordionContent>
                  <div className="space-y-1 pb-2">
                    {/* Keep topic actions focused on learning here; past papers
                        live together in the dedicated archive tab. */}
                    <div className="grid grid-cols-2 gap-2 px-1 pb-3 sm:grid-cols-3">
                      <Button size="sm" variant="outline" className="gap-1.5" disabled={!links} onClick={() => links && navigate(links.notes)}>
                        <FileText className="h-3.5 w-3.5" /> Notes
                      </Button>
                      <Button size="sm" variant="outline" className="gap-1.5" disabled={!links} onClick={() => links && navigate(links.quiz)}>
                        <ClipboardList className="h-3.5 w-3.5" /> Questions
                      </Button>
                      <Button size="sm" variant="outline" className="gap-1.5" onClick={() => navigate("/flashcards")}>
                        <Layers className="h-3.5 w-3.5" /> Flashcards
                      </Button>
                    </div>
                    {topicLessons.length > 0 && (
                      <p className="px-3 pt-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Lessons</p>
                    )}
                    {topicLessons.map((lesson) => {
                      const dest = topicLinks[lesson.topic_id]?.notes;
                      return (
                        <button
                          key={lesson.id}
                          onClick={() => setSelectedLesson(lesson)}
                          className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm hover:bg-muted transition-colors text-left"
                        >
                          {progress[lesson.id] ? (
                            <CheckCircle2 className="h-4 w-4 text-accent shrink-0" />
                          ) : (
                            <Circle className="h-4 w-4 text-muted-foreground shrink-0" />
                          )}
                          <span className="flex-1">{lesson.title}</span>
                          {dest && (
                            <span
                              role="link"
                              tabIndex={0}
                              onClick={(e) => { e.stopPropagation(); navigate(dest); }}
                              onKeyDown={(e) => { if (e.key === "Enter") { e.stopPropagation(); navigate(dest); } }}
                              className="rounded px-2 py-0.5 text-xs text-primary hover:underline"
                            >
                              Notes
                            </span>
                          )}
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        </button>
                      );
                    })}
                    {topicNotes.length > 0 && (
                      <p className="px-3 pt-2 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Files & notes</p>
                    )}
                    {topicNotes.map((n) => {
                      const dest = topicLinks[n.topic_id]?.notes;
                      if (!n.file_url && !dest) return null;
                      return (
                        <button
                          key={n.id}
                          onClick={() => {
                            if (n.file_url) openSignedFile("study-materials", n.file_url).catch((e) => toast({ title: "Couldn't open this file", description: e?.message ?? "Please try again.", variant: "destructive" }));
                            else if (dest) navigate(dest);
                          }}
                          className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm hover:bg-muted transition-colors text-left"
                        >
                          <FileText className="h-4 w-4 text-primary shrink-0" />
                          <span className="min-w-0 flex-1 truncate">{n.title}</span>
                          <span className="text-xs text-muted-foreground">Notes</span>
                        </button>
                      );
                    })}
                    {topicLessons.length === 0 && (
                      <p className="text-sm text-muted-foreground px-3 py-2">No lessons in this topic yet.</p>
                    )}
                  </div>
                </AccordionContent>
              </AccordionItem>
            );
          })}
        </Accordion>
      )}
      <LessonsPreviewGate hiddenCount={hiddenCount} />
    </div>
  );
}

// Shared preview-limit state for the lessons page (persisted per subject-level).
// Lesson pages apply preview limiting per subject-level. Free-plan users see
// the first FREE_PREVIEW_LIMIT lessons per level (from PreviewLimit.tsx) and
// the remainder is replaced with an upgrade prompt.
export function LessonsPreviewGate({ hiddenCount }: { hiddenCount: number }) {
  const { isPreview, loading } = usePlanAccess();
  if (loading || !isPreview || hiddenCount <= 0) return null;
  return (
    <PreviewLimit
      hiddenCount={hiddenCount}
      what="lesson"
    />
  );
}

// Revision-notes library (uploaded study materials) — presented as an
// editorial reading surface: numbered entries, display-serif titles and a
// measure-limited reader, rather than a wall of identical cards.
import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { SEOHead } from "@/components/SEOHead";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { openProtectedFile } from "@/lib/contentFiles";
import { LEVELS, LEVEL_LABELS } from "@/lib/subjects";
import { toast } from "sonner";
import { loadFailureMessage } from "@/lib/net";
import {
  FileText, Search, Download, CheckCircle2, Circle, AlertCircle, RotateCcw, ExternalLink, Eye, Loader2,
} from "lucide-react";
import { ContentEditor } from "@/components/admin/ContentEditor";

export interface NoteRow {
  id: string;
  title: string;
  file_url: string | null;
  content: string | null;
  material_type: string;
  topic_id: string | null;
  topic_name: string;
  subject_name: string;
  subject_id: string;
  subject_level_id: string;
  level: string;
}

/** Material types this library surfaces, in the order the filter offers them. */
export const LIBRARY_TYPES = ["notes", "summary"] as const;

// A ceiling so the library cannot silently grow into an unbounded query.
const LIBRARY_LIMIT = 500;

export async function fetchNotes(): Promise<NoteRow[]> {
  const { data, error } = await supabase
    .from("study_materials")
    .select("id, title, file_url, content, material_type, topic_id, topics(id, name, subject_levels(id, level, subjects(id, name)))")
    // Previously pinned to "notes", which hid every "summary" material from the
    // library — half the content was only reachable from a topic page.
    .in("material_type", LIBRARY_TYPES as unknown as string[])
    .order("title")
    .limit(LIBRARY_LIMIT);
  if (error) throw error;
  return (data ?? []).map((m) => ({
    id: m.id,
    title: m.title,
    file_url: m.file_url,
    content: m.content,
    material_type: m.material_type ?? "notes",
    topic_id: m.topic_id,
    topic_name: m.topics?.name ?? "Unassigned",
    subject_name: m.topics?.subject_levels?.subjects?.name ?? "General",
    subject_id: m.topics?.subject_levels?.subjects?.id ?? "none",
    subject_level_id: m.topics?.subject_levels?.id ?? "",
    level: m.topics?.subject_levels?.level ?? "",
  }));
}

export function useNoteProgress() {
  const { user } = useAuth();
  const [done, setDone] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (!user) return;
    (async () => {
      try {
        const { data, error } = await supabase
          .from("material_progress")
          .select("material_id, completed")
          .eq("user_id", user.id);
        // PostgREST resolves with `{ error }` rather than rejecting, so the
        // old `catch` below never fired for a failed query: the tick marks just
        // silently vanished. Say so instead.
        if (error) {
          toast.error(loadFailureMessage("your study progress", error));
          return;
        }
        const map: Record<string, boolean> = {};
        (data ?? []).forEach((r) => { map[r.material_id] = r.completed; });
        setDone(map);
      } catch (e) {
        // A failed progress read must not surface as an unhandled rejection;
        // the list still works, it just shows nothing as studied yet.
        console.error("Could not load note progress:", e);
      }
    })();
  }, [user]);

  const toggle = async (materialId: string) => {
    if (!user) return;
    const next = !done[materialId];
    setDone((d) => ({ ...d, [materialId]: next }));
    const { error } = await supabase.from("material_progress").upsert(
      {
        user_id: user.id,
        material_id: materialId,
        completed: next,
        completed_at: next ? new Date().toISOString() : null,
      },
      { onConflict: "user_id,material_id" },
    );
    if (error) {
      setDone((d) => ({ ...d, [materialId]: !next }));
      toast.error("Could not save progress");
    }
  };

  return { done, toggle };
}

export async function downloadNote(note: NoteRow) {
  if (!note.file_url) return;
  // Protected download: same watermarked bytes via serve-material.
  await openProtectedFile("study-materials", note.file_url, note.title);
}

export default function Notes() {
  const { role } = useAuth();
  const [notes, setNotes] = useState<NoteRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [subject, setSubject] = useState("all");
  const [level, setLevel] = useState("all");
  const [type, setType] = useState("all");
  const { done, toggle } = useNoteProgress();
  // The library is scoped to the student's picked subject-levels, the same way
  // the dashboard tiles are. Without this a Mathematics + Physics student read
  // Computer Science A2 notes under a "Showing only your subjects" banner.
  const { user } = useAuth();
  const {
    pickedIds,
    loaded: prefsLoaded,
    isAdmin: isAdminRole,
    needsSubjectPick,
    filtering,
  } = useMySubjects();

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      setNotes(await fetchNotes());
    } catch (e) {
      setError(e.message ?? "Failed to load notes");
    }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const subjects = useMemo(() => {
    const seen = new Map<string, string>();
    notes.forEach((n) => seen.set(n.subject_id, n.subject_name));
    return [...seen.entries()];
  }, [notes]);

  const visible = useMemo(() => {
    const term = q.trim().toLowerCase();
    return notes.filter((n) => {
      if (filtering && !pickedIds.has(n.subject_level_id)) return false;
      if (subject !== "all" && n.subject_id !== subject) return false;
      if (level !== "all" && n.level !== level) return false;
      if (type !== "all" && n.material_type !== type) return false;
      if (!term) return true;
      // Search the body too, not just the title: students look for a term they
      // remember reading, not the note's heading.
      const body = (n.content ?? "").replace(/<[^>]*>/g, " ").toLowerCase();
      return (
        n.title.toLowerCase().includes(term) ||
        n.topic_name.toLowerCase().includes(term) ||
        body.includes(term)
      );
    });
  }, [notes, q, subject, level, type, filtering, pickedIds]);

  const completedCount = visible.filter((n) => done[n.id]).length;
  const progressPct = visible.length ? Math.round((completedCount / visible.length) * 100) : 0;

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any notes are shown. While preferences are still loading we
  // render nothing — never the content itself. Sits after every hook so the
  // early returns never change hook order.
  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="cm-study mx-auto max-w-4xl space-y-8">
        <SEOHead path="/notes" />
        <SubjectGate />
      </div>
    );
  }

  return (
    <div className="cm-study mx-auto max-w-4xl space-y-8">
      <SEOHead path="/notes" />

      {/* ---------- masthead ---------- */}
      <header>
        <p className="eyebrow mb-3 flex items-center gap-2">
          <FileText className="h-3.5 w-3.5 text-primary" /> The library
        </p>
        <h1 className="display-xl text-3xl lg:text-4xl">Revision notes</h1>
        <p className="mt-3 text-sm text-muted-foreground">
          {loading
            ? "Loading notes…"
            : visible.length === 0
              ? "No notes in this view"
              : // Study ticks are per-account: promising a progress figure to a
                // visitor who has no account to record it against was a number
                // that could never move.
                !user
                ? "Sign in to track which notes you've studied"
                : `${completedCount} of ${visible.length} marked as studied — ${progressPct}% of this set`}
        </p>
        <hr className="rule-gold mt-6" />
      </header>

      {/* ---------- filters ---------- */}
      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search notes or topic keywords…"
            className="pl-9"
            aria-label="Search notes"
          />
        </div>
        <Select value={subject} onValueChange={setSubject}>
          <SelectTrigger className="w-full sm:w-[180px]"><SelectValue placeholder="Subject" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All subjects</SelectItem>
            {subjects.map(([id, name]) => <SelectItem key={id} value={id}>{name}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={level} onValueChange={setLevel}>
          <SelectTrigger className="w-full sm:w-[160px]"><SelectValue placeholder="Level" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All levels</SelectItem>
            {LEVELS.map((l) => <SelectItem key={l} value={l}>{LEVEL_LABELS[l]}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={type} onValueChange={setType}>
          <SelectTrigger className="w-full sm:w-[150px]" aria-label="Material type"><SelectValue placeholder="Type" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All types</SelectItem>
            <SelectItem value="notes">Notes</SelectItem>
            <SelectItem value="summary">Summaries</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {error && (
        <Card className="border-destructive/40">
          <CardContent className="flex items-center justify-between gap-3 p-4">
            <p className="text-sm text-destructive flex items-center gap-2"><AlertCircle className="h-4 w-4" /> {error}</p>
            <Button size="sm" variant="outline" onClick={load} className="gap-1"><RotateCcw className="h-3.5 w-3.5" /> Try again</Button>
          </CardContent>
        </Card>
      )}

      {/* ---------- entries ---------- */}
      {loading ? (
        <div className="space-y-3">{[0, 1, 2].map((i) => <Skeleton key={i} className="h-24 rounded-xl" />)}</div>
      ) : visible.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center py-14">
            <FileText className="h-9 w-9 text-muted-foreground/30 mb-3" />
            <p className="text-sm text-muted-foreground">No notes match your search.</p>
          </CardContent>
        </Card>
      ) : (
        <ol className="space-y-3">
          {visible.map((n, i) => {
            const studied = !!done[n.id];
            return (
              <li key={n.id}>
                <Card
                  className={`group relative overflow-hidden transition-colors ${studied ? "border-primary/25" : ""}`}
                >
                  {/* gold rail marks the entry as studied */}
                  <span
                    aria-hidden
                    className={`absolute left-0 top-0 h-full w-[2px] transition-opacity ${studied ? "bg-primary opacity-100" : "opacity-0"}`}
                  />
                  <CardContent className="flex flex-wrap items-center gap-4 p-5">
                    <span className="num hidden w-7 shrink-0 font-mono text-xs text-muted-foreground/50 sm:block">
                      {String(i + 1).padStart(2, "0")}
                    </span>

                    {/* Per-account control: hidden when signed out instead of
                        rendering a toggle whose only outcome is "nothing". */}
                    {user && (
                      <button
                        onClick={() => toggle(n.id)}
                        aria-label={studied ? "Mark as not studied" : "Mark as studied"}
                        className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md transition-transform hover:bg-muted"
                      >
                        {studied
                          ? <CheckCircle2 className="h-5 w-5 text-primary" />
                          : <Circle className="h-5 w-5 text-muted-foreground/40" />}
                      </button>
                    )}

                    <div className="min-w-0 flex-1">
                      <p className="font-display text-[15px] font-semibold leading-snug tracking-tight">
                        {n.title}
                      </p>
                      <div className="mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1">
                        <span className="eyebrow">{n.subject_name}</span>
                        {n.level && (
                          <>
                            <span className="text-muted-foreground/30">·</span>
                            <span className="eyebrow">{LEVEL_LABELS[n.level as "OL"] ?? n.level}</span>
                          </>
                        )}
                        <span className="text-muted-foreground/30">·</span>
                        <span className="min-w-0 text-xs text-muted-foreground truncate">{n.topic_name}</span>
                        {n.material_type === "summary" && (
                          <Badge variant="outline" className="text-[10px] capitalize">Summary</Badge>
                        )}
                      </div>
                    </div>

                    <div className="flex gap-1.5">
                      {role === "admin" && (
                        <ContentEditor
                          entityType="material"
                          entityId={n.id}
                          initialTitle={n.title}
                          initialContent={n.content ?? null}
                          onSaved={load}
                        />
                      )}
                      {n.content && (
                        <Button size="sm" variant="secondary" className="gap-1" asChild>
                          <Link to={`/notes/${n.id}`}><Eye className="h-3.5 w-3.5" /> Read</Link>
                        </Button>
                      )}
                      {/* File-backed controls only appear when there is a file. Every
                          material in the library is HTML-only today, so these used to
                          render as 60 dead, unlabelled buttons per page. */}
                      {n.file_url && (
                        <>
                          <Button size="sm" variant="ghost" className="gap-1"
                            onClick={async () => {
                              try {
                                await openProtectedFile("study-materials", n.file_url!);
                              } catch (e) {
                                toast.error(e?.message ?? "Could not open this file");
                              }
                            }}>
                            <ExternalLink className="h-3.5 w-3.5" /> Open
                          </Button>
                          <Button size="sm" variant="ghost"
                            aria-label={`Download ${n.title}`}
                            title={`Download ${n.title}`}
                            onClick={() => downloadNote(n).catch((e) => toast.error(e?.message ?? "Could not download this file"))}>
                            <Download className="h-3.5 w-3.5" />
                          </Button>
                        </>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </li>
            );
          })}
        </ol>
      )}

      <p className="text-xs text-muted-foreground">
        Looking for a specific lesson? Open it from <Link to="/lessons" className="text-primary underline">Lessons</Link> to view its notes.
      </p>
    </div>
  );
}

// Past-paper archive grouped by year; opens via watermarking proxy.
import { useState, useMemo } from "react";
import { supabase } from "@/integrations/supabase/client";
import { usePlanAccess, FREE_PREVIEW_LIMIT, usePreviewSliceWithLimit } from "@/components/PreviewLimit";
import { useToast } from "@/hooks/useToast";
import { useAuth } from "@/lib/auth";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { PaperPractice, type PracticePaper } from "@/components/PaperPractice";
import { SEOHead } from "@/components/SEOHead";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { openProtectedFile, openExternalPaper, ExternalPaperGated } from "@/lib/contentFiles";
import {
  boardLabel,
  archiveBoard,
  archivePaperGroup,
  paperSortKey,
  paperFileName,
  sortSessions,
  SESSION_ORDER,
  filterArchivePapers,
  filterPapersForSubjects,
} from "@/lib/pastPaperFiles";
import { Loader2, FileText, Search, ExternalLink, Clock, Trophy, Download, Wand2 } from "lucide-react";
import { SolvedPaperMarker } from "@/components/SolvedPaperMarker";
import { MarkPaperDialog } from "@/components/MarkPaperDialog";
import { QueryError } from "@/components/QueryError";
import { loadFailureMessage } from "@/lib/net";

interface PastPaper {
  id: string;
  year: number;
  session: string | null;
  paper_number: string | null;
  title: string;
  topic_id: string | null;
  paper_url: string | null;
  mark_scheme_url: string | null;
  topic_name: string | null;
  subject_slug: string | null;
  level: "OL" | "AS" | "A2" | null;
}

const LEVEL_FILTERS = [
  { id: "all", label: "All levels" },
  { id: "OL", label: "IGCSE" },
  { id: "AS", label: "AS Level" },
  { id: "A2", label: "A2 Level" },
];

const levelLabel = (l: string | null) => LEVEL_FILTERS.find((f) => f.id === l)?.label ?? l;

// `paper_number` rows already read "Paper 1 (12)" — prefixing another "Paper"
// rendered "Paper Paper 1 (12)".
const paperLabel = (n: string | null) => (!n ? "—" : /^paper\b/i.test(n) ? n : `Paper ${n}`);

export default function PastPapers() {
  const { toast } = useToast();
  const { user } = useAuth();
  const qc = useQueryClient();
  const { pickedIds, loaded: prefsLoaded, isAdmin, needsSubjectPick } = useMySubjects();
  const { data: subjectLevels } = useQuery({
    queryKey: ["archive_subject_levels"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("subject_levels")
        .select("id, level, subjects(slug)")
        .eq("is_active", true);
      if (error) throw error;
      return data ?? [];
    },
  });
  const [search, setSearch] = useState("");
  const [yearFilter, setYearFilter] = useState("all");
  const [levelFilter, setLevelFilter] = useState("all");
  const [boardFilter, setBoardFilter] = useState("all");
  const [paperFilter, setPaperFilter] = useState("all");
  const [sessionFilter, setSessionFilter] = useState("all");
  const [practicePaper, setPracticePaper] = useState<PracticePaper | null>(null);
  // The paper whose row the student tapped “Submit for marking” on — the
  // marking is scoped to that paper's own mark scheme.
  const [markPaper, setMarkPaper] = useState<any | null>(null);

  const { data: topics, error: topicsError } = useQuery({
    queryKey: ["topics"],
    queryFn: async () => {
      // Throw so React Query surfaces the failure; ignoring `error` here meant
      // a broken request looked exactly like "no topics exist".
      const { data, error } = await supabase.from("topics").select("*").order("sort_order");
      if (error) throw error;
      return data ?? [];
    },
  });

  const { data: papers, isLoading, error: papersError, refetch: refetchPapers } = useQuery({
    queryKey: ["past_papers"],
    queryFn: async () => {
      const { data, error } = await supabase.from("past_papers").select("*, topics(name, subject_levels(level, subjects(name, slug)))").order("year", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
  });

  // Saved sittings for this student, so each card can surface a best score.
  const { data: attempts } = useQuery({
    queryKey: ["past_paper_attempts", user?.id],
    enabled: !!user,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("past_paper_attempts")
        .select("id, paper_id, percentage, created_at")
        .eq("user_id", user!.id)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
  });

  // Best score + number of sittings per paper (rows arrive newest-first, so the
  // first percentage seen for a paper is its most recent).
  const attemptsByPaper = useMemo(() => {
    const m = new Map<string, { best: number; count: number }>();
    for (const a of attempts ?? []) {
      if (!a.paper_id || a.percentage == null) continue;
      const cur = m.get(a.paper_id);
      if (!cur) m.set(a.paper_id, { best: a.percentage, count: 1 });
      else m.set(a.paper_id, { best: Math.max(cur.best, a.percentage), count: cur.count + 1 });
    }
    return m;
  }, [attempts]);

  const { loading: planLoading, isPreview, hasPaid } = usePlanAccess();

  const handleOpenFile = async (url: string) => {
    try {
      await openProtectedFile("past-papers", url);
    } catch (e) {
      toast({ title: "Unable to open file", description: e?.message ?? "Please try again", variant: "destructive" });
    }
  };

  // Save-to-disk variant. Same watermarked bytes as opening, but the browser is
  // told to download (and what to call the file) instead of previewing it.
  const handleDownloadFile = async (url: string, name: string) => {
    try {
      await openProtectedFile("past-papers", url, name);
    } catch (e) {
      toast({ title: "Unable to download file", description: e?.message ?? "Please try again", variant: "destructive" });
    }
  };

  // External papers route through serve-external-paper, which enforces the
  // plan and audits the click. A gated rejection becomes an upgrade prompt.
  const handleOpenExternal = async (url: string, label?: string) => {
    try {
      await openExternalPaper(url, label);
    } catch (e) {
      if (e instanceof ExternalPaperGated) {
        toast({ title: "Full plan required", description: e.message });
        return;
      }
      toast({ title: "Unable to open link", description: e?.message ?? "Please try again", variant: "destructive" });
    }
  };

  // Topic-linked rows use topic ownership; metadata-only rows use their
  // persisted subject_slug + level. The latter matters for archive papers that
  // are correctly classified but intentionally not assigned to a single topic.
  const topicToSl = useMemo(() => {
    const m = new Map<string, string>();
    (topics ?? []).forEach((t) => { if (t.subject_level_id) m.set(t.id, t.subject_level_id); });
    return m;
  }, [topics]);

  const subjectLevelByCode = useMemo(() => {
    const m = new Map<string, string>();
    (subjectLevels ?? []).forEach((row) => {
      const slug = row.subjects?.slug;
      if (slug && row.level) m.set(`${slug.toLowerCase()}/${String(row.level).toUpperCase()}`, row.id);
    });
    return m;
  }, [subjectLevels]);

  const scopedPapers = useMemo(
    () => filterPapersForSubjects(papers ?? [], {
      isAdmin,
      loaded: prefsLoaded,
      signedIn: !!user,
      pickedSubjectLevels: pickedIds,
      topicSubjectLevels: topicToSl,
      subjectLevelByCode,
    }),
    [papers, isAdmin, prefsLoaded, user, pickedIds, topicToSl, subjectLevelByCode],
  );

  // Filter options come from the whole subject-scoped archive, not the free
  // slice, so a student can see (and reach) every board / paper / session on
  // offer. Sessions always include the full board calendar, `Specimen` included.
  const boardOptions = useMemo(() => {
    const set = new Set<string>();
    (scopedPapers ?? []).forEach((p) => set.add(archiveBoard(p)));
    return [...set].sort((a, b) => a.localeCompare(b));
  }, [scopedPapers]);

  const paperOptions = useMemo(() => {
    const set = new Set<string>();
    (scopedPapers ?? []).forEach((p) => set.add(archivePaperGroup(p)));
    return [...set].sort((a, b) => paperSortKey(a).localeCompare(paperSortKey(b)));
  }, [scopedPapers]);

  const sessionOptions = useMemo(() => {
    const set = new Set<string>(SESSION_ORDER);
    (scopedPapers ?? []).forEach((p) => { if (p.session) set.add(p.session); });
    return [...set].sort(sortSessions);
  }, [scopedPapers]);

  // Every filter — search included — runs BEFORE the free-preview slice. It used
  // to be applied to `visiblePapers` (the slice), so a free student searching
  // for an older paper or a specimen only ever searched the first
  // `FREE_PREVIEW_LIMIT` rows and concluded the paper did not exist.
  const matchedPapers = useMemo(
    () => filterArchivePapers(scopedPapers ?? [], {
      search,
      level: levelFilter,
      board: boardFilter,
      paper: paperFilter,
      session: sessionFilter,
    }),
    [scopedPapers, search, levelFilter, boardFilter, paperFilter, sessionFilter],
  );

  // Year chips reflect the papers that survive the other filters, so switching
  // board or session never offers a year that would come up empty.
  const years = [...new Set(matchedPapers.map((p) => p.year))].sort((a, b) => b - a);
  const yearScoped = yearFilter === "all" ? matchedPapers : matchedPapers.filter((p) => p.year === Number(yearFilter));
  const { slice: visiblePapers } = usePreviewSliceWithLimit(yearScoped, FREE_PREVIEW_LIMIT);
  const filteredPapers = visiblePapers ?? [];

  const groupedPapers = years
    .map((y) => ({ year: y, papers: filteredPapers.filter((p) => p.year === y) }))
    .filter((g) => g.papers.length > 0);

  if (!isAdmin && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/past-papers" />
        <SubjectGate />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <SEOHead path="/past-papers" />
      <div>
        <h1 className="text-3xl font-bold flex items-center gap-2">
          <FileText className="h-7 w-7 text-primary" /> Past Papers
        </h1>
        <p className="text-muted-foreground text-sm">
          Download past exam papers and mark schemes. Solve one on paper and mark it with the{" "}
          <Link to="/ai-marker" className="font-semibold text-primary underline decoration-primary/30 underline-offset-4">AI Marker</Link>.
        </p>
      </div>

      {/* A failed load says so, with a retry, instead of showing a year list. */}
      {(papersError || topicsError) && (
        <QueryError
          message={loadFailureMessage("past papers", papersError ?? topicsError)}
          onRetry={() => refetchPapers()}
        />
      )}

      {/* AI marking of an uploaded solved paper. The component gates itself:
          free accounts get an upgrade card, and the worker enforces the plan
          server-side regardless. */}
      <div className="max-w-4xl mx-auto">
        <SolvedPaperMarker title="Mark a solved past paper" />
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col gap-4">
            <div className="relative">
              {/* The icon used to sit as a block above the field; every other
                  search box in the app nests it inside on the left. */}
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                className="pl-9"
                aria-label="Search past papers"
                placeholder="Search papers... (e.g. 2024, Paper 1, Chem, Specimen)"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <div className="flex flex-wrap gap-2">
              <Select value={levelFilter} onValueChange={setLevelFilter}>
                <SelectTrigger className="w-[170px]" aria-label="Filter by level">
                  <SelectValue placeholder="Level" />
                </SelectTrigger>
                <SelectContent>
                  {LEVEL_FILTERS.map((f) => (
                    <SelectItem key={f.id} value={f.id}>{f.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={boardFilter} onValueChange={setBoardFilter}>
                <SelectTrigger className="w-[200px]" aria-label="Filter by exam board">
                  <SelectValue placeholder="Board" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All boards</SelectItem>
                  {boardOptions.map((b) => (
                    <SelectItem key={b} value={b}>{b}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={paperFilter} onValueChange={setPaperFilter}>
                <SelectTrigger className="w-[200px]" aria-label="Filter by paper">
                  <SelectValue placeholder="Paper" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All papers</SelectItem>
                  {paperOptions.map((p) => (
                    <SelectItem key={p} value={p}>{p}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={sessionFilter} onValueChange={setSessionFilter}>
                <SelectTrigger className="w-[160px]" aria-label="Filter by session">
                  <SelectValue placeholder="Session" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All sessions</SelectItem>
                  {sessionOptions.map((s) => (
                    <SelectItem key={s} value={s}>{s}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex flex-wrap gap-2">
              {/* Year chips come from the papers actually in scope. They used to
                  be hard-coded to 2024/2023, which offered two years that did
                  not match the newest papers (2025) and hid the real ones. */}
              <Button variant="outline" onClick={() => setYearFilter("all")} className={yearFilter === "all" ? "bg-primary text-primary-foreground" : ""}>
                All years
              </Button>
              {years.map((y) => (
                <Button
                  key={y}
                  variant="outline"
                  onClick={() => setYearFilter(String(y))}
                  className={yearFilter === String(y) ? "bg-primary text-primary-foreground" : ""}
                >
                  {y}
                </Button>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Paper grid */}
      {isLoading ? (
        <Card>
          <CardContent className="py-12 text-center">
            <Loader2 className="h-8 w-8 animate-spin mx-auto text-primary" />
            <p className="text-sm text-muted-foreground mt-2">Loading past papers…</p>
          </CardContent>
        </Card>
      ) : filteredPapers.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <p className="text-sm text-muted-foreground">No past papers match your search.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {groupedPapers.flatMap((g) =>
            g.papers.map((p) => (
              <Card key={p.id} className="hover:shadow-md transition-shadow group">
                <CardHeader className="pb-2">
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <CardTitle className="text-base group-hover:text-primary transition-colors">
                      {p.title}
                    </CardTitle>
                    {/* Nothing in the archive has a PDF yet, so the primary action
                        used to be a disabled "Paper" button next to the words
                        "Awaiting upload" — a dead end. Point students at the exam
                        board's own page instead, and only show the download
                        buttons when there is actually a file to download. */}
                    <div className="flex shrink-0 flex-wrap justify-end gap-1">
                      {p.paper_url ? (
                        <Button variant="ghost" size="sm" onClick={() => handleOpenFile(p.paper_url ?? "")}>
                          View paper
                        </Button>
                      ) : null}
                      {p.mark_scheme_url && (
                        <Button variant="ghost" size="sm" onClick={() => handleOpenFile(p.mark_scheme_url ?? "")}>
                          View mark scheme
                        </Button>
                      )}
                      {/* A row can carry a paper but no mark scheme (or vice
                          versa), so the board-site fallback must fire whenever
                          *either* file is missing — keying it on `paper_url`
                          alone left those rows with no way out. */}
                      {(!p.paper_url || !p.mark_scheme_url) && p.source_url && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="gap-1"
                          onClick={() => handleOpenExternal(p.source_url!, boardLabel(p.source_url) ?? undefined)}
                        >
                          {boardLabel(p.source_url) ?? "Board site"}
                          <ExternalLink className="h-3 w-3" />
                        </Button>
                      )}
                    </div>
                  </div>
                  {/* CardDescription renders a <p>, and the level Badge renders a
                      <div> — invalid nesting, which React warns about. */}
                  <div className="text-sm text-muted-foreground space-y-1">
                    <div className="flex items-center gap-1.5">
                      {p.topics?.subject_levels?.level && (
                        <Badge variant="outline" className="text-[10px] uppercase tracking-[0.08em]">
                          {levelLabel(p.topics?.subject_levels?.level)}
                        </Badge>
                      )}
                      <span>
                        {p.session ? `${p.session} · Year ${p.year}` : `Year ${p.year}`}
                        {/* `topic_name` is not a column on past_papers — the topic
                            arrives as the nested `topics` embed. */}
                        {p.topics?.name && <span className="text-xs text-muted-foreground"> · {p.topics.name}</span>}
                      </span>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <p className="text-xs text-muted-foreground">
                    {paperLabel(p.paper_number)} ·{" "}
                    {p.paper_url
                      ? "Downloadable"
                      : p.source_url
                        ? "Not in our library yet — open it on the board's site"
                        : "Awaiting upload"}
                  </p>
                  <div className="mt-3 flex flex-wrap items-center justify-between gap-2">
                    <div className="flex flex-wrap items-center gap-2">
                      <Button
                        size="sm"
                        className="gap-1.5"
                        onClick={() => setPracticePaper({
                          id: p.id,
                          title: p.title,
                          session: p.session ?? null,
                          year: p.year,
                          paper_number: p.paper_number ?? null,
                        })}
                      >
                        <Clock className="h-3.5 w-3.5" /> Practise
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        className="gap-1.5"
                        title="Submit your solved script — marked against this paper's mark scheme"
                        onClick={() => setMarkPaper(p)}
                      >
                        <Wand2 className="h-3.5 w-3.5" /> Submit for marking
                      </Button>
                      {p.paper_url && (
                        <Button
                          size="sm"
                          variant="outline"
                          className="gap-1.5"
                          aria-label={`Download ${p.title} question paper`}
                          title="Download question paper"
                          onClick={() => handleDownloadFile(p.paper_url!, paperFileName(p.title, "paper"))}
                        >
                          <Download className="h-3.5 w-3.5" /> Download paper
                        </Button>
                      )}
                      {p.mark_scheme_url && (
                        <Button
                          size="sm"
                          variant="outline"
                          className="gap-1.5"
                          aria-label={`Download ${p.title} mark scheme`}
                          title="Download mark scheme"
                          onClick={() => handleDownloadFile(p.mark_scheme_url!, paperFileName(p.title, "mark-scheme"))}
                        >
                          <Download className="h-3.5 w-3.5" /> Download mark scheme
                        </Button>
                      )}
                    </div>
                    {(() => {
                      const score = attemptsByPaper.get(p.id);
                      if (!score) return null;
                      return (
                        <Badge variant="outline" className="gap-1 text-[10px] text-primary">
                          <Trophy className="h-3 w-3" /> Best {score.best}%
                          {score.count > 1 ? ` · ${score.count} sittings` : ""}
                        </Badge>
                      );
                    })()}
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      )}

      {/* Timed, paper-scoped practice. Saving an attempt awards XP server-side
          and refreshes the per-card best score. */}
      <PaperPractice
        paper={practicePaper}
        open={practicePaper !== null}
        onOpenChange={(o) => { if (!o) setPracticePaper(null); }}
        onSaved={() => qc.invalidateQueries({ queryKey: ["past_paper_attempts"] })}
      />

      {/* Submit-for-marking scoped to the tapped paper's own mark scheme. */}
      <MarkPaperDialog
        paper={markPaper}
        open={markPaper !== null}
        onOpenChange={(o) => { if (!o) setMarkPaper(null); }}
      />

    </div>
  );
}

// Practice hub — one page, three tabs:
//   • Topic questions: the full question bank by topic/difficulty, with
//     saved-progress mastery panel (merged from the old QuestionBank page)
//   • Review: every question you got wrong or bookmarked
//   • Drills: timed 10-question sessions on your weakest topics
import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ManuscriptQuestion } from "@/components/StudyManuscript";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { SEOHead } from "@/components/SEOHead";
import { BookmarkButton } from "@/components/BookmarkButton";
import { LEVEL_LABELS, type SubjectLevelCode } from "@/lib/subjects";
import { useMySubjects } from "@/hooks/useMySubjects";
import { useToast } from "@/hooks/useToast";
import { loadFailureMessage } from "@/lib/net";
import { SubjectPicker } from "@/components/SubjectPicker";
import { SubjectGate } from "@/components/SubjectGate";
import { FeedbackNudge } from "@/components/FeedbackNudge";
import { QuestionList, SavedProgressPanel, type Attempt, type TopicSummary } from "@/components/practice/QuestionBankParts";
import { cn } from "@/lib/utils";
import {
  Sparkles, Brain, CheckCircle2, XCircle, RotateCcw, Layers, Search,
  Bookmark, AlertCircle, Target, Database,
} from "lucide-react";

interface DrillQuestion {
  id: string;
  question_text: string;
  options: string[];
  topic_name: string;
  correct_option?: number;
  explanation?: string | null;
}

interface ReviewQuestion {
  id: string;
  quiz_id: string;
  quiz_title: string;
  question_text: string;
  options: string[];
  difficulty: string;
  topic_id: string | null;
  topic_name: string | null;
  bookmarked: boolean;
  last_correct: boolean | null;
  attempts_count: number;
}

interface BankQuestion {
  id: string;
  quiz_id: string;
  quiz_title: string;
  question_text: string;
  options: string[];
  difficulty: string;
  exam_type: string;
  is_ai_generated: boolean;
  topic_id: string | null;
  topic_name: string | null;
  bookmarked: boolean;
}

interface LevelOption { id: string; label: string }

export default function Practice() {
  const { user } = useAuth();
  const { toast } = useToast();
  const { pickedIds, loaded: prefsLoaded, isAdmin, needsSubjectPick, filtering } = useMySubjects();
  const [params, setParams] = useSearchParams();
  const requestedMode = params.get("mode") ?? "incorrect";
  const mode = requestedMode === "bookmarked" ? "bookmarked" : requestedMode === "all" ? "all" : "incorrect";
  const tab = params.get("tab") ?? (mode === "bookmarked" ? "review" : "topics");
  const levelId = params.get("level") ?? "all";
  // Default the review-level filter to the first subject-level the student
  // picked, so a student who chooses "Ol Math" immediately sees only Ol Math
  // review questions instead of every subject's wrong/bookmarked questions.
  const defaultedLevelId = useMemo(() => {
    if (isAdmin || !prefsLoaded) return levelId;
    if (levelId !== "all" && levelId !== "") return levelId;
    const picked = [...pickedIds];
    if (picked.length === 0) return "all";
    return picked[0];
  }, [levelId, isAdmin, prefsLoaded, pickedIds]);
  const topicFilter = params.get("topic") ?? "";

  const setParam = (key: string, value: string) => {
    const next = new URLSearchParams(params);
    if (value === "all" || value === "") next.delete(key); else next.set(key, value);
    setParams(next, { replace: true });
  };

  // ---------- Weak-topic drills ----------
  const [weakTopics, setWeakTopics] = useState<{ id: string; name: string; avg: number }[]>([]);
  const [drill, setDrill] = useState<DrillQuestion[]>([]);
  const [drillIdx, setDrillIdx] = useState(0);
  const [drillSelected, setDrillSelected] = useState<number | null>(null);
  const [drillCorrect, setDrillCorrect] = useState(0);
  const [drillCorrected, setDrillCorrected] = useState(false);
  const [drillDone, setDrillDone] = useState(false);
  const [drillTopic, setDrillTopic] = useState("");
  const [loadingWeak, setLoadingWeak] = useState(true);
  // Which topic's drill is being fetched, so the button can show progress
  // instead of looking dead between the click and the request landing.
  const [drillLoadingId, setDrillLoadingId] = useState<string | null>(null);

  // ---------- Review list (incorrect/bookmarked) ----------
  const [levelOptions, setLevelOptions] = useState<LevelOption[]>([]);
  const [questions, setQuestions] = useState<ReviewQuestion[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [difficulty, setDifficulty] = useState("all");
  const [active, setActive] = useState<ReviewQuestion | null>(null);
  const [selected, setSelected] = useState<number | null>(null);
  // `corrected` marks the case that matters most: this question was answered
  // wrongly before, and now it isn't. The server pays extra XP for it, and it is
  // the one piece of feedback worth calling out by name.
  const [reveal, setReveal] = useState<{ correct_option: number; explanation: string | null; correct: boolean; corrected?: boolean } | null>(null);
  const [topicSL, setTopicSL] = useState<Map<string, string>>(new Map()); // topic_id -> subject_level_id
  const pickedSlByTopic = useMemo(
    () => new Map([...topicSL.entries()].filter(([, sl]) => pickedIds.has(sl))),
    [topicSL, pickedIds],
  );

  // ---------- Topic questions (merged from QuestionBank) ----------
  const [bankTopics, setBankTopics] = useState<{ id: string; name: string }[]>([]);
  const [bankTopicId, setBankTopicId] = useState("");
  const [bankQuestions, setBankQuestions] = useState<BankQuestion[]>([]);
  const [bankSearch, setBankSearch] = useState("");
  const [bankDifficulty, setBankDifficulty] = useState("all");
  const [bankExamType, setBankExamType] = useState("all");
  const [bankAttempts, setBankAttempts] = useState<Record<string, Attempt>>({});
  const [bankSummary, setBankSummary] = useState<TopicSummary[]>([]);
  const [summaryLoading, setSummaryLoading] = useState(false);
  const [bankActive, setBankActive] = useState<BankQuestion | null>(null);
  const [bankSelected, setBankSelected] = useState<number | null>(null);
  const [bankReveal, setBankReveal] = useState<{ correct_option: number; explanation: string | null; correct: boolean; corrected?: boolean } | null>(null);

  useEffect(() => {
    if (!user) return;
    (async () => {
      const [topicsRes, quizzesRes, attemptsRes] = await Promise.all([
        supabase.from("topics").select("id, name, subject_level_id").order("sort_order"),
        supabase.from("quizzes").select("id, topic_id").eq("is_published", true),
        supabase.from("quiz_attempts").select("quiz_id, score, total_questions").eq("user_id", user.id).not("completed_at", "is", null),
      ]);
      const topics = topicsRes.data ?? [];
      setTopicSL(new Map(topics.map((t) => [t.id, t.subject_level_id])));
      setBankTopics(topics.map((t) => ({ id: t.id, name: t.name })));
      const quizTopic = new Map((quizzesRes.data ?? []).map((q) => [q.id, q.topic_id]));
      const tally: Record<string, { sum: number; n: number }> = {};
      (attemptsRes.data ?? []).forEach((a) => {
        const tid = quizTopic.get(a.quiz_id);
        if (!tid) return;
        const pct = ((a.score ?? 0) / (a.total_questions || 1)) * 100;
        tally[tid] = tally[tid] || { sum: 0, n: 0 };
        tally[tid].sum += pct;
        tally[tid].n += 1;
      });
      const ranked = topics
        .map((t) => ({ id: t.id, name: t.name, avg: tally[t.id] ? Math.round(tally[t.id].sum / tally[t.id].n) : -1 }))
        .filter((t) => t.avg >= 0)
        .sort((a, b) => a.avg - b.avg);
      setWeakTopics(ranked.length > 0 ? ranked : topics.map((t) => ({ id: t.id, name: t.name, avg: 0 })));
      setLoadingWeak(false);
    })();
  }, [user]);

  const loadReviewQuestions = async () => {
    setLoading(true);
    setError(null);
    const { data, error } = await supabase.rpc("get_review_questions", {
      _subject_level_id: levelId === "all" ? null : levelId,
      _mode: mode,
      _limit: 200,
    });
    if (error) setError(error.message);
    setQuestions(((data ?? []) as unknown as ReviewQuestion[]));
    setLoading(false);
  };

  useEffect(() => {
    (async () => {
      const { data, error: levelsError } = await supabase
        .from("subject_levels")
        .select("id, level, subjects(name)")
        .eq("is_active", true)
        .order("sort_order");
      if (levelsError) { setError(loadFailureMessage("your subjects", levelsError)); return; }
      setLevelOptions(
        (data ?? []).map((l) => ({
          id: l.id,
          label: `${l.subjects?.name ?? "Subject"} — ${LEVEL_LABELS[l.level as SubjectLevelCode]}`,
        })),
      );
    })();
  }, []);

  useEffect(() => { loadReviewQuestions(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [mode, defaultedLevelId]);

  const loadBankAttempts = async () => {
    if (!user) return;
    const { data, error: attemptsError } = await supabase
      .from("practice_attempts")
      .select("question_id, last_correct, attempts_count, last_attempt_at")
      .eq("user_id", user.id);
    if (attemptsError) {
      // Decorative (the "tried N times" marks), so it stays a toast rather
      // than blanking the whole question list.
      toast({
        title: "Couldn't load your practice history",
        description: loadFailureMessage("your practice history", attemptsError),
        variant: "destructive",
      });
      return;
    }
    const map: Record<string, Attempt> = {};
    (data ?? []).forEach((a) => { map[a.question_id] = a; });
    setBankAttempts(map);
  };

  const loadBankSummary = async () => {
    setSummaryLoading(true);
    try {
      const { data, error } = await supabase.rpc("get_practice_summary");
      if (error) throw error;
      setBankSummary(((data ?? []) as TopicSummary[]).filter((s) => s.total_questions > 0));
    } catch {
      setBankSummary([]);
    } finally {
      setSummaryLoading(false);
    }
  };

  // Load bank data lazily when its tab is first opened.
  useEffect(() => {
    if (tab !== "topics" || !user || bankTopics.length === 0) return;
    if (!bankTopicId) setBankTopicId(bankTopics[0].id);
    (async () => { await Promise.all([loadBankAttempts(), loadBankSummary()]); })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab, user, bankTopics]);

  useEffect(() => {
    if (tab !== "topics" || !bankTopicId) return;
    (async () => {
      const { data, error } = await supabase.rpc("browse_questions", {
        _topic_id: bankTopicId,
        _difficulty: bankDifficulty === "all" ? null : bankDifficulty,
        _exam_type: bankExamType === "all" ? null : bankExamType,
        _limit: 200,
        _offset: 0,
      });
      if (error) {
        // An empty panel is not the same as "no questions here".
        toast({ title: "Could not load questions", description: error.message, variant: "destructive" });
        setBankQuestions([]);
        return;
      }
      setBankQuestions(((data ?? []) as unknown as BankQuestion[]));
    })();
  }, [tab, bankTopicId, bankDifficulty, bankExamType]);

  const filteredReview = useMemo(() => {
    const q = search.trim().toLowerCase();
    return questions.filter((x) =>
      (difficulty === "all" || x.difficulty === difficulty) &&
      (!topicFilter || x.topic_id === topicFilter) &&
      (!q || x.question_text.toLowerCase().includes(q) || (x.topic_name ?? "").toLowerCase().includes(q) || x.quiz_title.toLowerCase().includes(q)));
  }, [questions, search, difficulty, topicFilter]);

  const filteredBank = useMemo(() => {
    const q = bankSearch.trim().toLowerCase();
    return q ? bankQuestions.filter((x) => x.question_text.toLowerCase().includes(q) || x.quiz_title.toLowerCase().includes(q)) : bankQuestions;
  }, [bankQuestions, bankSearch]);

  // ---------- Drill flow ----------
  const buildSession = async (topicId: string, topicName: string) => {
    // `if (pool.length === 0) return;` used to end this function with no state
    // change and no message, so clicking Drill on a topic without published
    // questions looked like a dead button. Errors were discarded too (the RPC
    // result's `error` was never read), which hid real failures the same way.
    if (drillLoadingId) return;
    setDrillLoadingId(topicId);
    try {
      const { data: qs, error } = await supabase.rpc("get_practice_questions", {
        _topic_id: topicId,
        _limit: 10,
      });
      if (error) {
        toast({
          title: "Could not start the drill",
          description: error.message,
          variant: "destructive",
        });
        return;
      }
      const pool: DrillQuestion[] = (qs ?? []).map((q) => ({
        id: q.id,
        question_text: q.question_text,
        options: Array.isArray(q.options) ? (q.options as string[]) : [],
        topic_name: topicName,
      }));
      if (pool.length === 0) {
        toast({
          title: "No questions to drill yet",
          description: `Nothing published for ${topicName} yet — try another topic or the Topic questions tab.`,
        });
        return;
      }
      setDrill(pool);
      setDrillTopic(topicName);
      setDrillIdx(0);
      setDrillSelected(null);
      setDrillCorrect(0);
      setDrillDone(false);
    } catch (e) {
      toast({
        title: "Could not start the drill",
        description: e?.message ?? "Unexpected error",
        variant: "destructive",
      });
    } finally {
      setDrillLoadingId(null);
    }
  };

  const handleDrillAnswer = async (i: number) => {
    if (drillSelected !== null) return;
    setDrillSelected(i);
    const { data, error } = await supabase.rpc("check_practice_answer", {
      _question_id: drill[drillIdx].id,
      _selected: i,
    });
    // Without this, a failed marking call left the option highlighted with no
    // verdict and no explanation — indistinguishable from a broken answer.
    if (error || !data) {
      setDrillSelected(null);
      toast({
        title: "Could not check that answer",
        description: error?.message ?? "Please try again.",
        variant: "destructive",
      });
      return;
    }
    const result = (data ?? {}) as { correct?: boolean; correct_option?: number; explanation?: string | null; corrected_mistake?: boolean };
    setDrill((prev) => prev.map((q, k) => k === drillIdx ? { ...q, correct_option: result.correct_option, explanation: result.explanation ?? null } : q));
    if (result.correct) setDrillCorrect((c) => c + 1);
    setDrillCorrected(Boolean(result.corrected_mistake));
  };

  const drillNext = () => {
    if (drillIdx + 1 < drill.length) { setDrillIdx(drillIdx + 1); setDrillSelected(null); setDrillCorrected(false); }
    else setDrillDone(true);
  };
  const drillReset = () => { setDrill([]); setDrillDone(false); setDrillIdx(0); setDrillSelected(null); setDrillCorrect(0); setDrillCorrected(false); };

  // ---------- Review flow ----------
  const startReview = (q: ReviewQuestion) => { setActive(q); setSelected(null); setReveal(null); };

  const submitReview = async () => {
    if (!active || selected === null) return;
    const { data, error } = await supabase.rpc("check_practice_answer", {
      _question_id: active.id,
      _selected: selected,
    });
    if (error) { setError(error.message); return; }
    const res = data as any;
    setReveal({
      correct_option: res.correct_option,
      explanation: res.explanation,
      correct: res.correct,
      corrected: Boolean(res.corrected_mistake),
    });
    setQuestions((prev) => prev.map((q) => q.id === active.id
      ? { ...q, last_correct: res.correct, attempts_count: q.attempts_count + 1 } : q));
  };

  // ---------- Topic-question flow ----------
  const startBankQuestion = (q: BankQuestion) => { setBankActive(q); setBankSelected(null); setBankReveal(null); };

  const submitBankQuestion = async (i: number) => {
    if (!bankActive || bankSelected !== null) return;
    setBankSelected(i);
    const { data, error } = await supabase.rpc("check_practice_answer", { _question_id: bankActive.id, _selected: i });
    // `if (!data) return;` used to leave the chosen option highlighted forever
    // with no verdict: the student clicks an answer and nothing happens.
    if (error || !data) {
      setBankSelected(null);
      toast({
        title: "Could not check that answer",
        description: error?.message ?? "Please try again.",
        variant: "destructive",
      });
      return;
    }
    const r = data as any;
    setBankReveal({
      correct_option: r.correct_option,
      explanation: r.explanation,
      correct: r.correct,
      corrected: Boolean(r.corrected_mistake),
    });
    loadBankAttempts();
    loadBankSummary();
  };

  const visibleLevelOptions = useMemo(() => {
    if (isAdmin || !prefsLoaded) return levelOptions;
    return levelOptions.filter((l) => pickedIds.has(l.id));
  }, [levelOptions, pickedIds, prefsLoaded, isAdmin]);

  const visibleWeakTopics = useMemo(() => {
    if (isAdmin || !prefsLoaded) return weakTopics;
    return weakTopics.filter((t) => pickedSlByTopic.get(t.id));
  }, [weakTopics, pickedIds, prefsLoaded, isAdmin, pickedSlByTopic]);

  const visibleBankTopics = useMemo(() => {
    if (isAdmin || !prefsLoaded) return bankTopics;
    return bankTopics.filter((t) => pickedSlByTopic.get(t.id));
  }, [bankTopics, pickedIds, prefsLoaded, isAdmin, pickedSlByTopic]);

  // The summary RPC is platform-wide, so its totals used to read "2 / 1940" and
  // its topic list named subjects the student never picked. Scope it the same
  // way as every other list on this page.
  const visibleBankSummary = useMemo(() => {
    if (!filtering) return bankSummary;
    return bankSummary.filter((s) => pickedSlByTopic.has(s.topic_id));
  }, [bankSummary, pickedIds, prefsLoaded, isAdmin, pickedSlByTopic]);

  // Keep the topic picker showing something real. It defaults to the first
  // topic in the whole bank, which for a student is usually NOT one of their
  // picked subject-levels — a Radix Select with a value that has no matching
  // item renders blank, so the control looked empty (and broken) while it was
  // silently filtering the question list.
  useEffect(() => {
    if (tab !== "topics" || visibleBankTopics.length === 0) return;
    if (!visibleBankTopics.some((t) => t.id === bankTopicId)) {
      setBankTopicId(visibleBankTopics[0].id);
    }
  }, [tab, visibleBankTopics, bankTopicId]);

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any practice content renders — nothing is shown while prefs
  // are loading or when nothing is picked. Early returns sit after every hook.
  if (!isAdmin && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Skeleton className="h-8 w-8 rounded-full" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/practice" />
        <SubjectGate />
      </div>
    );
  }

  // ---------- Render: active drill ----------
  if (drill.length > 0 && !drillDone) {
    const q = drill[drillIdx];
    return (
      <div className="max-w-2xl mx-auto space-y-5">
        <SEOHead path="/practice" />
        <div className="flex items-center justify-between">
          <Button variant="ghost" onClick={drillReset}>← Exit</Button>
          <Badge variant="outline">{drillIdx + 1} / {drill.length}</Badge>
        </div>
        <ManuscriptQuestion
          eyebrow={`Drill · ${drillIdx + 1} of ${drill.length} · ${q.topic_name}`}
          question={q.question_text}
          options={q.options}
          selected={drillSelected}
          correctOption={drillSelected !== null ? q.correct_option : null}
          disabled={drillSelected !== null}
          onSelect={handleDrillAnswer}
          explanation={drillSelected !== null ? q.explanation : null}
          footer={
            <>
              {drillCorrected && drillSelected !== null && (
                <p className="text-xs text-primary/90 flex items-center gap-1.5">
                  <Sparkles className="h-3.5 w-3.5" /> That one had you before — it doesn't now.
                </p>
              )}
              {drillSelected !== null && (
                <Button className="w-full mt-2" onClick={drillNext}>
                  {drillIdx + 1 < drill.length ? "Next question →" : "Finish session"}
                </Button>
              )}
            </>
          }
        />
      </div>
    );
  }

  if (drillDone) {
    const pct = Math.round((drillCorrect / drill.length) * 100);
    return (
      <div className="max-w-md mx-auto text-center space-y-4 py-10">
        <SEOHead path="/practice" />
        <Sparkles className="h-12 w-12 text-primary mx-auto" />
        <h2 className="text-2xl font-bold">Session complete</h2>
        <p className="text-4xl font-bold neon-text">{drillCorrect}/{drill.length}</p>
        <p className="text-muted-foreground">{pct}% on {drillTopic}</p>
        <FeedbackNudge tool="question" toolLabel={`${drillTopic} drill`} />
        <Button onClick={drillReset} className="gap-2"><RotateCcw className="h-4 w-4" /> Try another topic</Button>
      </div>
    );
  }

  // ---------- Render: topic-question focus view ----------
  if (bankActive) {
    return (
      <div className="max-w-2xl mx-auto space-y-5">
        <SEOHead path="/practice" />
        <div className="flex items-center justify-between">
          <Button variant="ghost" onClick={() => setBankActive(null)}>← Back to questions</Button>
          <Badge variant="outline">{bankActive.quiz_title}</Badge>
        </div>
        <ManuscriptQuestion
          eyebrow={`Question bank · ${bankActive.quiz_title}`}
          question={bankActive.question_text}
          options={bankActive.options}
          selected={bankSelected}
          correctOption={bankReveal ? bankReveal.correct_option : null}
          disabled={bankSelected !== null}
          onSelect={submitBankQuestion}
          explanation={bankReveal?.explanation ?? null}
          footer={
            <>
              {bankReveal?.corrected && (
                <p className="text-xs text-primary/90 flex items-center gap-1.5">
                  <Sparkles className="h-3.5 w-3.5" /> That one had you before — it doesn't now.
                </p>
              )}
              {bankReveal && (
                <Button className="w-full mt-2" onClick={() => setBankActive(null)}><RotateCcw className="h-4 w-4 mr-2" /> Pick another</Button>
              )}
            </>
          }
        />
      </div>
    );
  }

  // ---------- Render: hub ----------
  return (
    <div className="space-y-6">
      <SEOHead path="/practice" />
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
            <Target className="h-6 w-6 text-primary" /> Practice
          </h1>
          <p className="text-muted-foreground">Every question in one place: browse by topic, revisit the ones you're less sure of, and fix mistakes.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant={mode === "bookmarked" ? "secondary" : "outline"}
            size="sm"
            className="gap-1.5"
            aria-pressed={mode === "bookmarked"}
            onClick={() => {
              const next = new URLSearchParams(params);
              next.set("tab", "review");
              if (mode === "bookmarked") next.delete("mode");
              else next.set("mode", "bookmarked");
              setParams(next, { replace: true });
            }}
          >
            <Bookmark className="h-3.5 w-3.5" /> Bookmarked
          </Button>
          <SubjectPicker />
        </div>
      </div>

      <Tabs value={tab} onValueChange={(v) => setParam("tab", v)}>
        <TabsList className="flex-wrap h-auto justify-start gap-1">
          <TabsTrigger value="topics" className="gap-1.5"><Database className="h-3.5 w-3.5" /> Topic questions</TabsTrigger>
          <TabsTrigger value="review" className="gap-1.5"><RotateCcw className="h-3.5 w-3.5" /> Review</TabsTrigger>
          <TabsTrigger value="drills" className="gap-1.5"><Sparkles className="h-3.5 w-3.5" /> Smart drills</TabsTrigger>
        </TabsList>

        {/* Topic questions (old QuestionBank) */}
        <TabsContent value="topics" className="mt-4 space-y-4">
          <SavedProgressPanel
            summary={visibleBankSummary}
            loading={summaryLoading}
            error={null}
            onRetry={loadBankSummary}
            onJump={(id) => setBankTopicId(id)}
          />
          <Card>
            <CardContent className="flex flex-col sm:flex-row flex-wrap gap-3 p-4">
              <Select value={bankTopicId} onValueChange={setBankTopicId}>
                <SelectTrigger className="sm:w-60"><SelectValue placeholder="Pick a topic" /></SelectTrigger>
                <SelectContent>{visibleBankTopics.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
              </Select>
              <Select value={bankDifficulty} onValueChange={setBankDifficulty}>
                <SelectTrigger className="sm:w-40"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Any difficulty</SelectItem>
                  <SelectItem value="easy">Easy</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="hard">Hard</SelectItem>
                </SelectContent>
              </Select>
              <Select value={bankExamType} onValueChange={setBankExamType}>
                <SelectTrigger className="sm:w-40"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Any exam type</SelectItem>
                  <SelectItem value="quiz">Quiz</SelectItem>
                  <SelectItem value="exam">Exam</SelectItem>
                  <SelectItem value="mock">Mock</SelectItem>
                  <SelectItem value="ai_bank">Question bank</SelectItem>
                </SelectContent>
              </Select>
              <div className="relative flex-1 min-w-[180px]">
                <Search className="h-4 w-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
                <Input className="pl-9" aria-label="Search topic questions" placeholder="Search questions…" value={bankSearch} onChange={(e) => setBankSearch(e.target.value)} />
              </div>
            </CardContent>
          </Card>
          <QuestionList
            items={filteredBank}
            attempts={bankAttempts}
            onStart={startBankQuestion}
            onBookmark={(id, next) => setBankQuestions((prev) => prev.map((q) => q.id === id ? { ...q, bookmarked: next } : q))}
            loading={false}
          />
        </TabsContent>

        {/* Review (incorrect/bookmarked) */}
        <TabsContent value="review" className="mt-4 space-y-4">
          <Card>
            <CardContent className="flex flex-wrap items-center gap-3 p-4">
              {mode === "bookmarked" ? (
                <Badge variant="secondary" className="gap-1.5">
                  <Bookmark className="h-3.5 w-3.5" /> Bookmarked questions
                </Badge>
              ) : (
                <Tabs value={mode} onValueChange={(v) => setParam("mode", v)}>
                  <TabsList>
                    <TabsTrigger value="incorrect">Incorrect</TabsTrigger>
                    <TabsTrigger value="all">Both</TabsTrigger>
                  </TabsList>
                </Tabs>
              )}
              <Select value={defaultedLevelId} onValueChange={(v) => setParam("level", v)}>
                <SelectTrigger className="w-[230px]"><SelectValue placeholder="Subject & level" /></SelectTrigger>
                <SelectContent>
                  {isAdmin ? (
                    <SelectItem value="all">All subjects & levels</SelectItem>
                  ) : null}
                  {visibleLevelOptions.map((l) => <SelectItem key={l.id} value={l.id}>{l.label}</SelectItem>)}
                </SelectContent>
              </Select>
              <Select value={difficulty} onValueChange={setDifficulty}>
                <SelectTrigger className="w-[140px]"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Any difficulty</SelectItem>
                  <SelectItem value="easy">Easy</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="hard">Hard</SelectItem>
                </SelectContent>
              </Select>
              <div className="relative flex-1 min-w-[180px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search questions or topics" aria-label="Search review questions" className="pl-9" />
              </div>
            </CardContent>
          </Card>

          {error && (
            <Card className="border-destructive/40">
              <CardContent className="flex items-center justify-between gap-3 p-4">
                <p className="text-sm text-destructive flex items-center gap-2"><AlertCircle className="h-4 w-4" /> {error}</p>
                <Button size="sm" variant="outline" onClick={loadReviewQuestions}>Try again</Button>
              </CardContent>
            </Card>
          )}

          {active && (
            <ManuscriptQuestion
              eyebrow={`Review · ${active.topic_name ?? "General"} · ${active.quiz_title}`}
              question={active.question_text}
              options={active.options}
              selected={selected}
              correctOption={reveal ? reveal.correct_option : null}
              disabled={Boolean(reveal)}
              onSelect={(i) => !reveal && setSelected(i)}
              explanation={reveal?.explanation ?? null}
              actions={
                <BookmarkButton questionId={active.id} bookmarked={active.bookmarked}
                  onChange={(next) => setQuestions((p) => p.map((q) => q.id === active.id ? { ...q, bookmarked: next } : q))} />
              }
              footer={
                reveal ? (
                  <div className="space-y-3">
                    <p className={cn("text-sm font-semibold flex items-center gap-2", reveal.correct ? "text-emerald-600" : "text-destructive")}>
                      {reveal.correct ? <CheckCircle2 className="h-4 w-4" /> : <XCircle className="h-4 w-4" />}
                      {reveal.correct ? "Correct" : "Not quite"}
                    </p>
                    {reveal.corrected && (
                      <p className="text-sm text-primary/90 flex items-center gap-1.5">
                        <Sparkles className="h-4 w-4" /> That one had you before — it doesn't now.
                      </p>
                    )}
                    <div className="flex gap-2">
                      <Button size="sm" variant="outline" onClick={() => setActive(null)}>Close</Button>
                      <Button size="sm" onClick={() => startReview(active)}>Try again</Button>
                    </div>
                  </div>
                ) : (
                  <div className="flex gap-2">
                    <Button size="sm" onClick={submitReview} disabled={selected === null}>Check answer</Button>
                    <Button size="sm" variant="ghost" onClick={() => setActive(null)}>Cancel</Button>
                  </div>
                )
              }
            />
          )}

          {loading ? (
            <div className="space-y-3">{[0, 1, 2].map((i) => <Skeleton key={i} className="h-20 rounded-2xl" />)}</div>
          ) : filteredReview.length === 0 ? (
            <Card>
              <CardContent className="p-8 text-center space-y-2">
                <Bookmark className="h-8 w-8 mx-auto text-muted-foreground/50" />
                <p className="text-sm text-muted-foreground">
                  {mode === "bookmarked" ? "You haven't bookmarked any questions yet." : "Nothing to review — great work!"}
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-3">
              {filteredReview.map((q) => (
                <Card key={q.id}>
                  <CardContent className="flex items-center justify-between gap-3 p-4">
                    <div className="min-w-0">
                      <p className="text-sm font-medium line-clamp-2">{q.question_text}</p>
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        <Badge variant="secondary">{q.topic_name ?? "General"}</Badge>
                        <Badge variant="outline" className="capitalize">{q.difficulty}</Badge>
                        {q.last_correct === false && <Badge variant="outline" className="text-destructive border-destructive/40">Incorrect</Badge>}
                        {q.bookmarked && <Badge variant="outline" className="text-primary border-primary/40">Bookmarked</Badge>}
                        {q.attempts_count > 0 && <Badge variant="outline">{q.attempts_count} attempts</Badge>}
                      </div>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                      <BookmarkButton questionId={q.id} bookmarked={q.bookmarked}
                        onChange={(next) => setQuestions((p) => p.map((x) => x.id === q.id ? { ...x, bookmarked: next } : x))} />
                      <Button size="sm" onClick={() => startReview(q)}>Practise</Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        {/* Smart drills */}
        <TabsContent value="drills" className="mt-4">
          <section className="space-y-3">
            {loadingWeak ? (
              <p className="text-sm text-muted-foreground">Loading…</p>
            ) : (
              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                {visibleWeakTopics.slice(0, 9).map((t, i) => (
                  <Card key={t.id} className={cn("transition-all hover:border-primary/40", i === 0 && "neon-border")}>
                    <CardContent className="p-4 flex items-center justify-between gap-3">
                      <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          {i === 0 && <Badge className="text-[10px] bg-primary/15 text-primary border-primary/30">Top priority</Badge>}
                          <span className="text-xs text-muted-foreground">Avg {t.avg}%</span>
                        </div>
                        <p className="font-semibold text-sm truncate">{t.name}</p>
                      </div>
                      <Button
                        size="sm"
                        onClick={() => buildSession(t.id, t.name)}
                        disabled={drillLoadingId !== null}
                        className="gap-1 shrink-0"
                      >
                        <Brain className="h-4 w-4" />
                        {drillLoadingId === t.id ? "Starting…" : "Drill"}
                      </Button>
                    </CardContent>
                  </Card>
                ))}
                {visibleWeakTopics.length === 0 && (
                  <Card className="sm:col-span-2 lg:col-span-3"><CardContent className="py-6 text-center text-sm text-muted-foreground">
                    <Layers className="h-8 w-8 mx-auto mb-2 opacity-40" />
                    Complete a quiz and we'll point you at the topics worth revisiting.
                  </CardContent></Card>
                )}
              </div>
            )}
          </section>
        </TabsContent>
      </Tabs>
    </div>
  );
}

// Pricing: preview tier + three paid plans ($40/mo, $24/mo billed quarterly, $6.67/mo billed annually).
// Exactly two payment methods: Bank Transfer or E-Wallet (Urpay). Requesting a
// plan captures the payer's full name and a transaction receipt; an admin then
