            onClick={() => onCopy(row.value, row.key)}
            aria-label={`Copy ${row.key}`}
          >
            {copied === row.key ? <Check className="h-3.5 w-3.5 text-primary" /> : <Copy className="h-3.5 w-3.5" />}
            <span className="text-[11px]">{copied === row.key ? "Copied" : "Copy"}</span>
