export default function AdminAnnouncements() {
  const { toast } = useToast();
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  const load = () =>
    supabase
      .from("announcements")
      .select("*")
      .order("published_at", { ascending: false })
      .then(({ data, error }) => {
        if (error) {
          toast({ title: "Could not load announcements", description: error.message, variant: "destructive" });
          return;
        }
        setAnnouncements(data ?? []);
      });

  useEffect(() => { load(); }, []);

  const save = async () => {
    const { error } = await supabase.from("announcements").insert({ title, content });
    // A refused post used to clear the form and toast "Posted" — the
    // announcement was simply never there.
    if (error) {
      toast(contentSaveError("Could not post the announcement", error.message));
      return;
    }
    toast({ title: "Posted" });
    setOpen(false); setTitle(""); setContent(""); load();
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div><h1 className="text-2xl font-bold tracking-tight">Announcements</h1><p className="text-muted-foreground">Post updates</p></div>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild><Button className="gap-2"><Plus className="h-4 w-4" /> Post</Button></DialogTrigger>
          <DialogContent>
            <DialogHeader><DialogTitle>New Announcement</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} /></div>
              <div><Label>Content</Label><Textarea value={content} onChange={(e) => setContent(e.target.value)} /></div>
              <Button onClick={save} className="w-full">Post</Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
      <div className="space-y-3">
        {announcements.map((a) => (
          <Card key={a.id}>
            <CardContent className="flex items-center justify-between p-4">
              <div>
                <p className="font-medium">{a.title}</p>
                <p className="text-xs text-muted-foreground">{format(new Date(a.published_at), "PPP")}</p>
              </div>
              <Button size="icon" variant="ghost" aria-label={`Delete ${a.title}`} title={`Delete ${a.title}`} onClick={async () => { await supabase.from("announcements").delete().eq("id", a.id); load(); }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

// Audit-trail viewer: filters, archive toggle, CSV export.
import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import type { SupabaseClient } from "@supabase/supabase-js";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ChevronLeft, ChevronRight, Download, Search } from "lucide-react";
import { format } from "date-fns";

const PAGE_SIZE = 50;

// One owner for the audit filters: both the live table and the CSV export build
// their query through this, so adding a filter never silently diverges the two.
function buildAuditQuery(
  supabaseClient: SupabaseClient,
  table: "admin_audit_log" | "admin_audit_log_archive",
  select: string,
  { entityFilter, search, from, to }: { entityFilter: string; search: string; from?: number; to?: number }
) {
  let q = supabaseClient
    .from(table)
    .select(select, from !== undefined ? { count: "exact" } : undefined)
    .order("created_at", { ascending: false });
  if (from !== undefined && to !== undefined) q = q.range(from, to);
  if (entityFilter !== "all") q = q.eq("entity", entityFilter);
  if (search.trim()) q = q.ilike("entity_label", `%${search.trim()}%`);
  return q;
}

const ACTION_STYLES: Record<string, string> = {
  create: "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400",
  update: "bg-blue-500/15 text-blue-600 dark:text-blue-400",
  delete: "bg-red-500/15 text-red-600 dark:text-red-400",
  approve: "bg-violet-500/15 text-violet-600 dark:text-violet-400",
  reject: "bg-orange-500/15 text-orange-600 dark:text-orange-400",
  role_change: "bg-amber-500/15 text-amber-600 dark:text-amber-400",
  login: "bg-slate-500/15 text-slate-600 dark:text-slate-400",
  download: "bg-teal-500/15 text-teal-600 dark:text-teal-400",
  quiz_attempt: "bg-sky-500/15 text-sky-600 dark:text-sky-400",
  homework_submission: "bg-indigo-500/15 text-indigo-600 dark:text-indigo-400",
};

const ENTITY_OPTIONS = [
  "lessons", "topics", "quizzes", "questions", "past_papers", "study_materials",
  "subjects", "subject_levels", "announcements", "homework", "flashcards",
  "flashcard_sets", "user", "user_credentials", "quiz_attempt", "homework_submission",
];

function LabelDisplay({ label }: { label: string | null }) {
  if (!label) return <span className="text-muted-foreground">—</span>;
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(label);
  return <span className="font-mono text-xs">{isUuid ? `${label.slice(0, 8)}…` : label}</span>;
}

export default function AdminAuditLog() {
  const { role } = useAuth();
  const [logs, setLogs] = useState<any[]>([]);
  const [count, setCount] = useState(0);
  const [page, setPage] = useState(0);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [entityFilter, setEntityFilter] = useState<string>("all");
  const [inArchive, setInArchive] = useState(false);

  useEffect(() => { setPage(0); }, [search, entityFilter, inArchive]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    (async () => {
      const table = inArchive ? "admin_audit_log_archive" : "admin_audit_log";
      const { data, count: total, error } = await buildAuditQuery(
        supabase, table, "*",
        { entityFilter, search, from: page * PAGE_SIZE, to: page * PAGE_SIZE + PAGE_SIZE - 1 }
      );
      if (!cancelled) {
        if (error) console.error(error);
        setLogs(data ?? []);
        setCount(total ?? 0);
        setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [page, search, entityFilter, inArchive]);

  // Export: streams ALL rows matching the current filters (not just this page)
  // through Supabase pagination, then downloads as CSV.
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState<string | null>(null);

  const exportCsv = async () => {
    setExporting(true);
    setExportError(null);
    try {
      const BATCH = 1000;
      const rows: Array<Record<string, unknown>> = [];
      for (let from = 0; ; from += BATCH) {
        const { data, error } = await buildAuditQuery(
          supabase,
          inArchive ? "admin_audit_log_archive" : "admin_audit_log",
          "created_at, actor_username, action, entity, entity_label, details",
          { entityFilter, search, from, to: from + BATCH - 1 }
        );
        if (error) throw new Error(String(error));
        rows.push(...((data ?? []) as unknown as Array<Record<string, unknown>>));
        if (!data || data.length < BATCH) break;
      }

      const esc = (v: unknown) => {
        const s =
          v === null || v === undefined
            ? ""
            : typeof v === "object"
              ? JSON.stringify(v)
              : String(v);
        return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
      };
      const header = "timestamp,actor,action,entity,item,details";
      const body = rows
        .map((r) =>
          [r.created_at, r.actor_username ?? "system", r.action, r.entity, r.entity_label ?? "", r.details]
            .map(esc)
            .join(",")
        )
        .join("\n");
      const blob = new Blob([header + "\n" + body], { type: "text/csv;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      const filterTag = entityFilter !== "all" ? `-${entityFilter}` : "";
      a.download = `audit-log${inArchive ? "-archive" : ""}${filterTag}-${format(new Date(), "yyyy-MM-dd")}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      console.error(e);
      setExportError("Export failed — check your connection and try again.");
    } finally {
      setExporting(false);
    }
  };

  const pages = Math.max(1, Math.ceil(count / PAGE_SIZE));
  const rangeLabel = useMemo(
    () => (count === 0 ? "0" : `${page * PAGE_SIZE + 1}–${Math.min((page + 1) * PAGE_SIZE, count)} of ${count}`),
    [count, page]
  );

  // Non-approved admins get nothing from RLS; show an explicit empty state.
  if (role !== "admin") {
    return (
      <div className="space-y-6">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Audit Log</h1>
          <p className="text-muted-foreground">Admin activity history</p>
        </div>
        <Card>
          <CardContent className="p-10 text-center text-muted-foreground">
            Only approved admins can view the audit log.
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Audit Log</h1>
        <p className="text-muted-foreground">Admin activity, student quiz attempts, and homework submissions</p>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <div className="relative flex-1 min-w-56 max-w-sm">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by title or name…"
            className="pl-8"
          />
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {exportError && <span className="text-xs text-destructive">{exportError}</span>}
          <Button variant="outline" size="sm" onClick={exportCsv} disabled={exporting || loading}>
            <Download className="h-4 w-4" />
            {exporting ? "Exporting…" : "Export CSV"}
          </Button>
          <Label className="text-xs text-muted-foreground">View</Label>
          <Select value={inArchive ? "archive" : "live"} onValueChange={(v) => setInArchive(v === "archive")}>
            <SelectTrigger className="w-36"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="live">Active log</SelectItem>
              <SelectItem value="archive">Archive (&gt;12mo)</SelectItem>
            </SelectContent>
          </Select>
          <Label className="text-xs text-muted-foreground">Type</Label>
          <Select value={entityFilter} onValueChange={setEntityFilter}>
            <SelectTrigger className="w-44"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All entities</SelectItem>
              {ENTITY_OPTIONS.map((e) => (
                <SelectItem key={e} value={e}>{e.replace(/_/g, " ")}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>When</TableHead>
                <TableHead>Actor</TableHead>
                <TableHead>Action</TableHead>
                <TableHead>Entity</TableHead>
                <TableHead>Item</TableHead>
                <TableHead className="text-right">Details</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={6} className="py-10 text-center text-muted-foreground">Loading…</TableCell>
                </TableRow>
              ) : logs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="py-10 text-center text-muted-foreground">
                    No audit entries match. Changes made in the admin panel will appear here.
                  </TableCell>
                </TableRow>
              ) : (
                logs.map((log) => (
                  <TableRow key={log.id}>
                    <TableCell className="whitespace-nowrap text-xs">
                      {format(new Date(log.created_at), "MMM d, HH:mm:ss")}
                    </TableCell>
                    <TableCell className="text-sm font-medium">
                      {log.actor_username ?? <span className="text-muted-foreground italic">system</span>}
                    </TableCell>
                    <TableCell>
                      <span className={`inline-flex rounded-md px-2 py-0.5 text-xs font-semibold capitalize ${ACTION_STYLES[log.action] ?? "bg-muted text-muted-foreground"}`}>
                        {log.action}
                      </span>
                    </TableCell>
                    <TableCell className="text-sm capitalize">{log.entity.replace(/_/g, " ")}</TableCell>
                    <TableCell className="max-w-64 truncate"><LabelDisplay label={log.entity_label} /></TableCell>
                    <TableCell className="text-right">
                      {log.details && Object.keys(log.details).length > 0 ? (
                        <Dialog>
                          <DialogTrigger asChild>
                            <Button variant="ghost" size="sm">View</Button>
                          </DialogTrigger>
                          <DialogContent className="max-w-2xl">
                            <DialogHeader>
                              <DialogTitle className="capitalize">
                                {log.action} — {log.entity.replace(/_/g, " ")} — {log.entity_label ?? ""}
                              </DialogTitle>
                            </DialogHeader>
                            <ScrollArea className="max-h-96 rounded-md border bg-muted/30 p-3">
                              <pre className="whitespace-pre-wrap break-all text-xs">{JSON.stringify(log.details, null, 2)}</pre>
                            </ScrollArea>
                          </DialogContent>
                        </Dialog>
                      ) : (
                        <span className="text-muted-foreground">—</span>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <div className="flex items-center justify-between">
        <p className="text-xs text-muted-foreground">{rangeLabel} entries</p>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" disabled={page === 0} onClick={() => setPage((p) => p - 1)}>
            <ChevronLeft className="h-4 w-4" /> Prev
          </Button>
          <span className="text-xs text-muted-foreground">Page {page + 1} / {pages}</span>
          <Button variant="outline" size="sm" disabled={page + 1 >= pages} onClick={() => setPage((p) => p + 1)}>
            Next <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>
    </div>
  );
}

// Manage flashcard decks.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Plus, Pencil, Trash2, ChevronDown, ChevronUp, Layers } from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import { contentSaveError } from "@/lib/contentGuards";

export default function AdminFlashcards() {
  const { toast } = useToast();
  const [sets, setSets] = useState<any[]>([]);
  const [topics, setTopics] = useState<any[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [topicId, setTopicId] = useState<string>("");
  const [expandedSet, setExpandedSet] = useState<string | null>(null);
  const [cards, setCards] = useState<any[]>([]);
  const [cardFront, setCardFront] = useState("");
  const [cardBack, setCardBack] = useState("");
  const [editingCard, setEditingCard] = useState<any>(null);
  const { failure, report, clear } = useLoadFailure("flashcard sets");

  const load = async () => {
    clear();
    const [setsRes, topicsRes] = await Promise.all([
      supabase.from("flashcard_sets").select("*, topics(name)").order("created_at", { ascending: false }),
      supabase.from("topics").select("*").order("sort_order"),
    ]);
    // `?? []` on a failed request rendered "No flashcard sets yet" over a console
    // that actually holds data.
    const error = setsRes.error ?? topicsRes.error;
    if (error) {
      report(error);
      setSets([]);
      setTopics([]);
      return;
    }
    setSets(setsRes.data ?? []);
    setTopics(topicsRes.data ?? []);
  };

  useEffect(() => { load(); }, []);

  const loadCards = async (setId: string) => {
    const { data, error } = await supabase.from("flashcards").select("*").eq("set_id", setId).order("sort_order");
    // A failed read looked like a deck that has no cards.
    if (error) {
      report(error);
      setCards([]);
      return;
    }
    setCards(data ?? []);
  };

  const toggleExpand = (setId: string) => {
    if (expandedSet === setId) {
      setExpandedSet(null);
      setCards([]);
    } else {
      setExpandedSet(setId);
      loadCards(setId);
    }
  };

  const saveSet = async () => {
    const payload = {
      title,
      description: description || null,
      topic_id: topicId || null,
    };
    const { error } = editing
      ? await supabase.from("flashcard_sets").update(payload).eq("id", editing.id)
      : await supabase.from("flashcard_sets").insert(payload);
    // The dialog used to close and toast "Set created" for a refused write,
    // leaving the admin with an empty list and no idea why.
    if (error) {
      toast(contentSaveError("Could not save the set", error.message));
      return;
    }
    resetForm();
    load();
    toast({ title: editing ? "Set updated" : "Set created" });
  };

  const deleteSet = async (id: string) => {
    await supabase.from("flashcard_sets").delete().eq("id", id);
    if (expandedSet === id) setExpandedSet(null);
    load();
    toast({ title: "Set deleted" });
  };

  const editSet = (s) => {
    setEditing(s);
    setTitle(s.title);
    setDescription(s.description ?? "");
    setTopicId(s.topic_id ?? "");
    setOpen(true);
  };

  const resetForm = () => {
    setOpen(false);
    setEditing(null);
    setTitle("");
    setDescription("");
    setTopicId("");
  };

  const saveCard = async () => {
    if (!expandedSet) return;
    const payload = { set_id: expandedSet, front: cardFront, back: cardBack, sort_order: cards.length };
    const { error } = editingCard
      ? await supabase.from("flashcards").update({ front: cardFront, back: cardBack }).eq("id", editingCard.id)
      : await supabase.from("flashcards").insert(payload);
    // Clearing the form on a refused write threw away what the admin had typed.
    if (error) {
      toast(contentSaveError("Could not save the card", error.message));
      return;
    }
    setCardFront("");
    setCardBack("");
    setEditingCard(null);
    loadCards(expandedSet);
    toast({ title: editingCard ? "Card updated" : "Card added" });
  };

  const deleteCard = async (id: string) => {
    await supabase.from("flashcards").delete().eq("id", id);
    if (expandedSet) loadCards(expandedSet);
    toast({ title: "Card deleted" });
  };

  const startEditCard = (c) => {
    setEditingCard(c);
    setCardFront(c.front);
    setCardBack(c.back);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Manage Flashcard Sets</h1>
          <p className="text-muted-foreground text-sm">Create and manage flashcard sets for student revision</p>
        </div>
        <Dialog open={open} onOpenChange={(v) => { if (!v) resetForm(); else setOpen(true); }}>
          <DialogTrigger asChild>
            <Button className="gap-2"><Plus className="h-4 w-4" /> New Set</Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader><DialogTitle>{editing ? "Edit" : "Create"} Flashcard Set</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Marketing Mix" /></div>
              <div><Label>Description</Label><Textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Optional description" /></div>
              <div>
                <Label>Topic</Label>
                <Select value={topicId} onValueChange={setTopicId}>
                  <SelectTrigger><SelectValue placeholder="Select topic (optional)" /></SelectTrigger>
                  <SelectContent>
                    {topics.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <Button onClick={saveSet} disabled={!title.trim()} className="w-full">{editing ? "Update" : "Create"} Set</Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {failure && <QueryError message={failure} onRetry={load} />}

      {sets.length === 0 && (
        <Card className="border-dashed"><CardContent className="py-12 text-center text-muted-foreground"><Layers className="mx-auto h-10 w-10 mb-3 opacity-40" />No flashcard sets yet. Create one to get started.</CardContent></Card>
      )}

      <div className="space-y-3">
        {sets.map((s) => (
          <Card key={s.id} className="overflow-hidden">
            <div className="flex items-center justify-between p-4 cursor-pointer hover:bg-muted/30 transition-colors" onClick={() => toggleExpand(s.id)}>
              <div className="flex flex-wrap items-center gap-x-3 gap-y-1 min-w-0">
                <Layers className="h-5 w-5 text-primary shrink-0" />
                <div className="min-w-0">
                  <p className="font-semibold text-foreground truncate">{s.title}</p>
                  {s.description && <p className="text-xs text-muted-foreground truncate">{s.description}</p>}
                </div>
                {s.topics?.name && <Badge variant="secondary" className="shrink-0 max-w-full">{s.topics.name}</Badge>}
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <Button variant="ghost" size="icon" aria-label={`Edit ${s.title}`} title={`Edit ${s.title}`} onClick={(e) => { e.stopPropagation(); editSet(s); }}><Pencil className="h-4 w-4" /></Button>
                <Button variant="ghost" size="icon" aria-label={`Delete ${s.title}`} title={`Delete ${s.title}`} onClick={(e) => { e.stopPropagation(); deleteSet(s.id); }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
                {expandedSet === s.id ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
              </div>
            </div>

            {expandedSet === s.id && (
              <div className="border-t bg-muted/10 p-4 space-y-4">
                <div className="flex flex-wrap gap-2 items-end">
                  <div className="flex-1 min-w-[9rem]"><Label className="text-xs">Front</Label><Input value={cardFront} onChange={(e) => setCardFront(e.target.value)} placeholder="Question / term" /></div>
                  <div className="flex-1 min-w-[9rem]"><Label className="text-xs">Back</Label><Input value={cardBack} onChange={(e) => setCardBack(e.target.value)} placeholder="Answer / definition" /></div>
                  <div className="ml-auto flex gap-2">
                    <Button onClick={saveCard} disabled={!cardFront.trim() || !cardBack.trim()} size="sm">{editingCard ? "Update" : "Add"}</Button>
                    {editingCard && <Button variant="ghost" size="sm" onClick={() => { setEditingCard(null); setCardFront(""); setCardBack(""); }}>Cancel</Button>}
                  </div>
                </div>

                {cards.length === 0 ? (
                  <p className="text-sm text-muted-foreground text-center py-4">No cards yet. Add your first card above.</p>
                ) : (
                  <div className="space-y-2">
                    {cards.map((c, i) => (
                      <div key={c.id} className="flex items-center gap-3 rounded-lg border bg-background p-3">
                        <span className="text-xs text-muted-foreground w-6">{i + 1}</span>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium truncate">{c.front}</p>
                          <p className="text-xs text-muted-foreground truncate">{c.back}</p>
                        </div>
                        <Button variant="ghost" size="icon" className="h-8 w-8" aria-label={`Edit card “${c.front}”`} title="Edit card" onClick={() => startEditCard(c)}><Pencil className="h-3 w-3" /></Button>
                        <Button variant="ghost" size="icon" className="h-8 w-8" aria-label={`Delete card “${c.front}”`} title="Delete card" onClick={() => deleteCard(c.id)}><Trash2 className="h-3 w-3 text-destructive" /></Button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </Card>
        ))}
      </div>
    </div>
  );
}

// Per-student grade overview.
import { useEffect, useState, useCallback, useMemo } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Download, Search, BookOpen, ClipboardList, TrendingUp, User } from "lucide-react";
import { cn } from "@/lib/utils";

interface StudentGrade {
  userId: string;
  fullName: string;
  username: string | null;
  email: string | null;
  quizAttempts: { quizTitle: string; score: number; total: number; completedAt: string }[];
  homeworkGrades: { hwTitle: string; grade: string | null; status: string; submittedAt: string }[];
  quizAvg: number;
}

export default function AdminGradeBook() {
  const { role } = useAuth();
  const [students, setStudents] = useState<StudentGrade[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState<"name" | "quiz_avg">("name");
  const [selectedStudent, setSelectedStudent] = useState<StudentGrade | null>(null);

  const loadGrades = useCallback(async () => {
    setLoading(true);

    const [profilesRes, rolesRes, attemptsRes, quizzesRes, submissionsRes, homeworkRes] = await Promise.all([
      supabase.from("profiles").select("user_id, full_name, username, email"),
      supabase.from("user_roles").select("user_id, role, is_approved").eq("role", "student").eq("is_approved", true),
      supabase.from("quiz_attempts").select("user_id, quiz_id, score, total_questions, completed_at").not("completed_at", "is", null),
      supabase.from("quizzes").select("id, title"),
      supabase.from("homework_submissions").select("user_id, homework_id, grade, status, submitted_at"),
      supabase.from("homework").select("id, title"),
    ]);

    const approvedStudentIds = new Set((rolesRes.data ?? []).map((r) => r.user_id));
    const quizMap = Object.fromEntries((quizzesRes.data ?? []).map((q) => [q.id, q.title]));
    const hwMap = Object.fromEntries((homeworkRes.data ?? []).map((h) => [h.id, h.title]));

    const attemptsByUser: Record<string, StudentGrade["quizAttempts"]> = {};
    (attemptsRes.data ?? []).forEach((a) => {
      if (!approvedStudentIds.has(a.user_id)) return;
      if (!attemptsByUser[a.user_id]) attemptsByUser[a.user_id] = [];
      attemptsByUser[a.user_id].push({
        quizTitle: quizMap[a.quiz_id] ?? "Unknown Quiz",
        score: a.score ?? 0,
        total: a.total_questions ?? 0,
        completedAt: a.completed_at ?? "",
      });
    });

    const subsByUser: Record<string, StudentGrade["homeworkGrades"]> = {};
    (submissionsRes.data ?? []).forEach((s) => {
      if (!approvedStudentIds.has(s.user_id)) return;
      if (!subsByUser[s.user_id]) subsByUser[s.user_id] = [];
      subsByUser[s.user_id].push({
        hwTitle: hwMap[s.homework_id] ?? "Unknown Homework",
        grade: s.grade,
        status: s.status,
        submittedAt: s.submitted_at,
      });
    });

    const studentGrades: StudentGrade[] = (profilesRes.data ?? [])
      .filter((p) => approvedStudentIds.has(p.user_id))
      .map((p) => {
        const quizAttempts = attemptsByUser[p.user_id] ?? [];
        const quizAvg = quizAttempts.length > 0
          ? quizAttempts.reduce((sum, a) => sum + (a.total > 0 ? (a.score / a.total) * 100 : 0), 0) / quizAttempts.length
          : -1;
        return {
          userId: p.user_id,
          fullName: p.full_name || "Unnamed",
          username: p.username,
          email: p.email,
          quizAttempts,
          homeworkGrades: subsByUser[p.user_id] ?? [],
          quizAvg,
        };
      });

    setStudents(studentGrades);
    setLoading(false);
  }, []);

  useEffect(() => { loadGrades(); }, [loadGrades]);

  const filtered = useMemo(() => {
    const list = students.filter((s) =>
      s.fullName.toLowerCase().includes(search.toLowerCase()) ||
      (s.email ?? "").toLowerCase().includes(search.toLowerCase())
    );
    if (sortBy === "name") list.sort((a, b) => a.fullName.localeCompare(b.fullName));
    else list.sort((a, b) => b.quizAvg - a.quizAvg);
    return list;
  }, [students, search, sortBy]);

  const exportPdf = async (student?: StudentGrade) => {
    const target = student ? [student] : filtered;
    const { default: jsPDF } = await import("jspdf");
    const doc = new jsPDF({ orientation: "landscape" });

    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    const margin = 14;
    let y = margin;

    const addHeader = (title: string) => {
      doc.setFontSize(16);
      doc.setFont("helvetica", "bold");
      doc.text(title, margin, y);
      y += 6;
      doc.setFontSize(8);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(120);
      doc.text(`Generated: ${new Date().toLocaleDateString()}`, margin, y);
      doc.setTextColor(0);
      y += 8;
    };

    const checkPage = (need: number) => {
      if (y + need > pageH - margin) { doc.addPage(); y = margin; }
    };

    const drawTable = (headers: string[], rows: string[][], colWidths: number[]) => {
      const rowH = 7;
      checkPage(rowH * 2);

      // Header
      doc.setFillColor(43, 43, 43);
      doc.rect(margin, y, colWidths.reduce((a, b) => a + b, 0), rowH, "F");
      doc.setFontSize(8);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(255);
      let x = margin;
      headers.forEach((h, i) => { doc.text(h, x + 2, y + 5); x += colWidths[i]; });
      doc.setTextColor(0);
      y += rowH;

      // Rows
      doc.setFont("helvetica", "normal");
      rows.forEach((row, ri) => {
        checkPage(rowH);
        if (ri % 2 === 0) {
          doc.setFillColor(245, 245, 245);
          doc.rect(margin, y, colWidths.reduce((a, b) => a + b, 0), rowH, "F");
        }
        x = margin;
        row.forEach((cell, ci) => {
          const maxW = colWidths[ci] - 4;
          const txt = doc.splitTextToSize(cell, maxW)[0] ?? cell;
          doc.text(txt, x + 2, y + 5);
          x += colWidths[ci];
        });
        y += rowH;
      });
      y += 4;
    };

    if (student) {
      addHeader(`Grade Report: ${student.fullName}`);

      if (student.quizAttempts.length > 0) {
        doc.setFontSize(11);
        doc.setFont("helvetica", "bold");
        doc.text("Quiz Scores", margin, y);
        y += 6;
        const colW = [100, 40, 40, 80];
        drawTable(
          ["Quiz", "Score", "Percentage", "Date"],
          student.quizAttempts.map((a) => [
            a.quizTitle,
            `${a.score}/${a.total}`,
            a.total > 0 ? `${Math.round((a.score / a.total) * 100)}%` : "N/A",
            a.completedAt ? new Date(a.completedAt).toLocaleDateString() : "-",
          ]),
          colW
        );
        if (student.quizAvg >= 0) {
          doc.setFont("helvetica", "bold");
          doc.text(`Quiz Average: ${Math.round(student.quizAvg)}%`, margin, y);
          y += 8;
        }
      }

      if (student.homeworkGrades.length > 0) {
        checkPage(20);
        doc.setFontSize(11);
        doc.setFont("helvetica", "bold");
        doc.text("Homework Grades", margin, y);
        y += 6;
        const colW = [100, 50, 50, 60];
        drawTable(
          ["Homework", "Grade", "Status", "Submitted"],
          student.homeworkGrades.map((h) => [
            h.hwTitle,
            h.grade ?? "-",
            h.status,
            new Date(h.submittedAt).toLocaleDateString(),
          ]),
          colW
        );
      }
    } else {
      addHeader("Grade Book — All Students");

      const colW = [60, 50, 30, 30, 35, 30, 30];
      const totalW = colW.reduce((a, b) => a + b, 0);
      drawTable(
        ["Student", "Username", "Quizzes", "Quiz Avg", "Homeworks", "Graded", "Pending"],
        target.map((s) => {
          const graded = s.homeworkGrades.filter((h) => h.status === "graded").length;
          const pending = s.homeworkGrades.filter((h) => h.status === "pending").length;
          return [
            s.fullName,
            s.email ?? "-",
            String(s.quizAttempts.length),
            s.quizAvg >= 0 ? `${Math.round(s.quizAvg)}%` : "-",
            String(s.homeworkGrades.length),
            String(graded),
            String(pending),
          ];
        }),
        colW
      );
    }

    const filename = student
      ? `grade-report-${student.fullName.replace(/\s+/g, "-").toLowerCase()}.pdf`
      : "grade-book-all-students.pdf";
    doc.save(filename);
  };

  if (role !== "admin") {
    return <div className="p-8 text-center text-muted-foreground">Only admins can access the grade book.</div>;
  }

  const totalQuizAttempts = students.reduce((s, st) => s + st.quizAttempts.length, 0);
  const totalHomework = students.reduce((s, st) => s + st.homeworkGrades.length, 0);
  const overallAvg = students.filter((s) => s.quizAvg >= 0);
  const avgScore = overallAvg.length > 0
    ? Math.round(overallAvg.reduce((s, st) => s + st.quizAvg, 0) / overallAvg.length)
    : 0;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Grade Book</h1>
          <p className="text-sm text-muted-foreground">Consolidated view of all student grades</p>
        </div>
        <Button onClick={() => exportPdf()} className="gap-2">
          <Download className="h-4 w-4" /> Export All as PDF
        </Button>
      </div>

      {/* Summary cards */}
      <div className="grid gap-4 sm:grid-cols-3">
        <Card>
          <CardContent className="pt-6 flex items-center gap-4">
            <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center">
              <User className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">{students.length}</p>
              <p className="text-xs text-muted-foreground">Students</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6 flex items-center gap-4">
            <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center">
              <BookOpen className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">{totalQuizAttempts}</p>
              <p className="text-xs text-muted-foreground">Quiz Attempts</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6 flex items-center gap-4">
            <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center">
              <TrendingUp className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">{avgScore}%</p>
              <p className="text-xs text-muted-foreground">Class Quiz Average</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input placeholder="Search students..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9" />
        </div>
        <Select value={sortBy} onValueChange={(v) => setSortBy(v as any)}>
          <SelectTrigger className="w-[180px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="name">Sort by Name</SelectItem>
            <SelectItem value="quiz_avg">Sort by Quiz Avg</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Table */}
      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Student</TableHead>
                <TableHead className="text-center">Quizzes</TableHead>
                <TableHead className="text-center">Quiz Avg</TableHead>
                <TableHead className="text-center">Homework</TableHead>
                <TableHead className="text-center">Graded</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow><TableCell colSpan={6} className="text-center py-12 text-muted-foreground">Loading...</TableCell></TableRow>
              ) : filtered.length === 0 ? (
                <TableRow><TableCell colSpan={6} className="text-center py-12 text-muted-foreground">No students found</TableCell></TableRow>
              ) : (
                filtered.map((s) => {
                  const graded = s.homeworkGrades.filter((h) => h.status === "graded").length;
                  return (
                    <TableRow key={s.userId} className="cursor-pointer hover:bg-muted/50" onClick={() => setSelectedStudent(s)}>
                      <TableCell>
                        <div>
                          <p className="font-medium text-foreground">{s.fullName}</p>
                          {s.email && <p className="text-xs text-muted-foreground">{s.email}</p>}
                        </div>
                      </TableCell>
                      <TableCell className="text-center">{s.quizAttempts.length}</TableCell>
                      <TableCell className="text-center">
                        {s.quizAvg >= 0 ? (
                          <Badge className={cn("text-xs",
                            s.quizAvg >= 70 ? "bg-success text-success-foreground" :
                            s.quizAvg >= 50 ? "bg-warning text-warning-foreground" :
                            "bg-destructive text-destructive-foreground"
                          )}>
                            {Math.round(s.quizAvg)}%
                          </Badge>
                        ) : <span className="text-muted-foreground text-xs">-</span>}
                      </TableCell>
                      <TableCell className="text-center">{s.homeworkGrades.length}</TableCell>
                      <TableCell className="text-center">{graded}/{s.homeworkGrades.length}</TableCell>
                      <TableCell className="text-right">
                        <Button size="sm" variant="outline" className="gap-1" onClick={(e) => { e.stopPropagation(); exportPdf(s); }}>
                          <Download className="h-3 w-3" /> PDF
                        </Button>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Student detail dialog */}
      <Dialog open={!!selectedStudent} onOpenChange={(open) => !open && setSelectedStudent(null)}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          {selectedStudent && (
            <>
              <DialogHeader>
                <DialogTitle className="flex items-center justify-between">
                  <span>{selectedStudent.fullName}</span>
                  <Button size="sm" variant="outline" className="gap-1" onClick={() => exportPdf(selectedStudent)}>
                    <Download className="h-3 w-3" /> Export PDF
                  </Button>
                </DialogTitle>
              </DialogHeader>

              {/* Quiz scores */}
              <div className="space-y-3">
                <h3 className="text-sm font-semibold text-foreground flex items-center gap-2">
                  <BookOpen className="h-4 w-4 text-primary" /> Quiz Scores
                  {selectedStudent.quizAvg >= 0 && (
                    <Badge variant="secondary" className="text-xs">Avg: {Math.round(selectedStudent.quizAvg)}%</Badge>
                  )}
                </h3>
                {selectedStudent.quizAttempts.length === 0 ? (
                  <p className="text-sm text-muted-foreground">No quiz attempts yet.</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Quiz</TableHead>
                        <TableHead className="text-center">Score</TableHead>
                        <TableHead className="text-center">%</TableHead>
                        <TableHead className="text-right">Date</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {selectedStudent.quizAttempts.map((a, i) => {
                        const pct = a.total > 0 ? Math.round((a.score / a.total) * 100) : 0;
                        return (
                          <TableRow key={i}>
                            <TableCell className="font-medium">{a.quizTitle}</TableCell>
                            <TableCell className="text-center">{a.score}/{a.total}</TableCell>
                            <TableCell className="text-center">
                              <Badge className={cn("text-xs",
                                pct >= 70 ? "bg-success text-success-foreground" :
                                pct >= 50 ? "bg-warning text-warning-foreground" :
                                "bg-destructive text-destructive-foreground"
                              )}>{pct}%</Badge>
                            </TableCell>
                            <TableCell className="text-right text-xs text-muted-foreground">
                              {new Date(a.completedAt).toLocaleDateString()}
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                )}
              </div>

              {/* Homework grades */}
              <div className="space-y-3">
                <h3 className="text-sm font-semibold text-foreground flex items-center gap-2">
                  <ClipboardList className="h-4 w-4 text-primary" /> Homework Grades
                </h3>
                {selectedStudent.homeworkGrades.length === 0 ? (
                  <p className="text-sm text-muted-foreground">No homework submissions yet.</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Homework</TableHead>
                        <TableHead className="text-center">Grade</TableHead>
                        <TableHead className="text-center">Status</TableHead>
                        <TableHead className="text-right">Submitted</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {selectedStudent.homeworkGrades.map((h, i) => (
                        <TableRow key={i}>
                          <TableCell className="font-medium">{h.hwTitle}</TableCell>
                          <TableCell className="text-center">{h.grade ?? "-"}</TableCell>
                          <TableCell className="text-center">
                            <Badge variant={h.status === "graded" ? "default" : "secondary"} className="text-xs capitalize">
                              {h.status}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right text-xs text-muted-foreground">
                            {new Date(h.submittedAt).toLocaleDateString()}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Manage lessons.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
