/** PostgREST's "no rows for .single()" code — an expected result here, not a failure. */
const NO_ROWS = "PGRST116";

async function resolveTopicId(name: string): Promise<string | null> {
  if (!name.trim()) return null;
  const trimmed = name.trim();
  const { data: existing, error: lookupError } = await supabase
    .from("topics").select("id").ilike("name", trimmed).limit(1).single();
  // Anything other than "no rows" is a real failure. Swallowing it made a
  // broken lookup look like "topic not found", so the save quietly created a
  // second topic with the same name.
  if (lookupError && lookupError.code !== NO_ROWS) throw lookupError;
  if (existing) return existing.id;
  const { data: created, error: createError } = await supabase
    .from("topics").insert({ name: trimmed }).select("id").single();
  if (createError) throw createError;
  return created?.id ?? null;
}

export default function AdminLessons() {
  const { toast } = useToast();
  const [lessons, setLessons] = useState<any[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [topicName, setTopicName] = useState("");
  const [videoUrl, setVideoUrl] = useState("");
  const [sortOrder, setSortOrder] = useState(0);
  const [zoomUrl, setZoomUrl] = useState("");
  const { failure, report, clear } = useLoadFailure("lessons");

  const load = async () => {
    clear();
    const { data, error } = await supabase.from("lessons").select("*, topics(name)").order("sort_order");
    // Ignoring this showed an empty console to an admin whose request failed.
    if (error) {
      report(error);
      setLessons([]);
      return;
    }
    setLessons(data ?? []);
  };

  useEffect(() => { load(); }, []);

  const save = async () => {
    let topicId: string | null = null;
    try {
      topicId = await resolveTopicId(topicName);
    } catch (e) {
      // A topic name is guarded too, so a damaged one can be refused here.
      toast({
        title: "Could not look up that topic",
        description: contentGuardMessage(e?.message) ?? e?.message,
        variant: "destructive",
      });
      return;
    }
    const payload = { title, content, topic_id: topicId!, video_url: videoUrl || null, zoom_url: zoomUrl || null, sort_order: sortOrder };
    if (!topicId) {
      toast({ title: "Error", description: "Please enter a topic name", variant: "destructive" });
      return;
    }
    const { error } = editing
      ? await supabase.from("lessons").update(payload).eq("id", editing.id)
      : await supabase.from("lessons").insert(payload);
    // A refused save used to close the dialog and toast "Updated" anyway.
    if (error) {
      toast(contentSaveError("Could not save the lesson", error.message));
      return;
    }
    toast({ title: editing ? "Updated" : "Created" });
    setOpen(false); setEditing(null); setTitle(""); setContent(""); setTopicName(""); setVideoUrl(""); setZoomUrl(""); setSortOrder(0);
    load();
  };

  const remove = async (id: string) => {
    await supabase.from("lessons").delete().eq("id", id);
    toast({ title: "Deleted" }); load();
  };

  const openEdit = (l) => {
    setEditing(l); setTitle(l.title); setContent(l.content ?? ""); setTopicName(l.topics?.name ?? ""); setVideoUrl(l.video_url ?? ""); setZoomUrl(l.zoom_url ?? ""); setSortOrder(l.sort_order); setOpen(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div><h1 className="text-2xl font-bold tracking-tight">Lessons</h1><p className="text-muted-foreground">Manage lesson content</p></div>
        <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o) setEditing(null); }}>
          <DialogTrigger asChild><Button className="gap-2"><Plus className="h-4 w-4" /> Add Lesson</Button></DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
            <DialogHeader><DialogTitle>{editing ? "Edit" : "New"} Lesson</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Topic</Label>
                <Input value={topicName} onChange={(e) => setTopicName(e.target.value)} placeholder="e.g. Marketing, Finance, HR" />
              </div>
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} /></div>
              <div><Label>Content</Label><Textarea value={content} onChange={(e) => setContent(e.target.value)} className="min-h-[200px]" /></div>
              <div><Label>Video URL (optional)</Label><Input value={videoUrl} onChange={(e) => setVideoUrl(e.target.value)} /></div>
              <div><Label>Zoom Meeting Link (optional)</Label><Input value={zoomUrl} onChange={(e) => setZoomUrl(e.target.value)} placeholder="https://zoom.us/j/..." /></div>
              <div><Label>Sort Order</Label><Input type="number" value={sortOrder} onChange={(e) => setSortOrder(+e.target.value)} /></div>
              <Button onClick={save} className="w-full">{editing ? "Update" : "Create"}</Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
      {failure && <QueryError message={failure} onRetry={load} />}
      <div className="space-y-3">
        {lessons.map((l) => (
          <Card key={l.id} className="border-border/60 shadow-sm">
            <CardContent className="flex items-center justify-between p-4">
              <div>
                <p className="font-medium">{l.title}</p>
                <Badge variant="secondary" className="mt-1">{l.topics?.name ?? "No topic"}</Badge>
              </div>
              <div className="flex gap-2">
                <Button size="icon" variant="ghost" aria-label={`Edit ${l.title}`} title={`Edit ${l.title}`} onClick={() => openEdit(l)}><Pencil className="h-4 w-4" /></Button>
                <Button size="icon" variant="ghost" aria-label={`Delete ${l.title}`} title={`Delete ${l.title}`} onClick={() => remove(l.id)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

// Upload/manage study materials (with versioning + preview thumbnails).
//
// The `preview_url` / `page_count` / `source_range` columns have always existed
// on `study_materials` and are read by MaterialPreview on topic pages, but
// nothing ever wrote them — so every thumbnail, page count and source-range
// badge in the app was permanently blank. This form now captures them.
import { useEffect, useMemo, useState, useRef } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Plus, Pencil, Trash2, Upload, FileIcon, X } from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { Badge } from "@/components/ui/badge";
import { MaterialPreview } from "@/components/MaterialPreview";
import { deleteVersions, listVersions, recordVersion, removeStorageObjects } from "@/lib/contentFiles";
import { getSafeUploadExtension, validateUploadFile } from "@/lib/fileValidation";
import { FileVersionHistory } from "@/components/FileVersionHistory";

const UNASSIGNED = "unassigned";

interface TopicOption {
  id: string;
  name: string;
  subject_level_id: string | null;
}

export default function AdminMaterials() {
  const { toast } = useToast();
  const [materials, setMaterials] = useState<any[]>([]);
  const [topics, setTopics] = useState<TopicOption[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [topicId, setTopicId] = useState<string>(UNASSIGNED);
  const [materialType, setMaterialType] = useState("notes");
  const [file, setFile] = useState<File | null>(null);
  const [existingFileUrl, setExistingFileUrl] = useState<string | null>(null);
  const [previewFile, setPreviewFile] = useState<File | null>(null);
  const [existingPreviewUrl, setExistingPreviewUrl] = useState<string | null>(null);
  const [pageCount, setPageCount] = useState("");
  const [sourceRange, setSourceRange] = useState("");
  const [saving, setSaving] = useState(false);
  const [busyId, setBusyId] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const previewRef = useRef<HTMLInputElement>(null);

  const load = async () => {
    const [materialsRes, topicsRes] = await Promise.all([
      supabase.from("study_materials").select("*, topics(name)").order("created_at", { ascending: false }),
      supabase.from("topics").select("id, name, subject_level_id").order("name"),
    ]);
    setMaterials(materialsRes.data ?? []);
    setTopics((topicsRes.data ?? []) as TopicOption[]);
  };

  useEffect(() => { load(); }, []);

  const topicLabel = useMemo(() => {
    const map = new Map<string, string>();
    topics.forEach((t) => map.set(t.id, t.subject_level_id ? t.name : `${t.name} (no subject)`));
    return map;
  }, [topics]);

  const resetForm = () => {
    setOpen(false); setEditing(null); setTitle(""); setContent(""); setTopicId(UNASSIGNED);
    setMaterialType("notes"); setFile(null); setExistingFileUrl(null);
    setPreviewFile(null); setExistingPreviewUrl(null); setPageCount(""); setSourceRange("");
  };

  /** Upload one file into the private bucket, returning its storage path. */
  const uploadTo = async (bucket: string, folder: string, chosen: File): Promise<string> => {
    // Never interpolate a raw filename extension into a storage path.
    const ext = getSafeUploadExtension(chosen);
    if (!ext) throw new Error(`Unsupported file type for “${chosen.name}”.`);
    const path = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
    const { error } = await supabase.storage.from(bucket).upload(path, chosen);
    if (error) throw error;
    return path;
  };

  const save = async () => {
    if (!title.trim()) {
      toast({ title: "Title is required", variant: "destructive" });
      return;
    }
    setSaving(true);
    // Track uploads so a later failure can clean up what was already written.
    const uploaded: { bucket: string; path: string; slot: string; name: string }[] = [];

    try {
      let fileUrl = existingFileUrl;
      if (file) {
        const check = validateUploadFile(file);
        if ("error" in check) throw new Error(check.error);
        fileUrl = await uploadTo("study-materials", "materials", file);
        uploaded.push({ bucket: "study-materials", path: fileUrl, slot: "file", name: file.name });
      }

      let previewUrl = existingPreviewUrl;
      if (previewFile) {
        if (!previewFile.type.startsWith("image/")) {
          throw new Error("The preview thumbnail must be an image (PNG, JPG, GIF or WebP).");
        }
        previewUrl = await uploadTo("study-materials", "previews", previewFile);
        uploaded.push({ bucket: "study-materials", path: previewUrl, slot: "preview", name: previewFile.name });
      }

      const parsedPages = pageCount.trim() === "" ? null : Number(pageCount);
      if (parsedPages !== null && (!Number.isFinite(parsedPages) || parsedPages < 1)) {
        throw new Error("Page count must be a positive number.");
      }

      const payload = {
        title: title.trim(),
        content,
        topic_id: topicId === UNASSIGNED ? null : topicId,
        material_type: materialType,
        file_url: fileUrl,
        preview_url: previewUrl,
        page_count: parsedPages,
        source_range: sourceRange.trim() || null,
      };

      let materialId = editing?.id as string | undefined;
      if (editing) {
        const { error } = await supabase.from("study_materials").update(payload).eq("id", editing.id);
        if (error) throw error;
      } else {
        const { data, error } = await supabase.from("study_materials").insert(payload).select("id").single();
        if (error) throw error;
        materialId = data?.id;
      }
      if (!materialId) throw new Error("The material was saved but no id was returned.");

      // Version rows are history, not decoration — surface failures.
      for (const item of uploaded) {
        await recordVersion({
          entityType: "material",
          entityId: materialId,
          slot: item.slot,
          bucket: item.bucket,
          filePath: item.path,
          fileName: item.name,
        });
      }

      toast({ title: editing ? "Material updated" : "Material created" });
      resetForm();
      await load();
    } catch (e) {
      // Undo partial uploads so a failed save never leaves orphaned objects.
      for (const item of uploaded) {
        try {
          await removeStorageObjects(item.bucket, [item.path]);
        } catch {
          /* best effort */
        }
      }
      toast({
        title: "Could not save material",
        description: e?.message ?? "Please try again.",
        variant: "destructive",
      });
    } finally {
      setSaving(false);
    }
  };

  const removeMaterial = async (m) => {
    if (!window.confirm(`Delete “${m.title}”? Its uploaded file and version history are removed too.`)) return;
    setBusyId(m.id);
    try {
      // Collect the stored objects first: after the row is gone the version rows
      // are the only record of what was on disk.
      const versions = await listVersions("material", m.id).catch(() => []);
      const paths = versions.map((v) => v.file_path);

      const { error } = await supabase.from("study_materials").delete().eq("id", m.id);
      if (error) throw error;

      await deleteVersions("material", m.id).catch(() => undefined);
      if (m.preview_url) paths.push(m.preview_url);
      await removeStorageObjects("study-materials", paths).catch(() => undefined);

      toast({ title: "Material deleted" });
      await load();
    } catch (e) {
      toast({ title: "Delete failed", description: e?.message, variant: "destructive" });
    } finally {
      setBusyId(null);
    }
  };

  const openEdit = (m) => {
    setEditing(m);
    setTitle(m.title);
    setContent(m.content ?? "");
    setTopicId(m.topic_id ?? UNASSIGNED);
    setMaterialType(m.material_type ?? "notes");
    setExistingFileUrl(m.file_url ?? null);
    setExistingPreviewUrl(m.preview_url ?? null);
    setPageCount(m.page_count != null ? String(m.page_count) : "");
    setSourceRange(m.source_range ?? "");
    setFile(null);
    setPreviewFile(null);
    setOpen(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Study Materials</h1>
          <p className="text-muted-foreground">Manage revision content</p>
        </div>
        <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o) resetForm(); }}>
          <DialogTrigger asChild>
            <Button className="gap-2"><Plus className="h-4 w-4" /> Add Material</Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader><DialogTitle>{editing ? "Edit" : "New"} Material</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} /></div>

              <div className="grid gap-4 sm:grid-cols-2">
                <div><Label>Type</Label>
                  <Select value={materialType} onValueChange={setMaterialType}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="notes">Notes</SelectItem>
                      <SelectItem value="summary">Summary</SelectItem>
                      <SelectItem value="flashcard">Flashcard</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Topic</Label>
                  <Select value={topicId} onValueChange={setTopicId}>
                    <SelectTrigger><SelectValue placeholder="Unassigned" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value={UNASSIGNED}>Unassigned</SelectItem>
                      {topics.map((t) => (
                        <SelectItem key={t.id} value={t.id}>{topicLabel.get(t.id) ?? t.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <p className="mt-1 text-xs text-muted-foreground">
                    Topics are created in <Link to="/admin/subjects" className="text-primary underline">Admin → Subjects</Link> so
                    they always belong to a subject and level.
                  </p>
                </div>
              </div>

              <div><Label>Content</Label>
                <Textarea value={content} onChange={(e) => setContent(e.target.value)} className="min-h-[200px]" />
              </div>

              <div className="rounded-lg border p-3 space-y-3">
                <p className="text-sm font-medium">File &amp; preview</p>

                <div>
                  <Label>Material file (optional — PDF, Office, image or text)</Label>
                  <div className="mt-1 flex items-center gap-3">
                    <input ref={fileRef} type="file" className="hidden" onChange={(e) => setFile(e.target.files?.[0] ?? null)} />
                    <Button type="button" size="sm" variant="outline" onClick={() => fileRef.current?.click()} className="gap-2">
                      <Upload className="h-3 w-3" /> {file ? "Change file" : "Upload file"}
                    </Button>
                    {file && (
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <FileIcon className="h-3 w-3" />
                        <span className="truncate max-w-[180px]">{file.name}</span>
                        <button type="button" onClick={() => setFile(null)} aria-label="Remove selected file" className="inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-muted"><X className="h-3 w-3" /></button>
                      </div>
                    )}
                    {!file && existingFileUrl && <Badge variant="outline" className="gap-1"><FileIcon className="h-3 w-3" /> File attached</Badge>}
                  </div>
                </div>

                <div>
                  <Label>Preview thumbnail (optional image shown in topic lists)</Label>
                  <div className="mt-1 flex items-center gap-3">
                    <input ref={previewRef} type="file" accept="image/*" className="hidden"
                      onChange={(e) => setPreviewFile(e.target.files?.[0] ?? null)} />
                    <Button type="button" size="sm" variant="outline" onClick={() => previewRef.current?.click()} className="gap-2">
                      <Upload className="h-3 w-3" /> {previewFile ? "Change thumbnail" : "Upload thumbnail"}
                    </Button>
                    {(previewFile || existingPreviewUrl) && (
                      <MaterialPreview
                        fileUrl={existingFileUrl}
                        previewUrl={existingPreviewUrl}
                        pageCount={pageCount.trim() === "" ? null : Number(pageCount)}
                        sourceRange={sourceRange.trim() || null}
                      />
                    )}
                    {previewFile && (
                      <button type="button" onClick={() => setPreviewFile(null)} className="text-xs text-muted-foreground underline">
                        Undo new thumbnail
                      </button>
                    )}
                  </div>
                </div>

                <div className="grid gap-4 sm:grid-cols-2">
                  <div>
                    <Label>Page count (optional)</Label>
                    <Input value={pageCount} onChange={(e) => setPageCount(e.target.value)} inputMode="numeric" placeholder="e.g. 12" />
                  </div>
                  <div>
                    <Label>Source range (optional)</Label>
                    <Input value={sourceRange} onChange={(e) => setSourceRange(e.target.value)} placeholder="e.g. P1 notes p3–33" />
                  </div>
                </div>
              </div>

              <Button onClick={save} className="w-full" disabled={saving}>
                {saving ? "Saving…" : editing ? "Update" : "Create"}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      <div className="space-y-3">
        {materials.length === 0 && (
          <Card><CardContent className="py-12 text-center text-sm text-muted-foreground">No materials yet.</CardContent></Card>
        )}
        {materials.map((m) => (
          <Card key={m.id} className="border-border/60 shadow-sm">
            <CardContent className="flex flex-wrap items-center justify-between gap-3 p-4">
              <div className="flex min-w-0 items-center gap-3">
                <MaterialPreview
                  fileUrl={m.file_url}
                  previewUrl={m.preview_url}
                  pageCount={m.page_count}
                  sourceRange={m.source_range}
                  variant="compact"
                />
                <div className="min-w-0">
                  <p className="font-medium truncate">{m.title}</p>
                  <div className="mt-1 flex flex-wrap gap-2">
                    <Badge variant="secondary">{m.topics?.name ?? "General"}</Badge>
                    <Badge variant="outline" className="capitalize">{m.material_type}</Badge>
                    {m.file_url && <Badge variant="outline" className="gap-1"><FileIcon className="h-3 w-3" /> File</Badge>}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <FileVersionHistory entityType="material" entityId={m.id} onRestored={load} />
                <Button size="icon" variant="ghost" onClick={() => openEdit(m)} aria-label={`Edit ${m.title}`}>
                  <Pencil className="h-4 w-4" />
                </Button>
                <Button size="icon" variant="ghost" disabled={busyId === m.id} onClick={() => removeMaterial(m)}
                  aria-label={`Delete ${m.title}`}>
                  <Trash2 className="h-4 w-4 text-destructive" />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

// Upload/manage past papers.
//
// The archive is seeded with the board's paper list but no files, so this page
// is mostly a worklist: how many papers still need a PDF, which ones, and a way
// to attach a folder of board-downloaded PDFs in one pass instead of editing
// 378 rows by hand.
import { useMemo, useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/useToast";
import { loadFailureMessage } from "@/lib/net";
import { QueryError } from "@/components/QueryError";
import { Plus, Trash2, Pencil, FileText, FileCheck, Upload, ExternalLink, FolderUp, AlertTriangle, CheckCircle2, Check, ClipboardCheck } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { format } from "date-fns";
import { validateUploadFile, getSafeUploadExtension } from "@/lib/fileValidation";
import { matchPaperFiles, type ArchivePaper, type PaperFileMatch } from "@/lib/pastPaperFiles";
import { openSignedFile } from "@/lib/contentFiles";
import { cn } from "@/lib/utils";

const SESSIONS = ["May/June", "Oct/Nov", "Feb/Mar"];
const LEVELS = [
  { value: "OL", label: "IGCSE" },
  { value: "AS", label: "AS Level" },
  { value: "A2", label: "A2 Level" },
];
const SUBJECTS = [
  { value: "mathematics", label: "Mathematics" },
  { value: "physics", label: "Physics" },
  { value: "computer-science", label: "Computer Science" },
];
const currentYear = new Date().getFullYear();
const YEARS = Array.from({ length: 20 }, (_, i) => currentYear - i);

/** One coverage tile: how many rows have this file, out of the archive. */
function CoverageStat({
  label,
  have,
  total,
  icon: Icon,
  barClassName,
}: {
  label: string;
  have: number;
  total: number;
  icon: LucideIcon;
  barClassName?: string;
}) {
  const pct = total > 0 ? Math.round((have / total) * 100) : 0;
  return (
    <div className="rounded-lg border p-4 space-y-2">
      <div className="flex items-center justify-between">
        <span className="text-sm font-medium text-muted-foreground">{label}</span>
        <Icon className="h-4 w-4 text-muted-foreground" />
      </div>
      <div className="flex items-baseline gap-1">
        <span className="text-2xl font-bold text-foreground">{have}</span>
        <span className="text-sm text-muted-foreground">/ {total}</span>
      </div>
      <div className="h-1.5 w-full overflow-hidden rounded-full bg-muted">
        <div className={cn("h-full rounded-full bg-primary", barClassName)} style={{ width: `${pct}%` }} />
      </div>
      <p className="text-xs text-muted-foreground">{pct}% covered</p>
    </div>
  );
}

export default function AdminPastPapers() {
  const { toast } = useToast();
  const qc = useQueryClient();
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form, setForm] = useState({ title: "", year: currentYear, session: "", paper_number: "", topic_id: "", source_url: "", subject_slug: "none", level: "none" });
  const [paperFile, setPaperFile] = useState<File | null>(null);
  const [markSchemeFile, setMarkSchemeFile] = useState<File | null>(null);
  // Bulk attach (backfill) — a folder of board PDFs matched to rows by filename.
  const [bulkOpen, setBulkOpen] = useState(false);
  const [bulkMatches, setBulkMatches] = useState<{ file: File; match: PaperFileMatch }[]>([]);
  const [bulkOverrides, setBulkOverrides] = useState<Record<string, string>>({});
  const [bulkProgress, setBulkProgress] = useState<{ done: number; total: number } | null>(null);
  const [needsFileOnly, setNeedsFileOnly] = useState(false);

  // Throwing here (rather than returning `data ?? []`) is what puts React Query
  // into its error state; returning an empty array made a failed request look
  // exactly like "no papers yet".
  const { data: topics } = useQuery({
    queryKey: ["topics"],
    queryFn: async () => {
      const { data, error } = await supabase.from("topics").select("*").order("sort_order");
      if (error) throw error;
      return data ?? [];
    },
  });

  const { data: papers, isLoading, error: papersError, refetch } = useQuery({
    queryKey: ["past_papers"],
    queryFn: async () => {
      const { data, error } = await supabase.from("past_papers").select("*, topics(name)").order("year", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
  });

  // Link health comes from the recurring past-papers-harvest job: one row per
  // checked link in past_paper_link_checks, with `ok = false` meaning dead. Only
  // paper/mark-scheme rows are "the archive's links"; `candidate` rows are
  // newly-harvested sessions (not yet attached), so they are excluded here.
  const { data: linkHealth, error: linkHealthError, refetch: refetchLinkHealth } = useQuery({
    queryKey: ["past_paper_link_checks", "health"],
    queryFn: async () => {
      const [checked, brokenPapers, brokenSchemes, latest] = await Promise.all([
        supabase.from("past_paper_link_checks").select("id", { count: "exact", head: true }).in("slot", ["paper", "mark_scheme"]),
        supabase.from("past_paper_link_checks").select("id", { count: "exact", head: true }).eq("slot", "paper").eq("ok", false),
        supabase.from("past_paper_link_checks").select("id", { count: "exact", head: true }).eq("slot", "mark_scheme").eq("ok", false),
        supabase.from("past_paper_link_checks").select("checked_at").order("checked_at", { ascending: false }).limit(1).maybeSingle(),
      ]);
      const error = checked.error ?? brokenPapers.error ?? brokenSchemes.error ?? latest.error;
      if (error) throw error;
      return {
        checked: checked.count ?? 0,
        brokenPapers: brokenPapers.count ?? 0,
        brokenSchemes: brokenSchemes.count ?? 0,
        lastCheckedAt: latest.data?.checked_at ?? null,
      };
    },
  });

  // Review queue from the weekly job: newly-published sittings awaiting a
  // decision, and archive links the job found dead (not yet resolved).
  const { data: pendingCandidates } = useQuery({
    queryKey: ["past_paper_link_checks", "candidates"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("past_paper_link_checks")
        .select("id, url, host, session, year, status, ok, source_code, file_name, checked_at")
        .eq("slot", "candidate")
        .eq("review_status", "pending")
        .order("year", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
  });

  const { data: deadLinks } = useQuery({
    queryKey: ["past_paper_link_checks", "dead"],
    queryFn: async () => {
      // No embed: the checks table now has two FKs to past_papers, which makes
      // `past_papers(...)` ambiguous. Resolve the title from the papers we
      // already loaded in this page instead.
      const { data, error } = await supabase
        .from("past_paper_link_checks")
        .select("id, paper_id, url, slot, status, error, checked_at")
        .neq("slot", "candidate")
        .eq("ok", false)
        .neq("review_status", "resolved")
        .order("checked_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
  });

  const uploadFile = async (file: File, folder: string) => {
    const check = validateUploadFile(file);
    if (check.ok === false) throw new Error(check.error);
    // Never interpolate the raw filename into the storage path — use a UUID plus
    // a canonical allow-listed extension so the path can't be poisoned.
    const ext = getSafeUploadExtension(file) ?? "pdf";
    const path = `${folder}/${crypto.randomUUID()}.${ext}`;
    const { error } = await supabase.storage.from("past-papers").upload(path, file);
    if (error) throw error;
    return path;
  };

  const openSigned = async (urlOrPath: string) => {
    // Shared helper: opens external (sourced) PDFs directly, signs bucket paths.
    try {
      await openSignedFile("past-papers", urlOrPath);
    } catch (error) {
      toast({ title: "Error", description: error?.message ?? "Unable to open file", variant: "destructive" });
    }
  };

  const saveMutation = useMutation({
    mutationFn: async () => {
      let paper_url = editing?.paper_url ?? null;
      let mark_scheme_url = editing?.mark_scheme_url ?? null;

      if (paperFile) paper_url = await uploadFile(paperFile, "papers");
      if (markSchemeFile) mark_scheme_url = await uploadFile(markSchemeFile, "mark-schemes");

      const payload = {
        title: form.title,
        year: form.year,
        session: form.session || null,
        paper_number: form.paper_number || null,
        topic_id: form.topic_id || null,
        // Archive-level tagging: used when the paper isn't tied to a topic
        // (e.g. multi-year compilation PDFs on the Past Papers hub).
        subject_slug: form.subject_slug === "none" ? null : form.subject_slug,
        level: form.level === "none" ? null : (form.level as any),
        paper_url,
        mark_scheme_url,
        // Official board page — the student-facing fallback until our own
        // watermarked copy is uploaded.
        source_url: form.source_url.trim() || null,
      };

      if (editing) {
        const { error } = await supabase.from("past_papers").update(payload).eq("id", editing.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from("past_papers").insert(payload);
        if (error) throw error;
      }
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["past_papers"] });
      toast({ title: editing ? "Paper updated" : "Paper added" });
      closeDialog();
    },
    onError: (e) => toast({ title: "Error", description: e.message, variant: "destructive" }),
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("past_papers").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["past_papers"] });
      toast({ title: "Paper deleted" });
    },
  });

  // Which paper does a flagged dead link belong to? (papers are already loaded)
  const paperTitleById = useMemo(() => {
    const m = new Map<string, string>();
    for (const p of (papers ?? []) as any[]) m.set(p.id, p.title);
    return m;
  }, [papers]);

  // ---------- File coverage + bulk attach ----------
  const coverage = useMemo(() => {
    const rows = (papers ?? []) as any[];
    return {
      total: rows.length,
      papers: rows.filter((p) => p.paper_url).length,
      markSchemes: rows.filter((p) => p.mark_scheme_url).length,
      // Must mirror the `needsFileOnly` filter below exactly. The button used to
      // show `total - papers` (rows with no question paper) while the filter it
      // toggles listed every row missing *either* file, so the count never
      // matched the list it produced.
      needsFile: rows.filter((p) => !p.paper_url || !p.mark_scheme_url).length,
    };
  }, [papers]);

  const brokenTotal = (linkHealth?.brokenPapers ?? 0) + (linkHealth?.brokenSchemes ?? 0);

  // Approve/dismiss a flagged new sitting, or resolve a dead link. All three go
  // through admin-only RPCs (SECURITY DEFINER) that also audit-log the decision.
  const reviewMutation = useMutation({
    mutationFn: async ({ action, id }: { action: "approve" | "dismiss" | "resolve"; id: string }) => {
      if (action === "approve") {
        const { error } = await supabase.rpc("approve_paper_candidate", { p_check_id: id });
        if (error) throw error;
      } else if (action === "dismiss") {
        const { error } = await supabase.rpc("dismiss_paper_candidate", { p_check_id: id });
        if (error) throw error;
      } else {
        const { error } = await supabase.rpc("resolve_paper_link", { p_check_id: id });
        if (error) throw error;
      }
    },
    onSuccess: (_data, vars) => {
      qc.invalidateQueries({ queryKey: ["past_paper_link_checks"] });
      if (vars.action === "approve") qc.invalidateQueries({ queryKey: ["past_papers"] });
      toast({
        title: vars.action === "approve"
          ? "Added as a draft paper"
          : vars.action === "dismiss"
            ? "Candidate dismissed"
            : "Link marked resolved",
        description: vars.action === "approve"
          ? "Hidden from students until you attach the file and tag it."
          : undefined,
      });
    },
    onError: (e) => toast({ title: "Could not update", description: e.message, variant: "destructive" }),
  });

  const visiblePapers = useMemo(() => {
    const rows = (papers ?? []) as any[];
    return needsFileOnly ? rows.filter((p) => !p.paper_url || !p.mark_scheme_url) : rows;
  }, [papers, needsFileOnly]);

  const runBulkMatch = (files: File[]) => {
    if (files.length === 0) { setBulkMatches([]); return; }
    const rows = (papers ?? []) as ArchivePaper[];
    const matches = matchPaperFiles(files.map((f) => f.name), rows);
    setBulkMatches(files.map((file, i) => ({ file, match: matches[i] })));
    setBulkOverrides({});
  };

  const targetRow = (m: PaperFileMatch): ArchivePaper | null => {
    const override = bulkOverrides[m.file.fileName];
    if (override) return ((papers ?? []) as ArchivePaper[]).find((p) => p.id === override) ?? null;
    return m.row;
  };

  /** Upload every matched file, then write each row once (a paper and its mark scheme share a row). */
  const attachBulk = async () => {
    const pending = bulkMatches
      .map(({ file, match }) => ({ file, match, row: targetRow(match) }))
      .filter((x) => x.row) as { file: File; match: PaperFileMatch; row: ArchivePaper }[];
    if (pending.length === 0) return;

    setBulkProgress({ done: 0, total: pending.length });
    const updates = new Map<string, { paper_url?: string; mark_scheme_url?: string }>();
    let failed = 0;

    for (const [i, item] of pending.entries()) {
      // `unknown` kinds are treated as question papers — the common case.
      const isMarkScheme = item.match.file.kind === "mark_scheme";
      try {
        const path = await uploadFile(item.file, isMarkScheme ? "mark-schemes" : "papers");
        const patch = updates.get(item.row.id) ?? {};
        if (isMarkScheme) patch.mark_scheme_url = path;
        else patch.paper_url = path;
        updates.set(item.row.id, patch);
      } catch (e) {
        failed += 1;
        toast({ title: `Could not upload ${item.file.name}`, description: e?.message ?? "Upload failed", variant: "destructive" });
      }
      setBulkProgress({ done: i + 1, total: pending.length });
    }

    let saved = 0;
    for (const [id, patch] of updates) {
      const { error } = await supabase.from("past_papers").update(patch).eq("id", id);
      if (error) {
        failed += 1;
        toast({ title: "Could not save the attachment", description: error.message, variant: "destructive" });
      } else saved += 1;
    }

    qc.invalidateQueries({ queryKey: ["past_papers"] });
    const skipped = bulkMatches.length - pending.length;
    toast({
      title: saved > 0 ? "Papers attached" : "Nothing attached",
      description: `${saved} paper${saved === 1 ? "" : "s"} updated${skipped ? `, ${skipped} skipped` : ""}${failed ? `, ${failed} failed` : ""}.`,
      variant: failed && saved === 0 ? "destructive" : undefined,
    });
    setBulkProgress(null);
    setBulkMatches([]);
    if (saved > 0) setBulkOpen(false);
  };

  const openCreate = () => {
    setEditing(null);
    setForm({ title: "", year: currentYear, session: "", paper_number: "", topic_id: "", source_url: "", subject_slug: "none", level: "none" });
    setPaperFile(null);
    setMarkSchemeFile(null);
    setOpen(true);
  };

  const openEdit = (p) => {
    setEditing(p);
    setForm({ title: p.title, year: p.year, session: p.session ?? "", paper_number: p.paper_number ?? "", topic_id: p.topic_id ?? "", source_url: p.source_url ?? "", subject_slug: p.subject_slug ?? "none", level: p.level ?? "none" });
    setPaperFile(null);
    setMarkSchemeFile(null);
    setOpen(true);
  };

  const closeDialog = () => { setOpen(false); setEditing(null); };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Past Papers Bank</h1>
          <p className="text-muted-foreground text-sm">
            Upload and manage IGCSE past papers and mark schemes
            {coverage.total > 0 && (
              <>
                {" · "}
                <span className={coverage.papers === 0 ? "text-amber-600" : "text-muted-foreground"}>
                  {coverage.papers} of {coverage.total} have a question paper PDF
                </span>
                {" · "}
                <span>{coverage.markSchemes} mark schemes</span>
              </>
            )}
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button
            variant={needsFileOnly ? "default" : "outline"}
            className="gap-2"
            aria-pressed={needsFileOnly}
            onClick={() => setNeedsFileOnly((v) => !v)}
          >
            <AlertTriangle className="h-4 w-4" /> Needs a file
            {coverage.total > 0 && ` (${coverage.needsFile})`}
          </Button>
          <Button variant="outline" className="gap-2" onClick={() => { setBulkOpen(true); setBulkMatches([]); }}>
            <FolderUp className="h-4 w-4" /> Bulk attach
          </Button>
          <Button onClick={openCreate} className="gap-2"><Plus className="h-4 w-4" /> Add Paper</Button>
        </div>
      </div>

      {/* Coverage + health panel: how complete the archive is, and whether the
          weekly link check has found any dead links. */}
      <Card>
        <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-2 space-y-0">
          <div>
            <CardTitle>Archive health</CardTitle>
            <p className="mt-1 text-xs text-muted-foreground">
              {linkHealth?.lastCheckedAt
                ? `Links last checked ${format(new Date(linkHealth.lastCheckedAt), "MMM d, HH:mm")}`
                : "Links are re-checked weekly by the archive job"}
            </p>
          </div>
          {!linkHealthError && linkHealth && (
            <Badge variant={brokenTotal > 0 ? "destructive" : "secondary"} className="gap-1">
              {brokenTotal > 0 ? <AlertTriangle className="h-3 w-3" /> : <CheckCircle2 className="h-3 w-3" />}
              {brokenTotal > 0 ? `${brokenTotal} broken link${brokenTotal === 1 ? "" : "s"}` : "All links resolve"}
            </Badge>
          )}
        </CardHeader>
        <CardContent>
          {linkHealthError ? (
            <p className="text-sm text-muted-foreground">
              Couldn't load link health.{" "}
              <button type="button" className="inline-flex items-center underline underline-offset-2" onClick={() => refetchLinkHealth()}>Retry</button>
            </p>
          ) : (
            <div className="grid gap-4 sm:grid-cols-3">
              <CoverageStat label="Question papers" have={coverage.papers} total={coverage.total} icon={FileText} />
              <CoverageStat label="Mark schemes" have={coverage.markSchemes} total={coverage.total} icon={FileCheck} barClassName="bg-green-600" />
              <div className="rounded-lg border p-4 space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-sm font-medium text-muted-foreground">Broken links</span>
                  {brokenTotal > 0
                    ? <AlertTriangle className="h-4 w-4 text-destructive" />
                    : <CheckCircle2 className="h-4 w-4 text-green-600" />}
                </div>
                <div className="flex items-baseline gap-1">
                  <span className={cn("text-2xl font-bold", brokenTotal > 0 ? "text-destructive" : "text-foreground")}>
                    {linkHealth ? brokenTotal : "—"}
                  </span>
                  <span className="text-sm text-muted-foreground">of {linkHealth?.checked ?? 0} checked</span>
                </div>
                <p className="text-xs text-muted-foreground">
                  {!linkHealth
                    ? "Loading…"
                    : brokenTotal > 0
                      ? `${linkHealth.brokenPapers} paper · ${linkHealth.brokenSchemes} mark scheme`
                      : "Every checked link resolves"}
                </p>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Review queue: the weekly job flags these; an admin makes the call. */}
      <Card>
        <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-2 space-y-0">
          <div>
            <CardTitle className="flex items-center gap-2">
              <ClipboardCheck className="h-5 w-5 text-primary" /> Needs review
            </CardTitle>
            <p className="mt-1 text-xs text-muted-foreground">
              Flagged by the scheduled past-paper link check.
            </p>
          </div>
          {!!(pendingCandidates?.length || deadLinks?.length) && (
            <Badge variant="secondary">{(pendingCandidates?.length ?? 0) + (deadLinks?.length ?? 0)} open</Badge>
          )}
        </CardHeader>
        <CardContent className="space-y-6">
          {pendingCandidates === undefined && deadLinks === undefined ? (
            <p className="text-sm text-muted-foreground">Loading…</p>
          ) : !pendingCandidates?.length && !deadLinks?.length ? (
            <p className="text-sm text-muted-foreground">
              Nothing flagged — every link resolves and no new sittings were found.
            </p>
          ) : (
            <>
              {!!pendingCandidates?.length && (
                <div className="space-y-2">
                  <p className="text-sm font-medium">New sittings found ({pendingCandidates.length})</p>
                  <div className="rounded-lg border">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Paper</TableHead>
                          <TableHead>Session</TableHead>
                          <TableHead>Live</TableHead>
                          <TableHead className="text-right">Decision</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {pendingCandidates.map((c) => (
                          <TableRow key={c.id}>
                            <TableCell>
                              <p className="text-sm font-medium">
                                {c.file_name ? c.file_name.replace(/\.pdf$/i, "") : c.url}
                              </p>
                              <p className="text-xs text-muted-foreground">{c.source_code ?? c.host ?? ""}</p>
                            </TableCell>
                            <TableCell className="text-sm">{[c.session, c.year].filter(Boolean).join(" ")}</TableCell>
                            <TableCell>
                              {c.ok
                                ? <Badge variant="outline" className="text-[10px] text-green-600">Live</Badge>
                                : <Badge variant="outline" className="text-[10px] text-amber-600">{c.status ? `HTTP ${c.status}` : "Unverified"}</Badge>}
                            </TableCell>
                            <TableCell className="text-right space-x-1 whitespace-nowrap">
                              <Button
                                size="sm"
                                className="gap-1"
                                disabled={reviewMutation.isPending}
                                onClick={() => reviewMutation.mutate({ action: "approve", id: c.id })}
                              >
                                <Check className="h-3.5 w-3.5" /> Approve
                              </Button>
                              <Button
                                size="sm"
                                variant="ghost"
                                disabled={reviewMutation.isPending}
                                onClick={() => reviewMutation.mutate({ action: "dismiss", id: c.id })}
                              >
                                Dismiss
                              </Button>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Approving adds a hidden draft row (no topic/level) you can attach files to — students
                    don't see it until it's tagged.
                  </p>
                </div>
              )}

              {!!deadLinks?.length && (
                <div className="space-y-2">
                  <p className="text-sm font-medium text-destructive">Broken links ({deadLinks.length})</p>
                  <div className="rounded-lg border">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Paper</TableHead>
                          <TableHead>Slot</TableHead>
                          <TableHead>Status</TableHead>
                          <TableHead className="text-right">Action</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {deadLinks.map((l) => (
                          <TableRow key={l.id}>
                            <TableCell className="text-sm">
                              {l.paper_id ? paperTitleById.get(l.paper_id) ?? "—" : "—"}
                            </TableCell>
                            <TableCell className="text-xs capitalize">{String(l.slot).replace("_", " ")}</TableCell>
                            <TableCell className="text-xs text-destructive">
                              {l.status ? `HTTP ${l.status}` : "Unreachable"}{l.error ? ` · ${l.error}` : ""}
                            </TableCell>
                            <TableCell className="text-right">
                              <Button
                                size="sm"
                                variant="outline"
                                disabled={reviewMutation.isPending}
                                onClick={() => reviewMutation.mutate({ action: "resolve", id: l.id })}
                              >
                                Mark resolved
                              </Button>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{needsFileOnly ? "Papers still missing a file" : "All Past Papers"}</CardTitle>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <p className="text-muted-foreground text-sm">Loading…</p>
          ) : papersError ? (
            <QueryError
              message={loadFailureMessage("past papers", papersError)}
              onRetry={() => refetch()}
            />
          ) : !papers?.length ? (
            <p className="text-muted-foreground text-sm">No past papers yet.</p>
          ) : visiblePapers.length === 0 ? (
            <p className="text-muted-foreground text-sm">
              Every past paper in the archive has both files. Nice.
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Title</TableHead>
                  <TableHead>Level</TableHead>
                  <TableHead>Year</TableHead>
                  <TableHead>Session</TableHead>
                  <TableHead>Paper</TableHead>
                  <TableHead>Topic</TableHead>
                  <TableHead>Files</TableHead>
                  <TableHead>Source</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {visiblePapers.map((p) => (
                  <TableRow key={p.id}>
                    <TableCell className="font-medium">{p.title}</TableCell>
                    <TableCell>{p.level ? <Badge variant="outline" className="text-[10px] uppercase">{p.level}</Badge> : "—"}</TableCell>
                    <TableCell>{p.year}</TableCell>
                    <TableCell>{p.session ?? "—"}</TableCell>
                    <TableCell>{p.paper_number ?? "—"}</TableCell>
                    <TableCell>{p.topics?.name ? <Badge variant="secondary">{p.topics.name}</Badge> : "—"}</TableCell>
                    <TableCell className="flex gap-2">
                      {!p.paper_url && (
                        <Badge variant="outline" className="gap-1 border-amber-500/40 text-amber-600">
                          <AlertTriangle className="h-3 w-3" /> No PDF
                        </Badge>
                      )}
                      {p.paper_url && (
                        <button type="button" className="inline-flex items-center justify-center" onClick={() => openSigned(p.paper_url)}>
                          <Badge variant="outline" className="gap-1 cursor-pointer"><FileText className="h-3 w-3" /> Paper</Badge>
                        </button>
                      )}
                      {p.mark_scheme_url && (
                        <button type="button" className="inline-flex items-center justify-center" onClick={() => openSigned(p.mark_scheme_url)}>
                          <Badge variant="outline" className="gap-1 cursor-pointer text-green-600"><FileCheck className="h-3 w-3" /> MS</Badge>
                        </button>
                      )}
                    </TableCell>
                    <TableCell>
                      {p.source_url ? (
                        <a href={p.source_url} target="_blank" rel="noopener noreferrer">
                          <Badge variant="outline" className="gap-1 cursor-pointer">Official <ExternalLink className="h-3 w-3" /></Badge>
                        </a>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </TableCell>
                    <TableCell className="text-right space-x-1">
                      <Button size="icon" variant="ghost" aria-label={`Edit ${p.title}`} title={`Edit ${p.title}`} onClick={() => openEdit(p)}><Pencil className="h-4 w-4" /></Button>
                      <Button size="icon" variant="ghost" className="text-destructive" aria-label={`Delete ${p.title}`} title={`Delete ${p.title}`} onClick={() => deleteMutation.mutate(p.id)}><Trash2 className="h-4 w-4" /></Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editing ? "Edit Past Paper" : "Add Past Paper"}</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Title *</Label>
              <Input value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} placeholder="e.g. Physics 9702" />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Year *</Label>
                <Select value={String(form.year)} onValueChange={v => setForm(f => ({ ...f, year: Number(v) }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>{YEARS.map(y => <SelectItem key={y} value={String(y)}>{y}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              <div>
                <Label>Session</Label>
                <Select value={form.session} onValueChange={v => setForm(f => ({ ...f, session: v }))}>
                  <SelectTrigger><SelectValue placeholder="Select" /></SelectTrigger>
                  <SelectContent>{SESSIONS.map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Paper Number</Label>
                <Input value={form.paper_number} onChange={e => setForm(f => ({ ...f, paper_number: e.target.value }))} placeholder="e.g. Paper 1" />
              </div>
              <div>
                <Label>Topic</Label>
                <Select value={form.topic_id} onValueChange={v => setForm(f => ({ ...f, topic_id: v }))}>
                  <SelectTrigger><SelectValue placeholder="Select topic" /></SelectTrigger>
                  <SelectContent>{topics?.map(t => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Level (archive)</Label>
                <Select value={form.level} onValueChange={v => setForm(f => ({ ...f, level: v }))}>
                  <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">— none (topic-linked) —</SelectItem>
                    {LEVELS.map(l => <SelectItem key={l.value} value={l.value}>{l.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Subject (archive)</Label>
                <Select value={form.subject_slug} onValueChange={v => setForm(f => ({ ...f, subject_slug: v }))}>
                  <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">— none —</SelectItem>
                    {SUBJECTS.map(s => <SelectItem key={s.value} value={s.value}>{s.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <Label>Official source URL</Label>
              <Input
                type="url"
                value={form.source_url}
                onChange={e => setForm(f => ({ ...f, source_url: e.target.value }))}
                placeholder="https://www.cambridgeinternational.org/…/past-papers/"
              />
              <p className="text-xs text-muted-foreground mt-1">
                Shown to students as “Official papers” until a watermarked PDF is uploaded here.
              </p>
            </div>
            <div>
              <Label className="flex items-center gap-2"><Upload className="h-4 w-4" /> Question Paper (PDF)</Label>
              <Input type="file" accept=".pdf" onChange={e => setPaperFile(e.target.files?.[0] ?? null)} />
              {editing?.paper_url && !paperFile && <p className="text-xs text-muted-foreground mt-1">Current file will be kept</p>}
            </div>
            <div>
              <Label className="flex items-center gap-2"><Upload className="h-4 w-4" /> Mark Scheme (PDF)</Label>
              <Input type="file" accept=".pdf" onChange={e => setMarkSchemeFile(e.target.files?.[0] ?? null)} />
              {editing?.mark_scheme_url && !markSchemeFile && <p className="text-xs text-muted-foreground mt-1">Current file will be kept</p>}
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={closeDialog}>Cancel</Button>
            <Button onClick={() => saveMutation.mutate()} disabled={!form.title || saveMutation.isPending}>
              {saveMutation.isPending ? "Saving…" : editing ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Bulk attach: drop the PDFs straight from the board's site into the
          archive. Each filename is matched to a row by paper code, year, session
          and paper number; anything ambiguous is left for the admin to point at
          a specific row rather than guessed at. */}
      <Dialog open={bulkOpen} onOpenChange={(o) => { setBulkOpen(o); if (!o) { setBulkMatches([]); setBulkProgress(null); } }}>
        <DialogContent className="max-w-3xl max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Bulk attach papers</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label className="flex items-center gap-2"><FolderUp className="h-4 w-4" /> Select the board PDFs</Label>
              <Input
                type="file"
                accept=".pdf"
                multiple
                aria-label="Select past paper PDFs to attach in bulk"
                onChange={(e) => runBulkMatch(Array.from(e.target.files ?? []))}
              />
              <p className="text-xs text-muted-foreground mt-1">
                Filenames like <span className="font-mono">0580_s24_qp_22.pdf</span> or{" "}
                <span className="font-mono">WMA12_01_msc_20240307.pdf</span> are matched automatically
                (qp/que → question paper, ms/msc → mark scheme).
              </p>
            </div>

            {bulkMatches.length > 0 && (
              <div className="space-y-2">
                <p className="text-sm text-muted-foreground">
                  {bulkMatches.filter((m) => m.match.status === "ready").length} ready ·{" "}
                  {bulkMatches.filter((m) => m.match.status === "ambiguous").length} need a paper picked ·{" "}
                  {bulkMatches.filter((m) => m.match.status === "unmatched").length} unmatched
                </p>
                <div className="rounded-lg border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>File</TableHead>
                        <TableHead>Detected</TableHead>
                        <TableHead>Goes to</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {bulkMatches.map(({ file, match }) => {
                        const chosen = targetRow(match);
                        return (
                          <TableRow key={file.name}>
                            <TableCell className="font-mono text-xs max-w-[220px] truncate">{file.name}</TableCell>
                            <TableCell className="text-xs">
                              {match.file.kind === "mark_scheme" ? "Mark scheme" : "Question paper"}
                              {match.file.code ? ` · ${match.file.code}` : ""}
                              {match.file.paperToken ? `/${match.file.paperToken}` : ""}
                            </TableCell>
                            <TableCell>
                              {match.status === "ready" && chosen ? (
                                <span className="flex items-center gap-1 text-xs">
                                  <CheckCircle2 className="h-3 w-3 text-green-600" />
                                  <span className="truncate max-w-[260px]">{chosen.title} · {chosen.session ?? "—"} {chosen.year}</span>
                                </span>
                              ) : match.status === "ambiguous" ? (
                                <Select
                                  value={bulkOverrides[file.name] ?? ""}
                                  onValueChange={(v) => setBulkOverrides((prev) => ({ ...prev, [file.name]: v }))}
                                >
                                  <SelectTrigger className="h-8 w-full text-xs" aria-label={`Choose the paper for ${file.name}`}>
                                    <SelectValue placeholder={match.reason} />
                                  </SelectTrigger>
                                  <SelectContent>
                                    {match.candidates.map((c) => (
                                      <SelectItem key={c.id} value={c.id}>
                                        {c.title} · {c.session ?? "—"} {c.year}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                              ) : (
                                <span className="text-xs text-destructive">{match.reason}</span>
                              )}
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </div>
              </div>
            )}

            {bulkProgress && (
              <p className="text-sm text-muted-foreground">
                Uploading {bulkProgress.done} of {bulkProgress.total}…
              </p>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setBulkOpen(false); setBulkMatches([]); }}>Cancel</Button>
            <Button
              onClick={attachBulk}
              disabled={bulkProgress !== null || bulkMatches.every(({ match }) => !targetRow(match))}
            >
              {bulkProgress ? "Uploading…" : "Attach files"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Admin Payments: review subscription requests. Approving marks the sub active
// (ends_at = now + plan.months); rejecting marks it cancelled. Table updates go
// through an admin-permitted path (service role not required: admins pass RLS
// via a dedicated policy).
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { useToast } from "@/hooks/useToast";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import { format } from "date-fns";
import { Check, X, RefreshCw, Landmark, Wallet, ReceiptText, Download } from "lucide-react";

const PLAN_PRICE: Record<string, string> = { free: "—", monthly: "$40/mo", quarterly: "$72 / 3mo", annual: "$80 / yr" };

const METHOD_LABEL: Record<string, string> = {
  bank_transfer: "Bank Transfer",
  ewallet_urpay: "E-Wallet (Urpay)",
};

function MethodBadge({ method }: { method: string | null }) {
  if (!method) return <span className="text-xs text-muted-foreground">—</span>;
  const isBank = method === "bank_transfer";
  return (
    <Badge variant="outline" className="gap-1 text-[11px]">
      {isBank ? <Landmark className="h-3 w-3" /> : <Wallet className="h-3 w-3" />}
      {METHOD_LABEL[method] ?? method}
    </Badge>
  );
}

export default function AdminPayments() {
  const { toast } = useToast();
  const { role } = useAuth();
  const [rows, setRows] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const { failure, report, clear } = useLoadFailure("subscription requests");

  const load = async () => {
    setLoading(true);
    clear();
    const { data, error } = await supabase
      .from("subscriptions")
      .select("*, profiles(username, full_name, email), plans(name, months, price_monthly)")
      .order("created_at", { ascending: false })
      .limit(200);
    // A failed read rendered "No subscription requests yet.", so an admin could
    // believe nobody had paid.
    if (error) {
      report(error);
      setRows([]);
      setLoading(false);
      return;
    }
    setRows(data ?? []);
    setLoading(false);
  };
  useEffect(() => { if (role === "admin") load(); }, [role]);

  const decide = async (id: string, approve: boolean, months: number) => {
    const patch = approve
      ? { status: "active", starts_at: new Date().toISOString(), ends_at: new Date(Date.now() + months * 30 * 864e5).toISOString(), updated_at: new Date().toISOString() }
      : { status: "cancelled", updated_at: new Date().toISOString() };
    const { error } = await supabase.from("subscriptions").update(patch).eq("id", id);
    if (error) {
      toast({ title: "Update failed", description: error.message, variant: "destructive" });
      return;
    }
    toast({ title: approve ? "Subscription activated" : "Request rejected" });
    load();
  };

  if (role !== "admin") return <Card><CardContent className="p-10 text-center text-muted-foreground">Admins only.</CardContent></Card>;

  const pending = rows.filter(r => r.status === "pending_payment");

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Payments</h1>
          <p className="text-muted-foreground">Subscription requests and active plans</p>
        </div>
        <Button variant="outline" size="sm" onClick={load} className="gap-2"><RefreshCw className="h-4 w-4" /> Refresh</Button>
      </div>

      {pending.length > 0 && (
        <Card className="border-amber-500/40 bg-amber-500/5">
          <CardContent className="p-4 text-sm">
            <span className="font-medium">{pending.length} request{pending.length > 1 ? "s" : ""} awaiting confirmation</span> — verify the bank transfer, then activate.
          </CardContent>
        </Card>
      )}

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>User</TableHead>
                <TableHead>Plan</TableHead>
                <TableHead>Method</TableHead>
                <TableHead>Receipt</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Requested</TableHead>
                <TableHead>Ends</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow><TableCell colSpan={8} className="py-10 text-center text-muted-foreground">Loading…</TableCell></TableRow>
              ) : failure ? (
                <TableRow>
                  <TableCell colSpan={8} className="py-6">
                    <QueryError message={failure} onRetry={load} />
                  </TableCell>
                </TableRow>
              ) : rows.length === 0 ? (
                <TableRow><TableCell colSpan={8} className="py-10 text-center text-muted-foreground">No subscription requests yet.</TableCell></TableRow>
              ) : (
                rows.map(r => (
                  <TableRow key={r.id}>
                    <TableCell>
                      <p className="font-medium text-sm">{r.profiles?.email ?? r.profiles?.username ?? r.user_id.slice(0, 8)}</p>
                      <p className="text-xs text-muted-foreground">{r.profiles?.email}</p>
                      {r.full_name && (
                        <p className="mt-0.5 flex items-center gap-1 text-[11px] text-muted-foreground">
                          <Download className="h-3 w-3" /> {r.full_name}
                        </p>
                      )}
                    </TableCell>
                    <TableCell className="text-sm">{r.plans?.name ?? r.plan_id}<span className="block text-xs text-muted-foreground">{PLAN_PRICE[r.plan_id]}</span></TableCell>
                    <TableCell><MethodBadge method={r.payment_method ?? null} /></TableCell>
                    <TableCell>
                      {r.receipt_path ? (
                        <Button
                          size="sm"
                          variant="outline"
                          className="gap-1 text-xs"
                          onClick={async () => {
                            const { data, error } = await supabase.storage
                              .from("homework-uploads")
                              .createSignedUrl(r.receipt_path, 3600);
                            if (error || !data?.signedUrl) {
                              toast({ title: "Could not open receipt", description: error?.message, variant: "destructive" });
                              return;
                            }
                            window.open(data.signedUrl, "_blank", "noopener,noreferrer");
                          }}
                        >
                          <ReceiptText className="h-3.5 w-3.5" /> View
                        </Button>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <Badge variant="secondary" className={
                        r.status === "active" ? "bg-emerald-500/15 text-emerald-600" :
                        r.status === "pending_payment" ? "bg-amber-500/15 text-amber-600" :
                        "bg-muted text-muted-foreground"
                      }>{r.status.replace("_", " ")}</Badge>
                    </TableCell>
                    <TableCell className="text-xs">{format(new Date(r.created_at), "MMM d, HH:mm")}</TableCell>
                    <TableCell className="text-xs">{r.ends_at ? format(new Date(r.ends_at), "MMM d, yyyy") : "—"}</TableCell>
                    <TableCell className="text-right">
                      {r.status === "pending_payment" && (
                        <div className="flex justify-end gap-2">
                          <Button size="sm" variant="outline" className="gap-1 text-emerald-600" onClick={() => decide(r.id, true, r.plans?.months ?? 1)}>
                            <Check className="h-3.5 w-3.5" /> Activate
                          </Button>
                          <Button size="sm" variant="outline" className="gap-1 text-destructive" onClick={() => decide(r.id, false, 0)}>
                            <X className="h-3.5 w-3.5" /> Reject
                          </Button>
                        </div>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}

// Manage AI/topic question bank.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { useToast } from "@/hooks/useToast";
import { Database, Sparkles, Search } from "lucide-react";

export default function AdminQuestionBank() {
  const { toast } = useToast();
  const [topics, setTopics] = useState<any[]>([]);
  const [questions, setQuestions] = useState<any[]>([]);
  const [quizzes, setQuizzes] = useState<any[]>([]);
  const [filterTopic, setFilterTopic] = useState<string>("all");
  const [search, setSearch] = useState("");

  const [open, setOpen] = useState(false);
  const [pickedTopics, setPickedTopics] = useState<Record<string, boolean>>({});
  const [count, setCount] = useState(10);
  const [title, setTitle] = useState("");
  const [building, setBuilding] = useState(false);

  const load = async () => {
    const [t, q, qz] = await Promise.all([
      supabase.from("topics").select("*").order("sort_order"),
      supabase.from("questions").select("id, question_text, quiz_id, correct_option, options"),
      supabase.from("quizzes").select("id, title, topic_id"),
    ]);
    setTopics(t.data ?? []);
    setQuestions(q.data ?? []);
    setQuizzes(qz.data ?? []);
  };
  useEffect(() => { load(); }, []);

  const quizMap = new Map(quizzes.map((q) => [q.id, q]));
  const topicMap = new Map(topics.map((t) => [t.id, t.name]));

  const filtered = questions.filter((q) => {
    const quiz = quizMap.get(q.quiz_id);
    if (filterTopic !== "all" && quiz?.topic_id !== filterTopic) return false;
    if (search && !q.question_text.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  const buildQuiz = async () => {
    const topicIds = Object.entries(pickedTopics).filter(([_, v]) => v).map(([k]) => k);
    if (topicIds.length === 0 || !title.trim()) {
      toast({ title: "Pick at least one topic and enter a title", variant: "destructive" });
      return;
    }
    setBuilding(true);
    try {
      // Pool: questions whose quiz belongs to picked topics
      const pool = questions.filter((q) => {
        const qz = quizMap.get(q.quiz_id);
        return qz && topicIds.includes(qz.topic_id);
      });
      if (pool.length === 0) throw new Error("No questions found for the selected topics.");
      const picked = pool.sort(() => Math.random() - 0.5).slice(0, count);

      const { data: newQuiz, error: e1 } = await supabase.from("quizzes").insert({
        title: title.trim(),
        description: `Auto-generated from ${topicIds.length} topic(s)`,
        topic_id: topicIds[0],
        is_published: true,
      }).select().single();
      if (e1) throw e1;

      const rows = picked.map((q, i) => ({
        quiz_id: newQuiz.id,
        question_text: q.question_text,
        options: q.options,
        correct_option: q.correct_option,
        sort_order: i,
      }));
      const { error: e2 } = await supabase.from("questions").insert(rows);
      if (e2) throw e2;

      toast({ title: "Quiz built!", description: `Created "${newQuiz.title}" with ${rows.length} questions.` });
      setOpen(false);
      setTitle("");
      setPickedTopics({});
      load();
    } catch (e) {
      toast({ title: "Failed", description: e.message, variant: "destructive" });
    } finally {
      setBuilding(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Database className="h-6 w-6 text-primary" /> Question Bank
          </h1>
          <p className="text-muted-foreground">Search every question across all quizzes and auto-build new ones.</p>
        </div>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild>
            <Button className="gap-2"><Sparkles className="h-4 w-4" /> Auto-build Quiz</Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader><DialogTitle>Auto-build a new quiz</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Quiz title</Label>
                <Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Mixed Practice — Marketing" />
              </div>
              <div className="space-y-2">
                <Label>Number of questions</Label>
                <Input type="number" min={1} max={50} value={count} onChange={(e) => setCount(Number(e.target.value) || 10)} />
              </div>
              <div className="space-y-2">
                <Label>Pick topics</Label>
                <div className="max-h-48 overflow-y-auto rounded-lg border p-2 space-y-1">
                  {topics.map((t) => (
                    <label key={t.id} className="flex items-center gap-2 px-2 py-1.5 hover:bg-muted/50 rounded text-sm cursor-pointer">
                      <Checkbox
                        checked={!!pickedTopics[t.id]}
                        onCheckedChange={(v) => setPickedTopics((p) => ({ ...p, [t.id]: !!v }))}
                      />
                      {t.name}
                    </label>
                  ))}
                </div>
              </div>
            </div>
            <DialogFooter>
              <Button onClick={buildQuiz} disabled={building}>{building ? "Building…" : "Build quiz"}</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      <div className="flex gap-3 flex-wrap">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search questions…" className="pl-9" />
        </div>
        <select
          value={filterTopic}
          onChange={(e) => setFilterTopic(e.target.value)}
          className="rounded-md border border-input bg-background px-3 py-2 text-sm"
        >
          <option value="all">All topics</option>
          {topics.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
        </select>
      </div>

      <p className="text-sm text-muted-foreground">{filtered.length} question{filtered.length === 1 ? "" : "s"}</p>

      <div className="space-y-2">
        {filtered.slice(0, 100).map((q) => {
          const quiz = quizMap.get(q.quiz_id);
          const topicName = quiz ? topicMap.get(quiz.topic_id) : null;
          return (
            <Card key={q.id}>
              <CardContent className="p-4 space-y-1">
                <div className="flex items-center gap-2 flex-wrap">
                  {topicName && <Badge variant="secondary" className="text-[10px]">{topicName}</Badge>}
                  {quiz && <Badge variant="outline" className="text-[10px]">{quiz.title}</Badge>}
                </div>
                <p className="text-sm">{q.question_text}</p>
              </CardContent>
            </Card>
          );
        })}
        {filtered.length > 100 && (
          <p className="text-xs text-center text-muted-foreground">Showing first 100 of {filtered.length}. Refine your filter.</p>
        )}
      </div>
    </div>
  );
}

// Manage quizzes and questions.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Switch } from "@/components/ui/switch";
import { Plus, Pencil, Trash2, Brain, Upload } from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import { Badge } from "@/components/ui/badge";
import { getSafeUploadExtension } from "@/lib/fileValidation";
import { contentGuardMessage, contentSaveError } from "@/lib/contentGuards";
import { resolveQuizOptions } from "@/lib/quizAnswers";

export default function AdminQuizzes() {
  const { toast } = useToast();
  const [quizzes, setQuizzes] = useState<any[]>([]);
  const [topics, setTopics] = useState<any[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [topicId, setTopicId] = useState("");
  const [timeLimit, setTimeLimit] = useState<number | "">("");
  const [isPublished, setIsPublished] = useState(false);
  const [examFile, setExamFile] = useState<File | null>(null);
  const [uploadingFile, setUploadingFile] = useState(false);

  const [questionsOpen, setQuestionsOpen] = useState<string | null>(null);
  const [questions, setQuestions] = useState<any[]>([]);
  const [qText, setQText] = useState("");
  const [qOptions, setQOptions] = useState(["", "", "", ""]);
  const [qCorrect, setQCorrect] = useState(0);
  const [qExplanation, setQExplanation] = useState("");
  const { failure, report, clear } = useLoadFailure("quizzes");

  const load = async () => {
    clear();
    const [q, t] = await Promise.all([
      supabase.from("quizzes").select("*, topics(name)").order("created_at", { ascending: false }),
      supabase.from("topics").select("*").order("sort_order"),
    ]);
    // Both reads used to collapse into `?? []`, so a failed request rendered an
    // empty console with no hint anything had gone wrong.
    const error = q.error ?? t.error;
    if (error) {
      report(error);
      setQuizzes([]);
      setTopics([]);
      return;
    }
    setQuizzes(q.data ?? []);
    setTopics(t.data ?? []);
  };

  useEffect(() => { load(); }, []);

  const loadQuestions = async (quizId: string) => {
    const { data, error } = await supabase.from("questions").select("*").eq("quiz_id", quizId).order("sort_order");
    // Otherwise a failed read showed "this quiz has no questions".
    if (error) {
      report(error);
      setQuestions([]);
      setQuestionsOpen(quizId);
      return;
    }
    setQuestions(data ?? []);
    setQuestionsOpen(quizId);
  };

  const saveQuiz = async () => {
    let examFileUrl: string | null = editing?.exam_file_url ?? null;

    if (examFile) {
      setUploadingFile(true);
      const ext = getSafeUploadExtension(examFile);
      if (!ext) {
        toast({ title: "File upload blocked", description: "Unsupported file type. Allowed: PDF, Word, images.", variant: "destructive" });
        setUploadingFile(false);
        return;
      }
      const path = `${crypto.randomUUID()}.${ext}`;
      const { error: uploadErr } = await supabase.storage.from("quiz-files").upload(path, examFile);
      if (uploadErr) {
        toast({ title: "File upload failed", description: uploadErr.message, variant: "destructive" });
        setUploadingFile(false);
        return;
      }
      // Store path only (bucket is private, use signed URLs to access)
      examFileUrl = path;
      setUploadingFile(false);
    }

    const payload: any = {
      title, description, topic_id: topicId || null,
      time_limit_minutes: timeLimit || null, is_published: isPublished,
      exam_file_url: examFileUrl,
    };

    let quizId = editing?.id;
    if (editing) {
      const { error } = await supabase.from("quizzes").update(payload).eq("id", editing.id);
      // A refused update still toasted "Updated", so a title with a damaged
      // character looked saved while the database kept the old one.
      if (error) {
        toast(contentSaveError("Could not update the quiz", error.message));
        return;
      }
    } else {
      const { data, error } = await supabase.from("quizzes").insert(payload).select("id").single();
      // A failed insert still toasted "Created", leaving the admin with no quiz.
      if (error) {
        toast({ title: "Could not create the quiz", description: error.message, variant: "destructive" });
        return;
      }
      quizId = data?.id;
    }

    // If exam file was uploaded and it's a new quiz, auto-create confirmation question
    let setupWarning: string | null = null;
    if (examFileUrl && !editing && quizId) {
      const { error } = await supabase.from("questions").insert({
        quiz_id: quizId,
        question_text: "Have you completed and submitted the exam?",
        options: ["Yes, I have submitted my exam", "No, I have not submitted yet"],
        correct_option: 0,
        explanation: "Make sure you upload your solved exam file before confirming.",
        sort_order: 0,
      });
      // The quiz itself saved, so still report success — but never swallow it:
      // without this the quiz looked ready with no confirmation step.
      if (error) setupWarning = contentGuardMessage(error.message) ?? error.message;
    }

    toast(
      setupWarning
        ? {
            title: "Quiz created, but its confirmation question was not",
            description: `${setupWarning} Add it under Questions.`,
            variant: "destructive",
          }
        : { title: editing ? "Updated" : "Created" },
    );
    setOpen(false); setEditing(null); resetForm(); load();
  };

  const addQuestion = async () => {
    if (!questionsOpen || !qText.trim()) return;
    // Blank option slots are dropped before saving, which shifts every option
    // after them, so the index the form reports is not the one that belongs in
    // the row. Resolve the picked option by its text (see quizAnswers.ts).
    const resolved = resolveQuizOptions(qOptions, qCorrect);
    if (resolved.error) {
      toast({ title: "Could not add the question", description: resolved.error, variant: "destructive" });
      return;
    }
    const { options, correctOption } = resolved;
    const { error } = await supabase.from("questions").insert({
      quiz_id: questionsOpen, question_text: qText, options,
      correct_option: correctOption, explanation: qExplanation || null, sort_order: questions.length,
    });
    // Ignoring this emptied the form and claimed "Question added" for a question
    // the database had refused.
    if (error) {
      toast(contentSaveError("Could not add the question", error.message));
      return;
    }
    setQText(""); setQOptions(["", "", "", ""]); setQCorrect(0); setQExplanation("");
    loadQuestions(questionsOpen);
    toast({ title: "Question added" });
  };

  const removeQuestion = async (id: string) => {
    await supabase.from("questions").delete().eq("id", id);
    if (questionsOpen) loadQuestions(questionsOpen);
  };

  const resetForm = () => {
    setTitle(""); setDescription(""); setTopicId(""); setTimeLimit(""); setIsPublished(false); setExamFile(null);
  };

  if (questionsOpen) {
    const quiz = quizzes.find((q) => q.id === questionsOpen);
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div><h1 className="text-2xl font-bold">{quiz?.title} - Questions</h1></div>
          <Button variant="ghost" onClick={() => setQuestionsOpen(null)}>← Back</Button>
        </div>
        <Card className="neon-border bg-card">
          <CardHeader><CardTitle className="text-lg">Add Question</CardTitle></CardHeader>
          <CardContent className="space-y-4">
            <div><Label>Question</Label><Textarea value={qText} onChange={(e) => setQText(e.target.value)} className="bg-secondary/50 border-border" /></div>
            {qOptions.map((opt, i) => (
              <div key={i} className="flex items-center gap-2">
                <Label className="w-20">Option {i + 1}</Label>
                <Input value={opt} onChange={(e) => { const n = [...qOptions]; n[i] = e.target.value; setQOptions(n); }} className="bg-secondary/50 border-border" />
                <input type="radio" name="correct" checked={qCorrect === i} onChange={() => setQCorrect(i)} />
                <span className="text-xs text-muted-foreground">Correct</span>
              </div>
            ))}
            <div><Label>Explanation (optional)</Label><Textarea value={qExplanation} onChange={(e) => setQExplanation(e.target.value)} className="bg-secondary/50 border-border" /></div>
            <Button onClick={addQuestion}>Add Question</Button>
          </CardContent>
        </Card>
        {failure && questionsOpen && (
          <QueryError message={failure} onRetry={() => loadQuestions(questionsOpen)} className="mb-3" />
        )}
        <div className="space-y-3">
          {questions.map((q, i) => (
            <Card key={q.id} className="neon-border bg-card">
              <CardContent className="flex items-start justify-between p-4">
                <div>
                  <p className="font-medium">Q{i + 1}. {q.question_text}</p>
                  <div className="mt-1 space-y-0.5">
                    {(Array.isArray(q.options) ? q.options : []).map((opt: string, j: number) => (
                      <p key={j} className={`text-sm ${j === q.correct_option ? "text-primary font-medium" : "text-muted-foreground"}`}>
                        {j === q.correct_option ? "✓" : "○"} {opt}
                      </p>
                    ))}
                  </div>
                </div>
                <Button size="icon" variant="ghost" aria-label="Delete question" title="Delete question" onClick={() => removeQuestion(q.id)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div><h1 className="text-2xl font-bold tracking-tight">Quizzes</h1><p className="text-muted-foreground">Create and manage quizzes</p></div>
        <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o) { setEditing(null); resetForm(); } }}>
          <DialogTrigger asChild><Button className="gap-2 bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground glow-shadow"><Plus className="h-4 w-4" /> Add Quiz</Button></DialogTrigger>
          <DialogContent className="neon-border bg-card">
            <DialogHeader><DialogTitle>{editing ? "Edit" : "New"} Quiz</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} className="bg-secondary/50 border-border" /></div>
              <div><Label>Description</Label><Textarea value={description} onChange={(e) => setDescription(e.target.value)} className="bg-secondary/50 border-border" /></div>
              <div><Label>Topic</Label>
                <Select value={topicId} onValueChange={setTopicId}>
                  <SelectTrigger className="bg-secondary/50 border-border"><SelectValue placeholder="Select topic" /></SelectTrigger>
                  <SelectContent>{topics.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              <div><Label>Time Limit (minutes)</Label><Input type="number" value={timeLimit} onChange={(e) => setTimeLimit(+e.target.value || "")} className="bg-secondary/50 border-border" /></div>

              {/* Exam File Upload */}
              <div className="space-y-2">
                <Label>Exam File (optional)</Label>
                <div className="flex items-center gap-3">
                  <label className="flex-1 flex items-center gap-2 cursor-pointer rounded-lg border border-dashed border-border p-3 hover:border-primary/40 transition-colors bg-secondary/30">
                    <Upload className="h-4 w-4 text-muted-foreground" />
                    <span className="text-sm text-muted-foreground">{examFile ? examFile.name : "Upload exam file (PDF, DOC, etc.)"}</span>
                    <input type="file" className="hidden" onChange={(e) => setExamFile(e.target.files?.[0] ?? null)} accept=".pdf,.doc,.docx,.png,.jpg,.jpeg" />
                  </label>
                  {examFile && <Button size="sm" variant="ghost" onClick={() => setExamFile(null)}>Clear</Button>}
                </div>
                {editing?.exam_file_url && !examFile && (
                  <p className="text-xs text-muted-foreground">Current file attached. Upload a new one to replace.</p>
                )}
              </div>

              <div className="flex items-center gap-2"><Switch checked={isPublished} onCheckedChange={setIsPublished} /><Label>Published</Label></div>
              <Button onClick={saveQuiz} className="w-full bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground" disabled={uploadingFile}>
                {uploadingFile ? "Uploading…" : editing ? "Update" : "Create"}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
      {failure && <QueryError message={failure} onRetry={load} />}
      <div className="space-y-3">
        {quizzes.map((q) => (
          <Card key={q.id} className="neon-border bg-card">
            <CardContent className="flex flex-wrap items-center justify-between gap-3 p-4">
              <div className="min-w-0">
                <p className="font-medium">{q.title}</p>
                <div className="flex gap-2 mt-1">
                  <Badge variant="secondary">{(q as any).topics?.name ?? "General"}</Badge>
                  <Badge variant={q.is_published ? "default" : "outline"}>{q.is_published ? "Published" : "Draft"}</Badge>
                  {q.exam_file_url && <Badge variant="outline" className="border-primary/30 text-primary">📎 Exam File</Badge>}
                </div>
              </div>
              <div className="ml-auto flex shrink-0 gap-2">
                <Button size="sm" variant="outline" className="border-border/60 hover:border-primary/30" onClick={() => loadQuestions(q.id)}>Questions</Button>
                <Button size="icon" variant="ghost" aria-label={`Edit ${q.title}`} title={`Edit ${q.title}`} onClick={() => { setEditing(q); setTitle(q.title); setDescription(q.description ?? ""); setTopicId(q.topic_id ?? ""); setTimeLimit(q.time_limit_minutes ?? ""); setIsPublished(q.is_published); setOpen(true); }}><Pencil className="h-4 w-4" /></Button>
                <Button size="icon" variant="ghost" aria-label={`Delete ${q.title}`} title={`Delete ${q.title}`} onClick={async () => { await supabase.from("quizzes").delete().eq("id", q.id); load(); }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

// Manage subjects and levels.
import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Skeleton } from "@/components/ui/skeleton";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/useToast";
import { Plus, Pencil, Trash2, Sparkles, Layers, Loader2, GraduationCap } from "lucide-react";
import {
  subjectIcon, subjectAccent, SUBJECT_ICON_NAMES, SUBJECT_COLORS,
  LEVELS, LEVEL_LABELS, type SubjectLevelCode,
} from "@/lib/subjects";

type Level = { id: string; subject_id: string; level: SubjectLevelCode; description: string | null; is_active: boolean; sort_order: number };
type Subject = { id: string; name: string; slug: string; description: string | null; icon: string; color: string; sort_order: number; is_active: boolean };
type Topic = { id: string; name: string; description: string | null; sort_order: number; subject_level_id: string | null };

const slugify = (s: string) =>
  s.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60);

export default function AdminSubjects() {
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [levels, setLevels] = useState<Level[]>([]);
  const [topics, setTopics] = useState<Topic[]>([]);

  // subject dialog
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<Subject | null>(null);
  const [form, setForm] = useState({ name: "", slug: "", description: "", icon: "BookOpen", color: "primary", sort_order: 0, is_active: true });

  // topic dialog
  const [topicOpen, setTopicOpen] = useState(false);
  const [topicLevelId, setTopicLevelId] = useState<string | null>(null);
  const [topicName, setTopicName] = useState("");
  const [topicDesc, setTopicDesc] = useState("");

  // AI dialog
  const [aiOpen, setAiOpen] = useState(false);
  const [aiTopicId, setAiTopicId] = useState<string>("");
  const [aiCount, setAiCount] = useState(10);
  const [aiDifficulty, setAiDifficulty] = useState("medium");
  const [aiTitle, setAiTitle] = useState("");
  const [generating, setGenerating] = useState(false);

  const load = async () => {
    const [s, l, t] = await Promise.all([
      supabase.from("subjects").select("*").order("sort_order"),
      supabase.from("subject_levels").select("*").order("sort_order"),
      supabase.from("topics").select("id, name, description, sort_order, subject_level_id").order("sort_order"),
    ]);
    setSubjects((s.data as Subject[]) ?? []);
    setLevels((l.data as Level[]) ?? []);
    setTopics((t.data as Topic[]) ?? []);
    setLoading(false);
  };
  useEffect(() => { load(); }, []);

  const levelsBySubject = useMemo(() => {
    const map = new Map<string, Level[]>();
    for (const l of levels) map.set(l.subject_id, [...(map.get(l.subject_id) ?? []), l]);
    return map;
  }, [levels]);

  const topicsByLevel = useMemo(() => {
    const map = new Map<string, Topic[]>();
    for (const t of topics) {
      if (!t.subject_level_id) continue;
      map.set(t.subject_level_id, [...(map.get(t.subject_level_id) ?? []), t]);
    }
    return map;
  }, [topics]);

  const unassigned = topics.filter((t) => !t.subject_level_id);

  const resetForm = () => setForm({ name: "", slug: "", description: "", icon: "BookOpen", color: "primary", sort_order: subjects.length + 1, is_active: true });

  const saveSubject = async () => {
    if (!form.name.trim()) { toast({ title: "Name is required", variant: "destructive" }); return; }
    const payload = {
      name: form.name.trim(),
      slug: slugify(form.slug || form.name),
      description: form.description.trim() || null,
      icon: form.icon,
      color: form.color,
      sort_order: form.sort_order,
      is_active: form.is_active,
    };
    let subjectId = editing?.id;
    if (editing) {
      const { error } = await supabase.from("subjects").update(payload).eq("id", editing.id);
      if (error) { toast({ title: "Failed", description: error.message, variant: "destructive" }); return; }
    } else {
      const { data, error } = await supabase.from("subjects").insert(payload).select("id").single();
      if (error) { toast({ title: "Failed", description: error.message, variant: "destructive" }); return; }
      subjectId = data.id;
      await supabase.from("subject_levels").insert(
        LEVELS.map((level, i) => ({ subject_id: subjectId!, level, sort_order: i + 1 })),
      );
    }
    toast({ title: editing ? "Subject updated" : "Subject created" });
    setOpen(false); setEditing(null); resetForm(); load();
  };

  const removeSubject = async (s: Subject) => {
    const { error } = await supabase.from("subjects").delete().eq("id", s.id);
    if (error) { toast({ title: "Failed", description: error.message, variant: "destructive" }); return; }
    toast({ title: "Subject deleted" });
    load();
  };

  const toggleLevel = async (l: Level, active: boolean) => {
    await supabase.from("subject_levels").update({ is_active: active }).eq("id", l.id);
    setLevels((prev) => prev.map((x) => (x.id === l.id ? { ...x, is_active: active } : x)));
  };

  const saveTopic = async () => {
    if (!topicLevelId || !topicName.trim()) return;
    const { error } = await supabase.from("topics").insert({
      name: topicName.trim(),
      description: topicDesc.trim() || null,
      subject_level_id: topicLevelId,
      sort_order: (topicsByLevel.get(topicLevelId)?.length ?? 0) + 1,
    });
    if (error) { toast({ title: "Failed", description: error.message, variant: "destructive" }); return; }
    toast({ title: "Topic added" });
    setTopicOpen(false); setTopicName(""); setTopicDesc(""); load();
  };

  const assignTopic = async (topicId: string, levelId: string) => {
    await supabase.from("topics").update({ subject_level_id: levelId }).eq("id", topicId);
    toast({ title: "Topic assigned" });
    load();
  };

  const generate = async () => {
    if (!aiTopicId) { toast({ title: "Pick a topic first", variant: "destructive" }); return; }
    setGenerating(true);
    try {
      const { data, error } = await supabase.functions.invoke("generate-questions", {
        body: { topicId: aiTopicId, count: aiCount, difficulty: aiDifficulty, quizTitle: aiTitle || undefined },
      });
      if (error) throw error;
      if ((data as any)?.error) throw new Error((data as any).error);
      toast({ title: "Question bank generated", description: `${(data as any).count} questions added to "${(data as any).title}".` });
      setAiOpen(false); setAiTitle("");
    } catch (e) {
      toast({ title: "Generation failed", description: e.message ?? "Please try again.", variant: "destructive" });
    } finally {
      setGenerating(false);
    }
  };

  if (loading) return <div className="space-y-4">{[0, 1, 2].map((i) => <Skeleton key={i} className="h-40 rounded-2xl" />)}</div>;

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
            <GraduationCap className="h-6 w-6 text-primary" /> Subjects
          </h1>
          <p className="text-muted-foreground">Manage subjects, their IGCSE, AS Level and A2 Level offerings, topics and AI question banks.</p>
        </div>
        <div className="flex gap-2">
          <Dialog open={aiOpen} onOpenChange={setAiOpen}>
            <DialogTrigger asChild><Button variant="outline" className="gap-2"><Sparkles className="h-4 w-4" /> AI question bank</Button></DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>Generate an AI question bank</DialogTitle></DialogHeader>
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label>Topic</Label>
                  <Select value={aiTopicId} onValueChange={setAiTopicId}>
                    <SelectTrigger><SelectValue placeholder="Select a topic" /></SelectTrigger>
                    <SelectContent>
                      {topics.map((t) => {
                        const lvl = levels.find((l) => l.id === t.subject_level_id);
                        const subj = subjects.find((s) => s.id === lvl?.subject_id);
                        return (
                          <SelectItem key={t.id} value={t.id}>
                            {subj ? `${subj.name} ${lvl?.level} — ` : ""}{t.name}
                          </SelectItem>
                        );
                      })}
                    </SelectContent>
                  </Select>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-2">
                    <Label>Questions</Label>
                    <Input type="number" min={1} max={25} value={aiCount} onChange={(e) => setAiCount(Number(e.target.value) || 10)} />
                  </div>
                  <div className="space-y-2">
                    <Label>Difficulty</Label>
                    <Select value={aiDifficulty} onValueChange={setAiDifficulty}>
                      <SelectTrigger><SelectValue /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="easy">Easy</SelectItem>
                        <SelectItem value="medium">Medium</SelectItem>
                        <SelectItem value="hard">Hard</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Set title (optional)</Label>
                  <Input value={aiTitle} onChange={(e) => setAiTitle(e.target.value)} placeholder="Auto-named if left blank" />
                </div>
              </div>
              <DialogFooter>
                <Button onClick={generate} disabled={generating} className="gap-2">
                  {generating ? <><Loader2 className="h-4 w-4 animate-spin" /> Generating…</> : <><Sparkles className="h-4 w-4" /> Generate</>}
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>

          <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o) { setEditing(null); resetForm(); } }}>
            <DialogTrigger asChild><Button className="gap-2"><Plus className="h-4 w-4" /> Add subject</Button></DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>{editing ? "Edit" : "New"} subject</DialogTitle></DialogHeader>
              <div className="space-y-4">
                <div className="space-y-2"><Label>Name</Label>
                  <Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Chemistry" />
                </div>
                <div className="space-y-2"><Label>URL slug</Label>
                  <Input value={form.slug} onChange={(e) => setForm({ ...form, slug: e.target.value })} placeholder={slugify(form.name) || "chemistry"} />
                </div>
                <div className="space-y-2"><Label>Description</Label>
                  <Textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} />
                </div>
                <div className="grid grid-cols-3 gap-3">
                  <div className="space-y-2"><Label>Icon</Label>
                    <Select value={form.icon} onValueChange={(v) => setForm({ ...form, icon: v })}>
                      <SelectTrigger><SelectValue /></SelectTrigger>
                      <SelectContent>{SUBJECT_ICON_NAMES.map((n) => <SelectItem key={n} value={n}>{n}</SelectItem>)}</SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2"><Label>Colour</Label>
                    <Select value={form.color} onValueChange={(v) => setForm({ ...form, color: v })}>
                      <SelectTrigger><SelectValue /></SelectTrigger>
                      <SelectContent>{SUBJECT_COLORS.map((c) => <SelectItem key={c} value={c} className="capitalize">{c}</SelectItem>)}</SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2"><Label>Order</Label>
                    <Input type="number" value={form.sort_order} onChange={(e) => setForm({ ...form, sort_order: Number(e.target.value) || 0 })} />
                  </div>
                </div>
                <div className="flex items-center justify-between rounded-lg border p-3">
                  <div><p className="text-sm font-medium">Visible to students</p><p className="text-xs text-muted-foreground">Hidden subjects only show for admins.</p></div>
                  <Switch aria-label="Visible to students" checked={form.is_active} onCheckedChange={(v) => setForm({ ...form, is_active: v })} />
                </div>
              </div>
              <DialogFooter><Button onClick={saveSubject}>{editing ? "Save changes" : "Create subject"}</Button></DialogFooter>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {subjects.length === 0 && (
        <Card><CardContent className="p-10 text-center text-muted-foreground">No subjects yet — add your first one.</CardContent></Card>
      )}

      {subjects.map((s) => {
        const Icon = subjectIcon(s.icon);
        const accent = subjectAccent(s.color);
        const subjLevels = (levelsBySubject.get(s.id) ?? []).sort((a, b) => LEVELS.indexOf(a.level) - LEVELS.indexOf(b.level));
        return (
          <Card key={s.id} className={accent.border}>
            <CardHeader className="flex-row items-start justify-between gap-3 space-y-0">
              <div className="flex items-start gap-3 min-w-0">
                <div className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border ${accent.border} ${accent.bg} ${accent.text}`}>
                  <Icon className="h-5 w-5" />
                </div>
                <div className="min-w-0">
                  <CardTitle className="flex items-center gap-2">
                    {s.name}
                    {!s.is_active && <Badge variant="outline">Hidden</Badge>}
                  </CardTitle>
                  <CardDescription>/{s.slug}{s.description ? ` — ${s.description}` : ""}</CardDescription>
                </div>
              </div>
              <div className="flex gap-1 shrink-0">
                <Button size="icon" variant="ghost" aria-label={`Edit ${s.name}`} title={`Edit ${s.name}`} onClick={() => { setEditing(s); setForm({ name: s.name, slug: s.slug, description: s.description ?? "", icon: s.icon, color: s.color, sort_order: s.sort_order, is_active: s.is_active }); setOpen(true); }}>
                  <Pencil className="h-4 w-4" />
                </Button>
                <Button size="icon" variant="ghost" aria-label={`Delete ${s.name}`} title={`Delete ${s.name}`} onClick={() => removeSubject(s)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
              </div>
            </CardHeader>
            <CardContent className="grid gap-3 md:grid-cols-3">
              {subjLevels.map((l) => {
                const lvlTopics = topicsByLevel.get(l.id) ?? [];
                return (
                  <div key={l.id} className="min-w-0 rounded-xl border border-border/60 p-4 space-y-3">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="text-sm font-semibold">{LEVEL_LABELS[l.level]}</p>
                        <p className="text-[11px] text-muted-foreground">{lvlTopics.length} topic{lvlTopics.length === 1 ? "" : "s"}</p>
                      </div>
                      {/* A bare switch announces just "switch, on": name it for the
                          subject + level it actually controls. */}
                      <Switch
                        checked={l.is_active}
                        aria-label={`Show ${s.name} — ${LEVEL_LABELS[l.level]} to students`}
                        onCheckedChange={(v) => toggleLevel(l, v)}
                      />
                    </div>
                    <div className="space-y-1 max-h-40 overflow-y-auto">
                      {lvlTopics.map((t) => (
                        <div key={t.id} className="rounded-lg bg-muted/40 px-2.5 py-1.5 text-xs truncate">{t.name}</div>
                      ))}
                      {lvlTopics.length === 0 && <p className="text-xs text-muted-foreground">No topics yet.</p>}
                    </div>
                    <Button size="sm" variant="outline" className="w-full gap-1"
                      onClick={() => { setTopicLevelId(l.id); setTopicOpen(true); }}>
                      <Plus className="h-3.5 w-3.5" /> Add topic
                    </Button>
                  </div>
                );
              })}
            </CardContent>
          </Card>
        );
      })}

      {unassigned.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base"><Layers className="h-4 w-4" /> Unassigned topics</CardTitle>
            <CardDescription>Move existing topics into a subject and level.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-2">
            {unassigned.map((t) => (
              <div key={t.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border p-3">
                <p className="text-sm font-medium">{t.name}</p>
                <Select onValueChange={(v) => assignTopic(t.id, v)}>
                  <SelectTrigger className="w-[240px]"><SelectValue placeholder="Assign to subject & level" /></SelectTrigger>
                  <SelectContent>
                    {subjects.map((s) =>
                      (levelsBySubject.get(s.id) ?? []).map((l) => (
                        <SelectItem key={l.id} value={l.id}>{s.name} — {LEVEL_LABELS[l.level]}</SelectItem>
                      )),
                    )}
                  </SelectContent>
                </Select>
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      <Dialog open={topicOpen} onOpenChange={setTopicOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>New topic</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div className="space-y-2"><Label>Name</Label><Input value={topicName} onChange={(e) => setTopicName(e.target.value)} /></div>
            <div className="space-y-2"><Label>Description</Label><Textarea value={topicDesc} onChange={(e) => setTopicDesc(e.target.value)} /></div>
          </div>
          <DialogFooter><Button onClick={saveTopic}>Add topic</Button></DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Grade homework submissions.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/useToast";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from "@/components/ui/dialog";
import {
  Download, Upload, FileCheck, Loader2, ClipboardList, Brain, Eye,
} from "lucide-react";
import { getSafeUploadExtension } from "@/lib/fileValidation";

interface HWSubmission {
  id: string;
  homework_id: string;
  user_id: string;
  status: string;
  file_url: string | null;
  content: string | null;
  submitted_at: string;
  grade: string | null;
  feedback: string | null;
  correction_file_url: string | null;
  homework_title: string;
  student_name: string;
  student_username: string | null;
}

interface QuizSubmission {
  id: string;
  quiz_id: string;
  user_id: string;
  score: number | null;
  total_questions: number | null;
  completed_at: string | null;
  submission_file_url: string | null;
  correction_file_url: string | null;
  answers: any;
  quiz_title: string;
  student_name: string;
  student_username: string | null;
}

export default function AdminSubmissions() {
  const { toast } = useToast();
  const [hwSubmissions, setHwSubmissions] = useState<HWSubmission[]>([]);
  const [quizSubmissions, setQuizSubmissions] = useState<QuizSubmission[]>([]);
  const [loading, setLoading] = useState(true);
  const { failure, report, clear } = useLoadFailure("submissions");

  // Grading dialog
  const [gradeTarget, setGradeTarget] = useState<HWSubmission | null>(null);
  const [gradeValue, setGradeValue] = useState("");
  const [feedbackValue, setFeedbackValue] = useState("");
  const [correctionFile, setCorrectionFile] = useState<File | null>(null);
  const [saving, setSaving] = useState(false);

  // Quiz correction dialog
  const [quizGradeTarget, setQuizGradeTarget] = useState<QuizSubmission | null>(null);
  const [quizCorrectionFile, setQuizCorrectionFile] = useState<File | null>(null);
  const [quizSaving, setQuizSaving] = useState(false);

  const loadData = async () => {
    setLoading(true);
    clear();

    // Load homework submissions with joined data
    const { data: hwData, error: hwError } = await supabase
      .from("homework_submissions")
      .select("id, homework_id, user_id, status, file_url, content, submitted_at, grade, feedback, correction_file_url")
      .order("submitted_at", { ascending: false });

    // Load quiz attempts that have submission files
    const { data: quizData, error: quizError } = await supabase
      .from("quiz_attempts")
      .select("id, quiz_id, user_id, score, total_questions, completed_at, submission_file_url, correction_file_url, answers")
      .order("started_at", { ascending: false });

    // Both tabs used to render "nothing submitted" over a failed request.
    const loadError = hwError ?? quizError;
    if (loadError) {
      report(loadError);
      setHwSubmissions([]);
      setQuizSubmissions([]);
      setLoading(false);
      return;
    }

    // Get unique user IDs and homework/quiz IDs
    const allUserIds = [
      ...(hwData ?? []).map(s => s.user_id),
      ...(quizData ?? []).map(s => s.user_id),
    ];
    const hwIds = (hwData ?? []).map(s => s.homework_id);
    const quizIds = (quizData ?? []).map(s => s.quiz_id);

    const { data: profiles } = allUserIds.length > 0
      ? await supabase.from("profiles").select("user_id, full_name, username").in("user_id", [...new Set(allUserIds)])
      : { data: [] };

    const { data: homeworks } = hwIds.length > 0
      ? await supabase.from("homework").select("id, title").in("id", [...new Set(hwIds)])
      : { data: [] };

    const { data: quizzes } = quizIds.length > 0
      ? await supabase.from("quizzes").select("id, title").in("id", [...new Set(quizIds)])
      : { data: [] };

    const profileMap = Object.fromEntries((profiles ?? []).map(p => [p.user_id, p]));
    const hwMap = Object.fromEntries((homeworks ?? []).map(h => [h.id, h]));
    const quizMap = Object.fromEntries((quizzes ?? []).map(q => [q.id, q]));

    setHwSubmissions((hwData ?? []).map(s => ({
      ...s,
      homework_title: hwMap[s.homework_id]?.title ?? "Unknown",
      student_name: profileMap[s.user_id]?.full_name ?? "Unknown",
      student_username: profileMap[s.user_id]?.username ?? null,
    })));

    setQuizSubmissions((quizData ?? []).filter(s => s.submission_file_url).map(s => ({
      ...s,
      quiz_title: quizMap[s.quiz_id]?.title ?? "Unknown",
      student_name: profileMap[s.user_id]?.full_name ?? "Unknown",
      student_username: profileMap[s.user_id]?.username ?? null,
    })));

    setLoading(false);
  };

  useEffect(() => { loadData(); }, []);

  const downloadSignedFile = async (bucket: string, path: string) => {
    // Strip any full URL prefix — we only need the storage path
    let cleanPath = path;
    const marker = `/object/public/${bucket}/`;
    const idx = path.indexOf(marker);
    if (idx !== -1) cleanPath = path.slice(idx + marker.length);
    if (!cleanPath) {
      toast({ title: "Could not open file", description: `File path is empty after stripping the public URL prefix.`, variant: "destructive" });
      return;
    }

    const { data, error } = await supabase.storage.from(bucket).createSignedUrl(cleanPath, 3600);
    if (error || !data?.signedUrl) {
      toast({ title: "Could not open file", description: error?.message ?? "Unknown error", variant: "destructive" });
      return;
    }
    window.open(data.signedUrl, "_blank", "noopener,noreferrer");
  };

  // ── HOMEWORK GRADING ──
  const openGradeDialog = (sub: HWSubmission) => {
    setGradeTarget(sub);
    setGradeValue(sub.grade ?? "");
    setFeedbackValue(sub.feedback ?? "");
    setCorrectionFile(null);
  };

  const saveHomeworkGrade = async () => {
    if (!gradeTarget) return;
    setSaving(true);

    let correctionUrl = gradeTarget.correction_file_url;

    if (correctionFile) {
      const ext = getSafeUploadExtension(correctionFile);
      if (!ext) {
        toast({ title: "Upload blocked", description: "Unsupported file type.", variant: "destructive" });
        setSaving(false);
        return;
      }
      const path = `corrections/${gradeTarget.user_id}/${gradeTarget.homework_id}/${crypto.randomUUID()}.${ext}`;
      const { error: uploadErr } = await supabase.storage.from("homework-uploads").upload(path, correctionFile);
      if (uploadErr) {
        toast({ title: "Upload failed", description: uploadErr.message, variant: "destructive" });
        setSaving(false);
        return;
      }
      correctionUrl = path;
    }

    const { error } = await supabase
      .from("homework_submissions")
      .update({
        grade: gradeValue || null,
        feedback: feedbackValue || null,
        correction_file_url: correctionUrl,
        status: gradeValue ? "graded" : "reviewed",
        graded_at: new Date().toISOString(),
      })
      .eq("id", gradeTarget.id);

    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Saved", description: "Submission graded successfully." });
      setGradeTarget(null);
      loadData();
    }
    setSaving(false);
  };

  // ── QUIZ CORRECTION ──
  const openQuizGradeDialog = (sub: QuizSubmission) => {
    setQuizGradeTarget(sub);
    setQuizCorrectionFile(null);
  };

  const saveQuizCorrection = async () => {
    if (!quizGradeTarget) return;
    setQuizSaving(true);

    let correctionUrl = quizGradeTarget.correction_file_url;

    if (quizCorrectionFile) {
      const ext = getSafeUploadExtension(quizCorrectionFile);
      if (!ext) {
        toast({ title: "Upload blocked", description: "Unsupported file type.", variant: "destructive" });
        setQuizSaving(false);
        return;
      }
      const path = `quiz-corrections/${quizGradeTarget.user_id}/${quizGradeTarget.quiz_id}/${crypto.randomUUID()}.${ext}`;
      const { error: uploadErr } = await supabase.storage.from("homework-uploads").upload(path, quizCorrectionFile);
      if (uploadErr) {
        toast({ title: "Upload failed", description: uploadErr.message, variant: "destructive" });
        setQuizSaving(false);
        return;
      }
      correctionUrl = path;
    }

    const { error } = await supabase
      .from("quiz_attempts")
      .update({ correction_file_url: correctionUrl })
      .eq("id", quizGradeTarget.id);

    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Saved", description: "Correction file uploaded." });
      setQuizGradeTarget(null);
      loadData();
    }
    setQuizSaving(false);
  };

  const statusBadge = (status: string) => {
    const map: Record<string, string> = {
      pending: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
      graded: "bg-green-500/20 text-green-400 border-green-500/30",
      reviewed: "bg-blue-500/20 text-blue-400 border-blue-500/30",
    };
    return map[status] ?? "bg-muted text-muted-foreground";
  };

  if (loading) {
    return (
      <div className="flex justify-center py-20">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  // Say the read failed rather than showing two empty tabs.
  if (failure) {
    return <QueryError message={failure} onRetry={loadData} />;
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Student Submissions</h1>
        <p className="text-muted-foreground">Review, grade, and upload corrections for student work</p>
      </div>

      <Tabs defaultValue="homework">
        <TabsList className="bg-secondary/60">
          <TabsTrigger value="homework" className="gap-2">
            <ClipboardList className="h-4 w-4" /> Homework ({hwSubmissions.length})
          </TabsTrigger>
          <TabsTrigger value="exams" className="gap-2">
            <Brain className="h-4 w-4" /> Exam Files ({quizSubmissions.length})
          </TabsTrigger>
        </TabsList>

        {/* ── HOMEWORK TAB ── */}
        <TabsContent value="homework">
          <Card className="neon-border bg-card/80 backdrop-blur">
            <CardContent className="p-0">
              {hwSubmissions.length === 0 ? (
                <div className="flex flex-col items-center py-16 text-muted-foreground">
                  <ClipboardList className="h-12 w-12 mb-4 opacity-40" />
                  <p>No homework submissions yet</p>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Student</TableHead>
                      <TableHead>Homework</TableHead>
                      <TableHead>Submitted</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>Grade</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {hwSubmissions.map((sub) => (
                      <TableRow key={sub.id}>
                        <TableCell>
                          <div>
                            <p className="font-medium">{sub.student_name}</p>
                            {sub.student_username && (
                              <p className="text-xs text-muted-foreground">@{sub.student_username}</p>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="font-medium">{sub.homework_title}</TableCell>
                        <TableCell className="text-sm text-muted-foreground">
                          {new Date(sub.submitted_at).toLocaleDateString()}
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline" className={statusBadge(sub.status)}>
                            {sub.status}
                          </Badge>
                        </TableCell>
                        <TableCell>{sub.grade || "—"}</TableCell>
                        <TableCell className="text-right space-x-2">
                          {sub.file_url && (
                            <Button size="sm" variant="outline" className="gap-1"
                              onClick={() => downloadSignedFile("homework-uploads", sub.file_url!)}>
                              <Download className="h-3.5 w-3.5" /> File
                            </Button>
                          )}
                          {sub.correction_file_url && (
                            <Button size="sm" variant="outline" className="gap-1 text-green-400 border-green-500/30"
                              onClick={() => downloadSignedFile("homework-uploads", sub.correction_file_url!)}>
                              <FileCheck className="h-3.5 w-3.5" /> Correction
                            </Button>
                          )}
                          <Button size="sm" className="gap-1" onClick={() => openGradeDialog(sub)}>
                            <Eye className="h-3.5 w-3.5" /> Grade
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* ── EXAMS TAB ── */}
        <TabsContent value="exams">
          <Card className="neon-border bg-card/80 backdrop-blur">
            <CardContent className="p-0">
              {quizSubmissions.length === 0 ? (
                <div className="flex flex-col items-center py-16 text-muted-foreground">
                  <Brain className="h-12 w-12 mb-4 opacity-40" />
                  <p>No exam file submissions yet</p>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Student</TableHead>
                      <TableHead>Quiz / Exam</TableHead>
                      <TableHead>Completed</TableHead>
                      <TableHead>Score</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {quizSubmissions.map((sub) => (
                      <TableRow key={sub.id}>
                        <TableCell>
                          <div>
                            <p className="font-medium">{sub.student_name}</p>
                            {sub.student_username && (
                              <p className="text-xs text-muted-foreground">@{sub.student_username}</p>
                            )}
                          </div>
                        </TableCell>
